        case 'sso_ldap_login':
            // LDAP/AD 로그인
            $username = $input['username'] ?? '';
            $password = $input['password'] ?? '';
            $remember = !empty($input['remember']);
            if (empty($username) || empty($password)) {
                $result = ['success' => false, 'error' => __('login_required_fields', '사용자명과 비밀번호를 입력하세요.')];
