                }
                $activityLog->log(ActivityLog::TYPE_LOGIN, [
                    'user_id' => $verifiedUser['id'] ?? 0,
                    'username' => $verifiedUser['username'] ?? '',
                    'display_name' => $verifiedUser['display_name'] ?? $verifiedUser['username'] ?? '',
