            $result = $auth->regenerateBackupCodes((string)($input['password'] ?? ''), is_scalar($input['code'] ?? '') ? (string)($input['code'] ?? '') : '');
            break;
        
        // ===== 세션 관리 =====
        case 'sessions':
            $auth->requireLogin();
            $result = ['success' => true, 'sessions' => $auth->getSessions()];
