                $ok = $storage->removeFolderPermission($storageId, $folderPath, $userId);
                $result = $ok ? ['success' => true] : ['success' => false, 'error' => 'Remove failed'];
            } else {
                $result = ['success' => false, 'error' => __('api_err_invalid_param', '잘못된 요청입니다.')];
            }
