            if (!$storage->checkFolderPermission($storageId, fsDirOr($hlsDir, $path))) {   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                http_response_code(403);
                echo json_encode(['error' => __('api_err_no_permission', '권한이 없습니다.')]);   // ★ (2026-11-10 19:35, 67차 점검) 거부 문구 번역(종전엔 영어 'No permission' 고정 — 판정·응답 구조는 그대로)
                exit;   // ★ (2026-11-04) 55차 P2 — break 면 끝의 기본 응답이 한 번 더 붙어 JSON 두 개가 나갔음
            }
            // 오래된 HLS 세션 정리 (stop 요청 시 항상, 그 외 20% 확률)
            $hlsAction = $_GET['hls_action'] ?? 'start';
            if ($hlsAction === 'stop' || mt_rand(1, 5) === 1) {
                _sessionDebugLog('STEP:hls_cleanup_start');
                $fileManager->hlsCleanupStale();
                _sessionDebugLog('STEP:hls_cleanup_done');
            }
            _sessionDebugLog('STEP:hls_before_stream');
            $fileManager->hlsStream($storageId, $path);
            _sessionDebugLog('STEP:hls_stream_done');
            break;
        
        case 'direct_stream':
            // ★ (2026-09-30) 원본 스트리밍(탐색 가능) — mp4 를 다시 인코딩하지 않고 키프레임 경계로 잘라 HLS 로(FileManager::directStream).
            //   인증·권한은 hls_stream 과 같게: 로그인 → 세션 닫기 → 폴더 권한.
            $auth->requireLogin();
            session_write_close();
            $storageId = (int)($_GET['storage_id'] ?? 0);
            $path = $_GET['path'] ?? '';
            // ★ (2026-10-28 17:23, 소스 점검 2단계) 스토리지 읽기 권한 — 종전엔 폴더 권한만 봐서(폴더 규칙이 없으면 늘 통과) 읽기 권한이 없는 스토리지(다른 사용자의 '내 파일' 등)도 열렸음(목록·다운로드·썸네일은 이미 검사함)
            if (!$storage->checkPermission($storageId, 'can_read')) {
                http_response_code(403);
                echo json_encode(['error' => __('api_err_no_permission', '권한이 없습니다.')]);   // ★ (2026-11-10 19:35, 67차 점검) 거부 문구 번역(종전엔 영어 'No permission' 고정 — 판정·응답 구조는 그대로)
                exit;   // ★ (2026-11-04) 55차 P2 — break 면 끝의 기본 응답이 한 번 더 붙어 JSON 두 개가 나갔음
            }
            $dsDir = dirname($path);
            if ($dsDir === '.') $dsDir = '';
            if (!$storage->checkFolderPermission($storageId, fsDirOr($dsDir, $path))) {   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                http_response_code(403);
                echo json_encode(['error' => __('api_err_no_permission', '권한이 없습니다.')]);   // ★ (2026-11-10 19:35, 67차 점검) 거부 문구 번역(종전엔 영어 'No permission' 고정 — 판정·응답 구조는 그대로)
                exit;   // ★ (2026-11-04) 55차 P2 — break 면 끝의 기본 응답이 한 번 더 붙어 JSON 두 개가 나갔음
            }
            $fileManager->directStream($storageId, $path);
            break;

        case 'transcode_log':
            $auth->requireRealAdmin();   // ★ (2026-11-15 02:59, 158차) 16차 의도('관리자만')대로 실제 관리자만 — 종전 requireAdmin 은 관리 권한이 하나도 없는 부관리자에게도 남의 파일 경로가 든 기록을 보여 줬음(재현). 화면은 이 기록을 부르지 않음   // ★ (2026-10-29 03:19, 16차) 이 로그엔 다른 사용자 파일의 절대 경로가 섞일 수 있어 관리자만(종전엔 로그인만)
            session_write_close(); // 세션 락 해제
            $dataDir = defined('DATA_PATH') ? DATA_PATH : (__DIR__ . '/data');
            $logFile = $dataDir . '/ffmpeg_pipe_stderr.log';
            header('Content-Type: text/plain; charset=utf-8');
            if (is_file($logFile)) {
                echo file_get_contents($logFile);
            } else {
                echo 'No log file';
            }
            break;
        
        case 'mms_debug_log':
            $auth->requireAdmin();
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') $auth->requireRealAdmin();   // ★ (2026-11-15 02:59, 158차) 읽기·비우기는 실제 관리자만(transcode_log 와 같은 이유). 기록 추가(POST)는 종전 그대로
            $dataDir = defined('DATA_PATH') ? DATA_PATH : (__DIR__ . '/data');
            $logFile = $dataDir . '/mms_debug.log';
            if ($_SERVER['REQUEST_METHOD'] === 'POST') {
                try {
                    $log = $_POST['log'] ?? ($input['log'] ?? '');
                    if ($log) {
                        if (is_file($logFile) && filesize($logFile) > 1048576) {
                            file_put_contents($logFile, '');
                        }
                        @file_put_contents($logFile, $log . "\n", FILE_APPEND | LOCK_EX);
                    }
                } catch (Exception $e) {}
                $result = ['success' => true]; break;
            } else {
                header('Content-Type: text/plain; charset=utf-8');
                echo is_file($logFile) ? file_get_contents($logFile) : 'No MMS log';
                exit;
            }
            break;
        
        // ★ 펜닐님 진단용 (임시 — 멀티오디오 회귀 추적): 다음 디버깅 위해 보존
        //    동영상 폴더 재생 + 음악 공유 폴더 + HLS + 멀티오디오 이벤트 모두 한 로그에 기록
        //    클라이언트에서 `App._diagLog('event', {...})` 호출 시 서버 파일에 시간순 누적
        //    diag_log_clear=1 GET 파라미터로 로그 비우기 가능
        case 'hls_diag_log':
            $auth->requireLogin();
            // ★ (2026-10-29 03:19, 16차) 읽기·비우기(GET)는 관리자만 — 다른 사용자 파일 경로가 섞일 수 있음. 재생 중 기록 추가(POST)는 로그인 사용자 그대로
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') $auth->requireRealAdmin();   // ★ (2026-11-15 02:59, 158차) 읽기·비우기는 실제 관리자만 — 종전 requireAdmin 은 관리 권한 없는 부관리자도 남의 파일 경로가 든 기록을 받았음(재현). 기록 추가(POST)는 그대로
            $dataDir = defined('DATA_PATH') ? DATA_PATH : (__DIR__ . '/data');
            $logFile = $dataDir . '/hls_diag.log';
            // ★ (2026-10-29 14:33, 21차 점검) 비우기는 관리자 GET 에서만 — 종전엔 POST 에 ?clear=1 을 붙이면 관리자 확인(POST 는 건너뜀) 없이 일반 사용자도 비울 수 있었음(재현)
            if ($_SERVER['REQUEST_METHOD'] !== 'POST' && !empty($_GET['clear']) && $_GET['clear'] === '1') {
                @file_put_contents($logFile, '');
                $result = ['success' => true, 'cleared' => true]; break;
            }
            if ($_SERVER['REQUEST_METHOD'] === 'POST') {
                // ★ (2026-09-26) 묶음 전송(batch) 추가 — 기존 한 건 방식(event·data)은 그대로.
                //   [결함] 클라이언트가 기록 하나당 요청 하나를 보내, 진단 기록을 늘린 뒤(누름·가운데 버튼 등) 분당 120 공용 제한에 걸려
                //   기록이 버려지고(09-26 00:53 기록에서 자동 시작 구간 누락) 진단 중엔 평소 요청까지 제한을 받을 수 있었다.
                //   batch: JSON 배열 [{event, data}, …] — 최대 100건·전체 128KB·한 건 8KB. 줄바꿈은 공백으로(한 기록 = 한 줄).
                if (isset($_POST['batch'])) {
                    try {
                        $raw = (string)$_POST['batch'];
                        if (strlen($raw) <= 131072) {
                            $arr = json_decode($raw, true);
                            if (is_array($arr)) {
                                if (is_file($logFile) && filesize($logFile) > 5242880) @file_put_contents($logFile, '');
                                $lines = '';
                                foreach (array_slice($arr, 0, 100) as $it) {
                                    if (!is_array($it)) continue;
                                    $ev = substr(str_replace(["\r", "\n"], ' ', (string)($it['event'] ?? '')), 0, 8192);
                                    if ($ev === '') continue;
                                    $dt = substr(str_replace(["\r", "\n"], ' ', (string)($it['data'] ?? '')), 0, 8192);
                                    $lines .= '[' . date('Y-m-d H:i:s') . '] ' . $ev . ($dt !== '' ? ' | ' . $dt : '') . "\n";
                                }
                                if ($lines !== '') @file_put_contents($logFile, $lines, FILE_APPEND | LOCK_EX);
                            }
                        }
                    } catch (Exception $e) {}
                    $result = ['success' => true]; break;
                }
                try {
                    $event = $_POST['event'] ?? ($input['event'] ?? '');
                    $data = $_POST['data'] ?? ($input['data'] ?? '');
                    // ★ (2026-11-01 11:32, 39차 점검) 한 건 방식은 값을 그대로 붙여 줄바꿈으로 가짜 로그 줄을 넣을 수 있었고 길이 제한도 없었음
                    //   → batch 와 같게 글자로 바꾸고(배열은 버림) 줄바꿈은 공백, 8KB 로 자름
                    $event = is_scalar($event) ? substr(str_replace(["\r", "\n"], ' ', (string)$event), 0, 8192) : '';
                    $data = is_scalar($data) ? substr(str_replace(["\r", "\n"], ' ', (string)$data), 0, 8192) : '';
                    if ($event !== '') {
                        // 로그 5MB 초과 시 자동 비움 (펜닐님 룰: 무한 누적 방지)
                        if (is_file($logFile) && filesize($logFile) > 5242880) {
                            @file_put_contents($logFile, '');
                        }
                        $line = '[' . date('Y-m-d H:i:s') . '] ' . $event;
                        if ($data !== '') $line .= ' | ' . $data;
                        @file_put_contents($logFile, $line . "\n", FILE_APPEND | LOCK_EX);
                    }
                } catch (Exception $e) {}
                $result = ['success' => true]; break;
            } else {
                header('Content-Type: text/plain; charset=utf-8');
                echo is_file($logFile) ? file_get_contents($logFile) : 'No diag log';
                exit;
            }
            break;
        
        // ★ 커버 진단 로그 (펜닐님 임시 진단용 — iOS 음악 썸네일 누락 디버깅)
        //   GET ?clear=1 : 로그 비우기
        //   GET (기본): 로그 내용 반환 (text/plain)
        //   POST: event + data 기록
        case 'cover_diag_log':
            $auth->requireLogin();
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') $auth->requireRealAdmin();   // ★ (2026-11-15 02:59, 158차) 읽기·비우기는 실제 관리자만 — 종전 requireAdmin 은 관리 권한 없는 부관리자도 남의 파일 경로가 든 기록을 받았음(재현). 기록 추가(POST)는 그대로   // ★ (2026-10-29 03:19, 16차) 읽기·비우기는 관리자만(hls_diag_log 와 같음)
            $dataDir = defined('DATA_PATH') ? DATA_PATH : (__DIR__ . '/data');
            $logFile = $dataDir . '/cover_diag.log';
            // ★ (2026-10-29 14:33, 21차 점검) 비우기는 관리자 GET 에서만 — 종전엔 POST 에 ?clear=1 을 붙이면 관리자 확인(POST 는 건너뜀) 없이 일반 사용자도 비울 수 있었음(재현)
            if ($_SERVER['REQUEST_METHOD'] !== 'POST' && !empty($_GET['clear']) && $_GET['clear'] === '1') {
                @file_put_contents($logFile, '');
                $result = ['success' => true, 'cleared' => true]; break;
            }
            if ($_SERVER['REQUEST_METHOD'] === 'POST') {
                try {
                    $event = $_POST['event'] ?? ($input['event'] ?? '');
                    $data = $_POST['data'] ?? ($input['data'] ?? '');
                    // ★ (2026-11-01 11:32, 39차 점검) 한 건 방식은 값을 그대로 붙여 줄바꿈으로 가짜 로그 줄을 넣을 수 있었고 길이 제한도 없었음
                    //   → batch 와 같게 글자로 바꾸고(배열은 버림) 줄바꿈은 공백, 8KB 로 자름
                    $event = is_scalar($event) ? substr(str_replace(["\r", "\n"], ' ', (string)$event), 0, 8192) : '';
                    $data = is_scalar($data) ? substr(str_replace(["\r", "\n"], ' ', (string)$data), 0, 8192) : '';
                    if ($event !== '') {
                        // 로그 10MB 초과 시 자동 비움
                        if (is_file($logFile) && filesize($logFile) > 10 * 1024 * 1024) {
                            @file_put_contents($logFile, '');
                        }
                        $line = '[' . date('Y-m-d H:i:s.') . substr((string)microtime(true), -4) . '] ' . $event;
                        if ($data !== '') $line .= ' | ' . $data;
                        @file_put_contents($logFile, $line . "\n", FILE_APPEND | LOCK_EX);
                    }
                } catch (Exception $e) {}
                $result = ['success' => true]; break;
            } else {
                header('Content-Type: text/plain; charset=utf-8');
                echo is_file($logFile) ? file_get_contents($logFile) : 'No cover diag log';
                exit;
            }
            break;
        
        case 'thumbnail':
            $auth->requireLogin();
            session_write_close(); // 세션 락 해제 (그리드 뷰 썸네일 병렬 로딩)
            _sessionDebugLog('STEP:thumb_after_swc');
            // 썸네일 활성화 체크
            $thumbSettings = loadSiteSettings();
            if (isset($thumbSettings['thumbnail_enabled']) && $thumbSettings['thumbnail_enabled'] === false) {
                http_response_code(404);
                exit;
            }
            // 썸네일은 이미지 바이너리 출력이므로 에러 핸들러 변경
            restore_error_handler();
            set_error_handler(function($errno, $errstr) { return true; }); // 에러 무시
            set_exception_handler(function($e) {
                @file_put_contents(__DIR__ . '/data/thumbcache/last_error.log', date('Y-m-d H:i:s') . ' ' . $e->getMessage() . "\n" . $e->getFile() . ':' . $e->getLine() . "\n" . $e->getTraceAsString());
                http_response_code(500);
                exit;
            });
            $thumbSize = $thumbSettings['thumbnail_size'] ?? ((int)($_GET['size'] ?? 200));
            // Base64 인코딩된 경로 디코딩
            $thumbPath = $_GET['path'] ?? '';
            if (isset($_GET['enc']) && $_GET['enc'] === 'b64') {
                $thumbPath = base64_decode($thumbPath);
                if ($thumbPath === false) {
                    http_response_code(400);
                    exit;
                }
            }
            // 폴더별 권한 체크
            $thumbDir = dirname($thumbPath);
            if ($thumbDir === '.') $thumbDir = '';
            if (!$storage->checkFolderPermission((int)($_GET['storage_id'] ?? 0), fsDirOr($thumbDir, $thumbPath))) {   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                http_response_code(403);
                exit;
            }
            _sessionDebugLog('STEP:thumb_before_generate');
            $fileManager->thumbnail(
                (int)($_GET['storage_id'] ?? 0),
                $thumbPath,
                $thumbSize
            );
            _sessionDebugLog('STEP:thumb_generate_done');
            break;

        // ★ (2026-10-02) 재생바 미리보기 장면(펜닐 지시) — 목록 썸네일과 같은 순서: 로그인 → 세션 닫기 → 썸네일 사용 설정 → 폴더 권한.
        case 'video_frame':
            $auth->requireLogin();
            session_write_close();
            $vfSettings = loadSiteSettings();
            if (isset($vfSettings['thumbnail_enabled']) && $vfSettings['thumbnail_enabled'] === false) { header('X-Frame-Error: disabled'); http_response_code(404); exit; }
            restore_error_handler();
            set_error_handler(function($errno, $errstr) { return true; });   // 이미지 출력 — 경고가 본문에 섞이지 않게(썸네일과 같음)
            $vfPath = (string)($_GET['path'] ?? '');
            $vfDir = dirname($vfPath);
            if ($vfDir === '.') $vfDir = '';
            if (!$storage->checkPermission((int)($_GET['storage_id'] ?? 0), 'can_read')) { header('X-Frame-Error: perm'); http_response_code(403); exit; }   // ★ (2026-10-28 17:23, 소스 점검 2단계) 스토리지 읽기 권한 — 종전엔 폴더 권한만 봐서(폴더 규칙이 없으면 늘 통과) 읽기 권한이 없는 스토리지(다른 사용자의 '내 파일' 등)도 열렸음(목록·다운로드·썸네일은 이미 검사함)
            if (!$storage->checkFolderPermission((int)($_GET['storage_id'] ?? 0), fsDirOr($vfDir, $vfPath))) { header('X-Frame-Error: perm'); http_response_code(403); exit; }   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
            $fileManager->videoFrame((int)($_GET['storage_id'] ?? 0), $vfPath, (float)($_GET['t'] ?? 0), !empty($_GET['a']));   // a=1: 짧은 영상 정확 탐색(화면이 정함)
            break;

        // ★ (2026-10-02) 재생바 미리보기 장면 묶음(펜닐 승인) — 한 장(video_frame)과 같은 순서: 로그인 → 세션 닫기 → 썸네일 사용 설정 → 폴더 권한.
        //   ts=초,초,…(최대 20개) 의 장면을 ffmpeg 1번으로 캐시에 만들고 결과 JSON(FileManager::videoFramesFile 설명).
        case 'video_frames':
            $auth->requireLogin();
            session_write_close();
            $vfsSettings = loadSiteSettings();
            if (isset($vfsSettings['thumbnail_enabled']) && $vfsSettings['thumbnail_enabled'] === false) {
                http_response_code(404); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['error' => 'disabled']); exit;
            }
            restore_error_handler();
            set_error_handler(function($errno, $errstr) { return true; });   // JSON 출력 — 경고가 본문에 섞이지 않게
            $vfsPath = (string)($_GET['path'] ?? '');
            $vfsDir = dirname($vfsPath);
            if ($vfsDir === '.') $vfsDir = '';
            // ★ (2026-10-28 17:23, 소스 점검 2단계) 스토리지 읽기 권한 — 종전엔 폴더 권한만 봐서(폴더 규칙이 없으면 늘 통과) 읽기 권한이 없는 스토리지(다른 사용자의 '내 파일' 등)도 열렸음(목록·다운로드·썸네일은 이미 검사함)
            if (!$storage->checkPermission((int)($_GET['storage_id'] ?? 0), 'can_read')
                || !$storage->checkFolderPermission((int)($_GET['storage_id'] ?? 0), fsDirOr($vfsDir, $vfsPath))) {   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                http_response_code(403); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['error' => 'perm']); exit;
            }
            $fileManager->videoFrames((int)($_GET['storage_id'] ?? 0), $vfsPath, (string)($_GET['ts'] ?? ''), !empty($_GET['a']));
            break;

        // ★ (2026-10-09) 재생바 미리보기용 키프레임 시각 목록(펜닐 승인 — 긴 mp4 는 키프레임마다 한 장). 장면 한 장·묶음과 같은 순서:
        //   로그인 → 세션 닫기 → 썸네일 사용 설정 → 폴더 권한. 목차만 읽어 JSON(FileManager::videoKeyTimesFile) — 상태를 바꾸지 않는 GET.
        case 'video_keytimes':
            $auth->requireLogin();
            session_write_close();
            $vkSettings = loadSiteSettings();
            if (isset($vkSettings['thumbnail_enabled']) && $vkSettings['thumbnail_enabled'] === false) {
                http_response_code(404); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok' => false, 'error' => 'disabled']); exit;
            }
            restore_error_handler();
            set_error_handler(function($errno, $errstr) { return true; });   // JSON 출력 — 경고가 본문에 섞이지 않게
            $vkPath = (string)($_GET['path'] ?? '');
            $vkDir = dirname($vkPath);
            if ($vkDir === '.') $vkDir = '';
            // ★ (2026-10-28 17:23, 소스 점검 2단계) 스토리지 읽기 권한 — 종전엔 폴더 권한만 봐서(폴더 규칙이 없으면 늘 통과) 읽기 권한이 없는 스토리지(다른 사용자의 '내 파일' 등)도 열렸음(목록·다운로드·썸네일은 이미 검사함)
            if (!$storage->checkPermission((int)($_GET['storage_id'] ?? 0), 'can_read')
                || !$storage->checkFolderPermission((int)($_GET['storage_id'] ?? 0), fsDirOr($vkDir, $vkPath))) {   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                http_response_code(403); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok' => false, 'error' => 'perm']); exit;
            }
            $fileManager->videoKeyTimes((int)($_GET['storage_id'] ?? 0), $vkPath);
            break;
        
        case 'audio_cover':
            // MP3 파일의 ID3v2 APIC 프레임에서 커버 이미지 추출
            $auth->requireLogin();
            session_write_close(); // 세션 락 해제 (플레이리스트 병렬 로딩 시)
            
            // ★ 출력 버퍼 정리 + PHP/api.php 자동 캐시 헤더 제거
            //    api.php 시작에서 'Cache-Control: no-cache, no-store, must-revalidate' 설정됨
            //    session_start()도 자동으로 'Cache-Control: max-age=0, private, must-revalidate' 추가
            //    이 헤더들이 audioCover의 우리 캐시 헤더를 덮어쓰므로 명시 제거
            while (ob_get_level()) ob_end_clean();
            header_remove('Cache-Control');
            header_remove('Expires');
            header_remove('Pragma');
            
            // 에러 핸들러 변경 (바이너리 응답이므로)
            restore_error_handler();
            set_error_handler(function($errno, $errstr) { return true; });
            set_exception_handler(function($e) {
                // 관리자 디버그용 로그 (thumbnail과 동일한 형식/위치/덮어쓰기 방식)
                // 덮어쓰기: 가장 최근 에러만 유지 (로그 파일 무한 증가 방지)
                @file_put_contents(
                    __DIR__ . '/data/thumbcache/last_error.log',
                    date('Y-m-d H:i:s') . ' [audio_cover] ' . $e->getMessage() . "\n" . $e->getFile() . ':' . $e->getLine() . "\n" . $e->getTraceAsString()
                );
                http_response_code(500);
                exit;
            });
            // Base64 인코딩된 경로 디코딩 (썸네일 패턴과 동일)
            $coverPath = $_GET['path'] ?? '';
            if (isset($_GET['enc']) && $_GET['enc'] === 'b64') {
                $coverPath = base64_decode($coverPath);
                if ($coverPath === false) {
                    http_response_code(400);
                    exit;
                }
            }
            // 폴더별 권한 체크
            $coverDir = dirname($coverPath);
            if ($coverDir === '.') $coverDir = '';
            if (!$storage->checkFolderPermission((int)($_GET['storage_id'] ?? 0), fsDirOr($coverDir, $coverPath))) {   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                http_response_code(403);
                exit;
            }
            $fileManager->audioCover(
                (int)($_GET['storage_id'] ?? 0),
                $coverPath,
                // ★ (2026-09-23) &sz=512 — 줄인 커버(플레이어·잠금화면·재생목록). 캐시가 늘지 않게 512 만 허용, 없으면 원본(종전)
                ((int)($_GET['sz'] ?? 0) === 512) ? 512 : 0
            );
            break;
            
        case 'audio_lyrics':
            // 오디오 가사 (LRC > USLT > TXT 우선순위)
            $auth->requireLogin();
            session_write_close(); // 세션 락 해제 (병렬 트랙 로딩 시)
            
            // Base64 인코딩된 경로 디코딩 (audio_cover 패턴 동일)
            $lyricsPath = $_GET['path'] ?? '';
            if (isset($_GET['enc']) && $_GET['enc'] === 'b64') {
                $lyricsPath = base64_decode($lyricsPath);
                if ($lyricsPath === false) {
                    http_response_code(400);
                    exit;
                }
            }
            
            // 폴더별 권한 체크
            $lyricsDir = dirname($lyricsPath);
            if ($lyricsDir === '.') $lyricsDir = '';
            if (!$storage->checkFolderPermission((int)($_GET['storage_id'] ?? 0), fsDirOr($lyricsDir, $lyricsPath))) {   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                http_response_code(403);
                exit;
            }
            
            $lyricsResult = $fileManager->getAudioLyrics(
                (int)($_GET['storage_id'] ?? 0),
                $lyricsPath
            );
            
            // 출력 버퍼 정리 + 캐시 헤더 제거
            while (ob_get_level()) ob_end_clean();
            header_remove('Cache-Control');
            header_remove('Expires');
            header_remove('Pragma');
            
            if (!$lyricsResult) {
                http_response_code(204);  // 가사 없음 (조용히 fallback)
                header('Cache-Control: public, max-age=300');
                exit;
            }
            
            header('Content-Type: application/json; charset=utf-8');
            header('Cache-Control: public, max-age=3600');
            echo json_encode([
                'source' => $lyricsResult['source'],
                'synced' => $lyricsResult['synced'],
                'text' => $lyricsResult['text'],
                'language' => $lyricsResult['language'] ?? null,
            ], JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);   // ★ (2026-11-02 09:05, 41차 점검) 가사·언어 칸에 깨진 UTF-8(인코딩 3 표시인데 CP949, 잘린 프레임 등)이 하나라도 있으면 json_encode 가 false → 빈 본문 200 이 1시간 캐시됐음(D4#5) → 대체 문자로(share.php 와 같게). 인코딩 해석 자체는 FileManager 몫
            exit;
            
        case 'mkdir':
            $auth->requireLogin();
            // 폴더별 쓰기 권한 체크
            if (!$storage->checkFolderPermission((int)($input['storage_id'] ?? 0), $input['path'] ?? '', 'can_write')) {
                $result = ['success' => false, 'error' => __('no_write_permission', '쓰기 권한이 없습니다.')]; break;
            }
            $result = $fileManager->createFolder(
                (int)($input['storage_id'] ?? 0),
                $input['path'] ?? '',
                $input['name'] ?? ''
            );
            if ($result['success'] ?? false) {
                $storageInfo = $storage->getStorageById((int)($input['storage_id'] ?? 0));
                $activityLog->log(ActivityLog::TYPE_CREATE_FOLDER, [
                    'storage_id' => (int)($input['storage_id'] ?? 0),
                    'storage_name' => $storageInfo['name'] ?? '',
                    'path' => ($input['path'] ?? '') . '/' . ($input['name'] ?? ''),
                    'filename' => $input['name'] ?? ''
                ]);
                
                // 인덱스 갱신
                $fileIndex = FileIndex::getInstance();
                if ($fileIndex->isAvailable()) {
                        $storageId = (int)($input['storage_id'] ?? 0);
                        // ★ (2026-10-29 22:39, 24차 점검) 서버가 정리한 실제 이름($result['name'])으로 — 종전엔 입력 이름('보고서.')으로 넣어 실제 폴더('보고서')와 다른 유령 행이 생겼음(2회차 재검토)
                        $filepath = trim(($input['path'] ?? '') . '/' . ($result['name'] ?? ($input['name'] ?? '')), '/');
                        $fileIndex->addFile($storageId, $filepath, [
                            'name' => $input['name'] ?? '',
                            'size' => 0,
                            'modified' => time(),
                            'is_dir' => true
                        ]);
                }
            }
            break;
            
        // ★ 새 파일 만들기 — 서버 템플릿 복사 (펜닐 v5.8.1e)
        //   docx/xlsx/pptx/hwp 빈 템플릿 복사 (파일 내용 자체는 templates/ 디렉토리)
        //   txt/md는 클라이언트에서 빈 Blob → upload API 사용 (이 액션 X)
        case 'create_from_template':
            $auth->requireLogin();
            $storageId = (int)($input['storage_id'] ?? 0);
            $relativePath = $input['path'] ?? '';
            $fileName = $input['name'] ?? '';
            $template = $input['template'] ?? '';
            
            // 폴더별 쓰기 권한 체크
            // ★ (2026-10-28 19:55, 6차 점검) 스토리지 권한도 확인 — 종전엔 폴더 권한(규칙이 없으면 통과)만 봐서 남의 홈 스토리지에 쓰거나 내려받을 수 있었음(재현)
            if (!$storage->checkPermission($storageId, 'can_write') || !$storage->checkFolderPermission($storageId, $relativePath, 'can_write')) {
                $result = ['success' => false, 'error' => __('no_write_permission', '쓰기 권한이 없습니다.')]; break;
            }
            
            // 허용된 템플릿만 처리 (whitelist)
            $allowedTemplates = ['docx', 'xlsx', 'pptx', 'hwp'];
            if (!in_array($template, $allowedTemplates, true)) {
                $result = ['success' => false, 'error' => 'Invalid template type']; break;
            }
            
            // 파일명 보안 검사
            // ★ (2026-11-01 11:32, 39차 점검) 제어 문자(\x00-\x1f·\x7f)를 보지 않아 줄바꿈 든 파일 이름이 만들어졌음 → 정규식에 넣음
            if (!is_string($fileName) || $fileName === '' || preg_match('/[\\\\\\/:\*\?"<>\|\x00-\x1f\x7f]/', $fileName) || strpos($fileName, '..') !== false || $fileName[0] === '.') {   // ★ (2026-11-01 17:27, 40차 점검) 이름 '0'(→ '0.docx' 등)이 empty 로 거부되던 것을 === '' 로
                $result = ['success' => false, 'error' => __('invalid_filename', '파일 이름이 잘못되었습니다.')]; break;
            }
            // ★ (2026-10-29 23:24, 24차 점검) 서버에서 실행될 수 있는 이름('x.php.hwp' 등) 거부 — 업로드·이름 바꾸기·텍스트 저장·rhwp 다른 이름 저장과 같은 기준(3회차 재검토: 이 경로만 빠졌음)
            if ($__execReason = fsServerExecReason($fileName . '.' . $template)) {
                $result = ['success' => false, 'error' => $__execReason]; break;
            }
            
            // 확장자 일치 검사
            $expectedExt = '.' . $template;
            if (substr(strtolower($fileName), -strlen($expectedExt)) !== $expectedExt) {
                $fileName .= $expectedExt;
            }
            // ★ (2026-11-04 01:36, 54차 점검) Windows 장치 이름(CON·NUL·COM1 …)은 앞에 '_' — 업로드·새 폴더·이름 바꾸기(sanitizeFilename, 40차)와 같은 방식. 이 경로만 빠져 'con.docx' 가 장치로 열렸음(정적 확인). Linux·보통 이름은 그대로
            if (DIRECTORY_SEPARATOR === '\\' && preg_match('/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(\.|$)/i', rtrim($fileName, ' .'))) $fileName = '_' . $fileName;
            
            // 템플릿 파일 경로 확인
            $templatePath = __DIR__ . '/templates/empty.' . $template;
            if (!is_file($templatePath)) {
                $result = ['success' => false, 'error' => 'Template file not found: ' . $template]; break;
            }
            
            // ★ Quota 검사 (펜닐 v5.8.1e — 일반 업로드와 동일하게 한도 체크)
            //   템플릿 파일 사이즈는 4~36KB로 작지만, 한도 도달 사용자가 무한 생성 못하도록 차단
            $_templateSize = filesize($templatePath);
            if ($_templateSize !== false) {
                $_quotaCheck = $fileManager->checkQuotaPublic($storageId, $_templateSize);
                if (!($_quotaCheck['allowed'] ?? true)) {
                    $result = ['success' => false, 'error' => $_quotaCheck['error'] ?? __('quota_exceeded', '용량 한도를 초과했습니다.')]; break;
                }
            }
            
            // 대상 경로 결정
            $basePath = $storage->getRealPath($storageId);
            if (empty($basePath) && !$fileManager->isRemoteStorage($storageId)) {
                $result = ['success' => false, 'error' => __('storage_path_invalid', '스토리지 경로가 잘못되었습니다.')]; break;
            }
            
            // 원격 스토리지면 어댑터 사용 (어댑터의 write 메서드)
            if ($fileManager->isRemoteStorage($storageId)) {
                $storageInfo = $storage->getStorageById($storageId);
                $adapter = StorageAdapterFactory::create($storageInfo);
                if (!$adapter || !$adapter->connect()) {
                    $result = ['success' => false, 'error' => __('adapter_connect_failed', '원격 스토리지 연결 실패')]; break;
                }
                // ★ Windows 탐색기 방식: 중복 시 (2), (3) 자동 증가 (펜닐 v5.8.1e)
                $remoteFullPath = ltrim($relativePath . '/' . $fileName, '/');
                if ($adapter->exists($remoteFullPath)) {
                    // 확장자 분리해서 (n) 추가
                    $dotPos = strrpos($fileName, '.');
                    $namePart = $dotPos !== false ? substr($fileName, 0, $dotPos) : $fileName;
                    $extPart  = $dotPos !== false ? substr($fileName, $dotPos) : '';
                    // 이미 (n) 패턴 있으면 그 부분 제거 후 새로 시도
                    $namePart = preg_replace('/ \(\d+\)$/u', '', $namePart);
                    for ($n = 2; $n <= 999; $n++) {
                        $tryName = $namePart . ' (' . $n . ')' . $extPart;
                        $tryRemote = ltrim($relativePath . '/' . $tryName, '/');
                        if (!$adapter->exists($tryRemote)) {
                            $fileName = $tryName;
                            $remoteFullPath = $tryRemote;
                            break;
                        }
                    }
                    if ($adapter->exists($remoteFullPath)) {
                        $adapter->disconnect();
                        $result = ['success' => false, 'error' => __('file_already_exists', '같은 이름의 파일이 너무 많습니다.')]; break;
                    }
                }
                $templateContent = file_get_contents($templatePath);
                $writeOk = $adapter->write($remoteFullPath, $templateContent);
                $adapter->disconnect();
                if (!$writeOk) {
                    $result = ['success' => false, 'error' => __('error_create_file', '파일 생성에 실패했습니다.')]; break;
                }
                $result = ['success' => true, 'name' => $fileName];
            } else {
                // 로컬 (또는 UNC + local 등록): 직접 복사
                $targetDir = $basePath . DIRECTORY_SEPARATOR . str_replace(['/', '\\'], DIRECTORY_SEPARATOR, $relativePath);
                $targetFullPath = rtrim($targetDir, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR . $fileName;
                
                // path traversal 방어
                $realBase = realpath($basePath);
                $realTargetDir = realpath($targetDir);
                // ★ (2026-10-31 12:03, 34차 전체 점검) 앞부분 글자 비교라 'user1' 기준에 'user10' 도 통과 — 다른 곳과 같은 isSubPath 로
                if ($realBase && $realTargetDir && $realTargetDir !== $realBase && !isSubPath($realTargetDir, $realBase)) {
                    $result = ['success' => false, 'error' => __('api_err_invalid_path', '잘못된 경로입니다.')]; break;
                }
                
                // ★ Windows 탐색기 방식: 중복 시 (2), (3) 자동 증가 (펜닐 v5.8.1e)
                if (file_exists($targetFullPath)) {
                    $dotPos = strrpos($fileName, '.');
                    $namePart = $dotPos !== false ? substr($fileName, 0, $dotPos) : $fileName;
                    $extPart  = $dotPos !== false ? substr($fileName, $dotPos) : '';
                    $namePart = preg_replace('/ \(\d+\)$/u', '', $namePart);
                    for ($n = 2; $n <= 999; $n++) {
                        $tryName = $namePart . ' (' . $n . ')' . $extPart;
                        $tryFull = rtrim($targetDir, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR . $tryName;
                        if (!file_exists($tryFull)) {
                            $fileName = $tryName;
                            $targetFullPath = $tryFull;
                            break;
                        }
                    }
                    if (file_exists($targetFullPath)) {
                        $result = ['success' => false, 'error' => __('file_already_exists', '같은 이름의 파일이 너무 많습니다.')]; break;
                    }
                }
                
                // ★ (2026-11-04) 55차 U3 — 이름을 고른 뒤 copy() 가 그사이 같은 이름으로 올라온 파일을 덮어썼음 → 업로드처럼 fopen('x') 로 자리를 먼저 잡고(이미 생겼으면 다음 이름) 그 자리에 copy
                $tplFh = @fopen($targetFullPath, 'x');
                if ($tplFh === false && file_exists($targetFullPath)) {
                    $dotPos = strrpos($fileName, '.');
                    $namePart = preg_replace('/ \(\d+\)$/u', '', $dotPos !== false ? substr($fileName, 0, $dotPos) : $fileName);
                    $extPart  = $dotPos !== false ? substr($fileName, $dotPos) : '';
                    for ($n = 2; $n <= 999 && $tplFh === false; $n++) {
                        $tryName = $namePart . ' (' . $n . ')' . $extPart;
                        $tryFull = rtrim($targetDir, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR . $tryName;
                        $tplFh = @fopen($tryFull, 'x');
                        if ($tplFh !== false) { $fileName = $tryName; $targetFullPath = $tryFull; }
                    }
                }
                if ($tplFh === false) {
                    $result = ['success' => false, 'error' => __('error_create_file', '파일 생성에 실패했습니다.')]; break;
                }
                fclose($tplFh);
                if (!@copy($templatePath, $targetFullPath)) {
                    @unlink($targetFullPath);
                    $result = ['success' => false, 'error' => __('error_create_file', '파일 생성에 실패했습니다.')]; break;
                }

                $result = ['success' => true, 'name' => $fileName];
            }
            
            // 활동 로그 + 인덱스 갱신
            // ★ (2026-10-29 18:02, 22차 점검) 만든 파일 크기만큼 사용량 반영(위에서 용량 확인은 하는데 반영이 빠져 있었음)
            if (($result['success'] ?? false) && !empty($_templateSize)) $storage->updateUsedSize($storageId, (int)$_templateSize);
            if ($result['success'] ?? false) {
                $storageInfo2 = $storage->getStorageById($storageId);
                $activityLog->log(ActivityLog::TYPE_UPLOAD ?? 'upload', [
                    'storage_id' => $storageId,
                    'storage_name' => $storageInfo2['name'] ?? '',
                    'path' => trim($relativePath . '/' . $fileName, '/'),
                    'filename' => $fileName,
                    'note' => 'created from template: ' . $template
                ]);
                
                $fileIndex2 = FileIndex::getInstance();
                if ($fileIndex2->isAvailable()) {
                    $filepath2 = trim($relativePath . '/' . $fileName, '/');
                    $fileIndex2->addFile($storageId, $filepath2, [
                        'name' => $fileName,
                        'size' => filesize($templatePath),
                        'modified' => time(),
                        'is_dir' => false
                    ]);
                }
            }
            break;
            
        case 'delete':
            $auth->requireLogin();
            $storageId = (int)($input['storage_id'] ?? 0);
            $path = $input['path'] ?? '';
            
            // 빈 경로 삭제 차단 (스토리지 루트 삭제 방지)
