                while (isset($mdUsedTop[mb_strtolower($cand)])) {
                    if (!$isDir && ($dot = strrpos($name, '.')) > 0) $cand = substr($name, 0, $dot) . " ($n)" . substr($name, $dot);
                    else $cand = $name . " ($n)";
                    $n++;
                }
                $mdUsedTop[mb_strtolower($cand)] = true;
                return $cand;
            };
