                $iuShare = $db->find('internal_shares', ['id' => (int)($input['id'] ?? 0)]);
                if ($iuShare && (int)($iuShare['shared_by'] ?? 0) === (int)$auth->getUserId() && ($iuPerm === 'write' || $iuPerm === 'full')) {
