            $withMeCount = 0;
            $byMeCount = 0;
            $totalCount = 0;
            foreach (is_array($allShares) ? $allShares : [] as $s) {
                $totalCount++;
                if ((int)($s['shared_with'] ?? 0) === $userId) $withMeCount++;
                if ((int)($s['shared_by'] ?? 0) === $userId) $byMeCount++;
            }
            $result = [
