                ],
                'mbstring' => [
                    'loaded' => extension_loaded('mbstring'),
                    'required' => true,
                    'desc' => __('ext_desc_mbstring', '다국어 문자열 처리')
                ],
                'json' => [
                    'loaded' => extension_loaded('json'),
