                if (trim((string)$input['ffmpeg_path']) !== trim((string)($siteSettings['ffmpeg_path'] ?? ''))) {
                    @unlink(__DIR__ . '/data/thumbcache/.ffmpeg_capable');
                    @unlink(__DIR__ . '/data/thumbcache/.ffmpeg_incapable');
