                $siteSettings['hw_accel_mode'] = in_array($m, ['', 'h264_nvenc', 'h264_qsv', 'h264_amf', 'h264_vaapi'], true) ? $m : '';
            }
            if (array_key_exists('vaapi_device', $input)) {
