        case 'clear_thumbcache':
            $auth->requireRealAdmin();
            $cacheDir = __DIR__ . '/data/thumbcache';
            $count = 0;
            $freedBytes = 0;
            if (is_dir($cacheDir)) {
                // 루트 디렉토리 파일 삭제 (일반 이미지/비디오 썸네일, MP3 nocover 마커)
                // glob('/*')는 .으로 시작하는 숨김 파일을 못 잡으므로 scandir 사용
                $files = scandir($cacheDir);
                foreach ($files as $f) {
                    if ($f === '.' || $f === '..') continue;
                    $filePath = $cacheDir . DIRECTORY_SEPARATOR . $f;
                    if (is_file($filePath)) {
                        $freedBytes += filesize($filePath);
                        @unlink($filePath);
                        $count++;
                    }
                }
                // MP3 ID3 커버 캐시 (audio_cover API용)
                // 주의: comments/ 등 다른 하위 디렉토리는 건드리지 않음 (게시판 댓글 썸네일)
                $audioCacheDir = $cacheDir . DIRECTORY_SEPARATOR . 'audio';
                if (is_dir($audioCacheDir) && !is_link($audioCacheDir)) {
                    $audioFiles = @scandir($audioCacheDir);
                    if ($audioFiles !== false) {
                        foreach ($audioFiles as $f) {
                            if ($f === '.' || $f === '..') continue;
                            $filePath = $audioCacheDir . DIRECTORY_SEPARATOR . $f;
                            if (is_file($filePath) && !is_link($filePath)) {
                                $fsize = @filesize($filePath);
                                if ($fsize !== false) $freedBytes += $fsize;
                                @unlink($filePath);
                                $count++;
                            }
                        }
                    }
                }
                // ★ (2026-10-02) 재생바 미리보기 장면 캐시(seek/, FileManager::videoFrameFile) — audio/ 와 같은 방식. .slot 잠금 파일은 남긴다.
                $seekCacheDir = $cacheDir . DIRECTORY_SEPARATOR . 'seek';
                if (is_dir($seekCacheDir) && !is_link($seekCacheDir)) {
                    $seekFiles = @scandir($seekCacheDir);
                    if ($seekFiles !== false) {
                        foreach ($seekFiles as $f) {
                            if ($f === '.' || $f === '..' || strpos($f, '.slot') === 0) continue;
                            $filePath = $seekCacheDir . DIRECTORY_SEPARATOR . $f;
                            if (is_file($filePath) && !is_link($filePath)) {
                                $fsize = @filesize($filePath);
                                if ($fsize !== false) $freedBytes += $fsize;
                                @unlink($filePath);
                                $count++;
                            }
                        }
                    }
                }
                // ★ (2026-11-12 16:10, 100차 CVR-4) 공유 페이지 표지 캐시(share_audio/: .bin·.img·.meta·.nocover·.w512.jpg)도 — 모두 다음 요청 때 mp3 에서 다시 만들어짐(폴더도 저절로 생김).
                //   종전엔 audio/·seek/ 만 지워 공유 쪽 옛 '표지 없음' 표시가 이 버튼으로 안 풀렸음(재현). audio/ 와 같은 방식
                $shAudioCacheDir = $cacheDir . DIRECTORY_SEPARATOR . 'share_audio';
                if (is_dir($shAudioCacheDir) && !is_link($shAudioCacheDir)) {
                    foreach ((@scandir($shAudioCacheDir) ?: []) as $f) {
                        if ($f === '.' || $f === '..') continue;
                        $filePath = $shAudioCacheDir . DIRECTORY_SEPARATOR . $f;
                        if (is_file($filePath) && !is_link($filePath)) {
                            $fsize = @filesize($filePath);
                            if ($fsize !== false) $freedBytes += $fsize;
                            @unlink($filePath);
                            $count++;
                        }
                    }
                }
            }
            $result = [
                'success' => true,
                'deleted' => $count,
                'freed' => $freedBytes
            ];
            break;
        
        case 'thumb_debug':
