                $ffmpegPaths = array_merge($ffmpegPaths, findVersionedMediaBins('ffmpeg'));
                array_push($ffmpegPaths, 'ffmpeg', '/usr/bin/ffmpeg', '/usr/local/bin/ffmpeg', '/usr/local/ffmpeg/bin/ffmpeg', '/volume1/@appstore/ffmpeg/bin/ffmpeg', '/volume1/@appstore/MediaServer/bin/ffmpeg', '/var/packages/ffmpeg/target/bin/ffmpeg', '/var/packages/MediaServer/target/bin/ffmpeg');
            }
            foreach ($ffmpegPaths as $fp) {
                $out = [];
                @exec(escapeshellarg($fp) . ' -version 2>&1', $out, $ret);
                if ($ret === 0) {
                    $ffmpegAvailable = true;
                    $ffmpegDetectedPath = $fp;
                    $firstLine = $out[0] ?? '';
                    if (preg_match('/ffmpeg version (\S+)/', $firstLine, $m)) {
                        $ffmpegVersion = $m[1];
                    }
                    break;
                }
            }
            
            // Imagick 체크
            $imagickLoaded = extension_loaded('imagick');
            $imagickVersion = $imagickLoaded && class_exists('Imagick') ? \Imagick::getVersion()['versionString'] ?? '' : '';
            
            // ffprobe 체크
            $ffprobeAvailable = false;
            $ffprobeVersion = '';
            $ffprobeDetectedPath = '';
            $configuredProbePath = trim($thumbSettings['ffprobe_path'] ?? '');
            $ffprobePaths = [];
            if ($configuredProbePath) {
                $ffprobePaths[] = $configuredProbePath;
            }
            if (PHP_OS_FAMILY === 'Windows') {
                array_push($ffprobePaths, 'ffprobe', 'C:\\ffmpeg\\bin\\ffprobe.exe', 'C:\\Program Files\\ffmpeg\\bin\\ffprobe.exe');
            } else {
                // ★ (2026-08-24) 버전이 붙은 패키지 경로(예: /var/packages/ffprobe7/target/bin/ffprobe)를
                //   PATH 보다 **먼저** 시도한다 — 자세한 배경은 findVersionedMediaBins() 주석 참조.
                $ffprobePaths = array_merge($ffprobePaths, findVersionedMediaBins('ffprobe'));
                array_push($ffprobePaths, 'ffprobe', '/usr/bin/ffprobe', '/usr/local/bin/ffprobe',
                    '/usr/local/ffmpeg/bin/ffprobe', '/volume1/@appstore/ffmpeg/bin/ffprobe',
                    '/volume1/@appstore/MediaServer/bin/ffprobe', '/var/packages/ffmpeg/target/bin/ffprobe',
                    '/var/packages/MediaServer/target/bin/ffprobe');
            }
            foreach ($ffprobePaths as $fp2) {
                $out2 = [];
                @exec(escapeshellarg($fp2) . ' -version 2>&1', $out2, $ret2);
                if ($ret2 === 0) {
                    $ffprobeAvailable = true;
                    $ffprobeDetectedPath = $fp2;
                    $firstLine2 = $out2[0] ?? '';
                    if (preg_match('/ffprobe version (\S+)/', $firstLine2, $m2)) {
                        $ffprobeVersion = $m2[1];
                    }
                    break;
                }
            }
            
            // 캐시 상태 (루트 *.jpg + MP3 커버용 audio/ 하위 - clear_thumbcache와 동일 범위)
            $cacheDir = __DIR__ . '/data/thumbcache';
            $cacheCount = 0;
            $cacheSize = 0;
            if (is_dir($cacheDir)) {
                // 루트의 일반 썸네일 (기존 동작)
                $files = glob($cacheDir . '/*.jpg');
                $cacheCount = count($files);
                foreach ($files as $f) {
                    $cacheSize += filesize($f);
                }
                // MP3 ID3 커버 캐시 (audio/ 하위)
                $audioCacheDir = $cacheDir . DIRECTORY_SEPARATOR . 'audio';
                if (is_dir($audioCacheDir) && !is_link($audioCacheDir)) {
                    $audioFiles = @scandir($audioCacheDir);
                    if ($audioFiles !== false) {
                        foreach ($audioFiles as $f) {
                            if ($f === '.' || $f === '..') continue;
                            $filePath = $audioCacheDir . DIRECTORY_SEPARATOR . $f;
                            if (is_file($filePath) && !is_link($filePath)) {
                                $fsize = @filesize($filePath);
                                if ($fsize !== false) {
                                    $cacheSize += $fsize;
                                    $cacheCount++;
                                }
                            }
                        }
                    }
                }
                // ★ (2026-10-02) 재생바 미리보기 장면 캐시(seek/) — clear_thumbcache 와 같은 범위(.slot 잠금 파일 제외)
                $seekCacheDir = $cacheDir . DIRECTORY_SEPARATOR . 'seek';
                if (is_dir($seekCacheDir) && !is_link($seekCacheDir)) {
                    $seekFiles = @scandir($seekCacheDir);
                    if ($seekFiles !== false) {
                        foreach ($seekFiles as $f) {
                            if ($f === '.' || $f === '..' || strpos($f, '.slot') === 0) continue;
                            $filePath = $seekCacheDir . DIRECTORY_SEPARATOR . $f;
                            if (is_file($filePath) && !is_link($filePath) && substr($f, -4) === '.jpg') {
                                $fsize = @filesize($filePath);
                                if ($fsize !== false) { $cacheSize += $fsize; $cacheCount++; }
                            }
                        }
                    }
                }
                // ★ (2026-11-12 16:10, 100차 CVR-4) 공유 페이지 표지 캐시(share_audio/) — clear_thumbcache 와 같은 범위
                $shAudioCacheDir = $cacheDir . DIRECTORY_SEPARATOR . 'share_audio';
                if (is_dir($shAudioCacheDir) && !is_link($shAudioCacheDir)) {
                    foreach ((@scandir($shAudioCacheDir) ?: []) as $f) {
                        if ($f === '.' || $f === '..') continue;
                        $filePath = $shAudioCacheDir . DIRECTORY_SEPARATOR . $f;
                        if (is_file($filePath) && !is_link($filePath)) {
                            $fsize = @filesize($filePath);
                            if ($fsize !== false) { $cacheSize += $fsize; $cacheCount++; }
                        }
                    }
                }
            }
            
            $result = [
                'success' => true,
                'gd' => [
                    'available' => $gdLoaded,
                    'jpeg' => !empty($gdInfo['JPEG Support']),
                    'png' => !empty($gdInfo['PNG Support']),
                    'gif' => !empty($gdInfo['GIF Read Support']),
                    'webp' => !empty($gdInfo['WebP Support']),
                ],
                'ffmpeg' => [
                    'available' => $ffmpegAvailable,
                    'version' => $ffmpegVersion,
                    'path' => $ffmpegDetectedPath,
                    'configured_path' => $configuredPath,
                ],
                'ffprobe' => [
                    'available' => $ffprobeAvailable,
                    'version' => $ffprobeVersion,
                    'path' => $ffprobeDetectedPath,
                    'configured_path' => $configuredProbePath,
                ],
                'proc_open' => [
                    'available' => function_exists('proc_open') && !in_array('proc_open', array_map('trim', explode(',', @ini_get('disable_functions') ?: ''))),
                ],
                'imagick' => [
                    'available' => $imagickLoaded,
                    'version' => $imagickVersion,
                ],
                'pdf_tools' => (function() {
                    $tools = [];
                    // pdftoppm
                    $out = []; @exec('pdftoppm -v 2>&1', $out, $ret);
                    if ($ret === 0) $tools[] = 'pdftoppm';
                    // mutool
                    $out = []; @exec('mutool --version 2>&1', $out, $ret);
                    if ($ret === 0) $tools[] = 'mutool';
                    // gs
                    $gsName = PHP_OS_FAMILY === 'Windows' ? 'gswin64c' : 'gs';
                    $out = []; @exec(escapeshellarg($gsName) . ' --version 2>&1', $out, $ret);
                    if ($ret === 0) $tools[] = $gsName;
                    return $tools;
                })(),
                'cache' => [
                    'count' => $cacheCount,
                    'size' => $cacheSize,
                ]
            ];
            break;
        
        case 'test_ffmpeg':
            $auth->requireRealAdmin();
            $testPath = trim($input['path'] ?? '');
            if (!$testPath) {
                $result = ['success' => false, 'error' => __('api_err_path_required', '경로를 입력해주세요.')];
                break;
            }
            $out = [];
            @exec(escapeshellarg($testPath) . ' -version 2>&1', $out, $ret);
            if ($ret === 0) {
                $ver = '';
                $firstLine = $out[0] ?? '';
                if (preg_match('/ffmpeg version (\S+)/', $firstLine, $m)) {
                    $ver = $m[1];
                }
                $result = ['success' => true, 'version' => $ver, 'output' => $firstLine];
            } else {
                $result = ['success' => false, 'error' => __('api_err_exec_failed', '실행 실패: ') . shellOutToUtf8((string)($out[0] ?? __('api_err_file_not_found', '파일을 찾을 수 없습니다.')))];
            }
            break;
        
        case 'test_ffprobe':
            $auth->requireRealAdmin();
            $testPath = trim($input['path'] ?? '');
            if (!$testPath) {
                $result = ['success' => false, 'error' => __('api_err_path_required', '경로를 입력해주세요.')];
                break;
            }
            $out = [];
            @exec(escapeshellarg($testPath) . ' -version 2>&1', $out, $ret);
            if ($ret === 0) {
                $ver = '';
                $firstLine = $out[0] ?? '';
                if (preg_match('/ffprobe version (\S+)/', $firstLine, $m)) {
                    $ver = $m[1];
                }
                $result = ['success' => true, 'version' => $ver, 'output' => $firstLine];
            } else {
                $result = ['success' => false, 'error' => __('api_err_exec_failed', '실행 실패: ') . shellOutToUtf8((string)($out[0] ?? __('api_err_file_not_found', '파일을 찾을 수 없습니다.')))];
            }
            break;
        
        // ★ (2026-08-24) 하드웨어 가속 진단 — 어느 단계에서 막혔는지까지 알려준다.
        //   [왜] 지금까지는 재생을 해봐야 HW 여부를 알 수 있었고, 실패해도 원인(빌드에 인코더가
        //   없는지 / 렌더 노드 권한인지 / 드라이버인지)을 구분할 수 없었다. 관리자가 버튼 한 번으로
        //   확인하고 조치까지 알 수 있게 한다.
        //   실제 인코딩을 1프레임 돌려보므로 "지원한다고 표시되는데 막상 안 되는" 경우도 걸러진다.
        case 'test_hwaccel':
            $auth->requireRealAdmin();

            $siteSettings = loadSiteSettings();
            $ffmpegPath = trim($siteSettings['ffmpeg_path'] ?? '');
            $ffmpegPaths = $ffmpegPath ? [$ffmpegPath] : [];
            if (PHP_OS_FAMILY === 'Windows') {
                array_push($ffmpegPaths, 'ffmpeg', 'C:\\ffmpeg\\bin\\ffmpeg.exe', 'C:\\Program Files\\ffmpeg\\bin\\ffmpeg.exe');
            } else {
                $ffmpegPaths = array_merge($ffmpegPaths, findVersionedMediaBins('ffmpeg'));
                array_push($ffmpegPaths, 'ffmpeg', '/usr/bin/ffmpeg', '/usr/local/bin/ffmpeg');
            }
            $ffmpegBin = '';
            foreach ($ffmpegPaths as $fp) {
                $o = []; $r = 1;
                @exec(escapeshellarg($fp) . ' -version 2>&1', $o, $r);
                if ($r === 0) { $ffmpegBin = $fp; break; }
            }
            if ($ffmpegBin === '') {
                $result = ['success' => false, 'error' => __('api_err_ffmpeg_not_found', 'ffmpeg 을 찾을 수 없습니다. 위에서 경로를 지정해주세요.')];
                break;
            }

            $devNull = PHP_OS_FAMILY === 'Windows' ? 'NUL' : '/dev/null';
            $encoderList = @shell_exec(escapeshellarg($ffmpegBin) . ' -encoders 2>' . $devNull) ?? '';

            // 렌더 노드 상태 — VA-API 판정과 "왜 안 되는지" 안내에 쓰인다.
            $renderNodes = [];
            $renderUsable = '';
            if (PHP_OS_FAMILY !== 'Windows') {
                $nodes = @glob('/dev/dri/renderD*');
                if (is_array($nodes)) {
                    sort($nodes);
                    foreach ($nodes as $n) {
                        $ok = (@is_readable($n) && @is_writable($n));
                        $renderNodes[] = ['path' => $n, 'usable' => $ok];
                        if ($ok && $renderUsable === '') $renderUsable = $n;
                    }
                }
            }

            $manualDev = trim($siteSettings['vaapi_device'] ?? '');
            if ($manualDev !== '' && @file_exists($manualDev)) $renderUsable = $manualDev;

            // ★ (2026-08-24) 권한 문제일 때 **그대로 복사해 쓸 수 있는 명령**을 만들어 준다.
            //   [배경] 종전 안내는 `usermod -aG videodriver http` 라는 **예시값**이라, 실제 웹서버
            //   계정명·그룹명이 다르면 사용자가 직접 알아내야 했다(배포 사용자 사례에서 확인).
            //   서버는 이 값들을 알 수 있으므로 실제 값으로 채운 명령을 내려준다.
            //   [주의] posix_* 는 확장이 없을 수 있어 전부 function_exists 로 감싸고,
            //   알아내지 못하면 해당 부분을 빈 값으로 두어 **안내 자체가 깨지지 않게** 한다.
            $webUser = '';
            if (function_exists('posix_geteuid') && function_exists('posix_getpwuid')) {
                $pw = @posix_getpwuid(@posix_geteuid());
                if (is_array($pw) && !empty($pw['name'])) $webUser = (string)$pw['name'];
            }
            if ($webUser === '' && function_exists('get_current_user')) {
                $webUser = (string)@get_current_user();
            }
            // 렌더 노드의 그룹명 — 여기에 웹서버 계정을 넣어야 접근이 열린다.
            $nodeGroup = '';
            $groupMembers = [];      // 기존 그룹 멤버 — synogroup 명령을 안전하게 만들기 위해 필요
            $membersKnown = false;   // 멤버 목록을 실제로 읽었는지(빈 그룹과 '못 읽음'을 구분)
            $probeNode = $renderUsable !== '' ? $renderUsable : (!empty($renderNodes) ? $renderNodes[0]['path'] : '');
            if ($probeNode !== '' && function_exists('filegroup') && function_exists('posix_getgrgid')) {
                $gid = @filegroup($probeNode);
                if ($gid !== false) {
                    $gr = @posix_getgrgid($gid);
                    if (is_array($gr) && !empty($gr['name'])) {
                        $nodeGroup = (string)$gr['name'];
                        if (isset($gr['members']) && is_array($gr['members'])) {
                            $membersKnown = true;
                            foreach ($gr['members'] as $mname) {
                                // 표시용 명령에 들어가므로 계정명으로 쓰이는 문자만 통과시킨다.
                                $mname = (string)$mname;
                                if ($mname !== '' && preg_match('/^[A-Za-z0-9._-]+$/', $mname)) {
                                    $groupMembers[] = $mname;
                                } else {
                                    // ★ (2026-08-24) 필터에 걸린 멤버가 하나라도 있으면 **완성 명령을 만들지 않는다.**
                                    //   synogroup 은 덮어쓰기라, 걸러진 계정이 명령에서 빠지면
                                    //   **그 계정이 그룹에서 제거된다** — 보안 필터가 오히려 손실을 만드는 셈이다.
                                    //   이 경우 아래에서 $membersKnown 을 false 로 되돌려 '조회 먼저' 경로를 타게 한다.
                                    $membersKnown = false;
                                }
                            }
                        }
                    }
                }
            }
            // 시놀로지는 usermod 대신 synogroup 을 쓰는 것이 안전하다.
            $isSyno = @is_file('/etc/synoinfo.conf') || @is_dir('/var/packages');
            $fixCmd = '';
            $altCmd = '';          // --memberadd 가 없는 구버전 DSM 을 위한 대안(--member 완성 명령)
            $getCmd = '';          // 시놀로지에서 멤버를 모를 때 먼저 실행할 조회 명령
            $alreadyMember = ($webUser !== '' && in_array($webUser, $groupMembers, true));

            if ($webUser !== '' && $nodeGroup !== '') {
                if (!$isSyno) {
                    // ★ usermod -aG 는 **추가(append)** 방식이라 기존 멤버에 영향이 없다.
                    $fixCmd = 'sudo usermod -aG ' . $nodeGroup . ' ' . $webUser;
                } else {
                    // ★ (2026-08-24) 시놀로지는 **--memberadd 를 1순위**로 안내한다.
                    //   [배경] `synogroup --member` 는 **덮어쓰기**다 — 나열한 계정만 남고 나머지는
                    //   그룹에서 제거된다(시놀로지 문서·커뮤니티 다수 확인). 실제로 배포 사용자 NAS 의
                    //   videodriver 그룹에는 sc-ffmpeg5·sc-ffmpeg7·sc-ffmpeg8 등이 들어 있어,
                    //   웹서버 계정만 지정했다면 **그 패키지들이 그룹에서 빠졌을 것**이다
                    //   (사용자가 스스로 --get 으로 먼저 확인해 회피한 사례).
                    //   [개선] 최신 DSM 에는 **`--memberadd`** 가 있고 이는 **추가(append)** 방식이라
                    //   기존 멤버를 나열할 필요가 없어 실수 여지가 없다 → 이것을 기본으로 제시한다.
                    //   다만 구버전 DSM 에는 없을 수 있으므로, 기존 멤버를 읽을 수 있으면
                    //   **--member 완성 명령을 대안으로 함께** 내려보낸다(멤버 전부 나열 + 웹서버 계정).
                    //   둘 다 만들 수 없으면(멤버 미확보) 파괴적 명령 대신 --get 조회부터 안내한다.
                    $fixCmd = 'sudo synogroup --memberadd ' . $nodeGroup . ' ' . $webUser;
                    if ($membersKnown) {
                        $list = $groupMembers;
                        if (!$alreadyMember) $list[] = $webUser;
                        $altCmd = 'sudo synogroup --member ' . $nodeGroup . ' ' . implode(' ', $list);
                    } else {
                        $getCmd = 'sudo synogroup --get ' . $nodeGroup;
                    }
                }
            }

            // ★ (2026-08-25) CPU·GPU 모델명 수집 — 사용자가 자기 하드웨어를 확인하고
            //   검색·문의할 수 있게 한다. 세대 판별표를 코드에 넣지 않는 이유는 표가 계속 낡고
            //   오판 시 잘못된 안내를 하게 되기 때문이다. **모델명만 보여주고 판단은 사용자에게** 맡긴다.
            $cpuModel = '';
            if (PHP_OS_FAMILY !== 'Windows') {
                if (@is_readable('/proc/cpuinfo')) {
                    $lines = @file('/proc/cpuinfo');
                    if (is_array($lines)) {
                        foreach ($lines as $l) {
                            if (stripos($l, 'model name') === 0) {
                                $parts = explode(':', $l, 2);
                                $cpuModel = trim($parts[1] ?? '');
                                break;
                            }
                        }
                    }
                }
            } else {
                // 윈도우는 wmic 로 조회(없으면 빈 값 — 표시를 생략한다)
                $o = []; $r = 1;
                @exec('wmic cpu get name /value 2>NUL', $o, $r);
                foreach ($o as $l) {
                    if (stripos($l, 'Name=') === 0) { $cpuModel = trim(substr($l, 5)); break; }
                }
            }

            // GPU — 리눅스는 DRM 노드에서 벤더/디바이스 ID 를 읽는다(lspci 가 없는 환경 대비).
            //   ID 를 이름으로 바꾸는 표는 두지 않고, 벤더만 판별해 표시한다.
            $gpuList = [];
            if (PHP_OS_FAMILY !== 'Windows') {
                // ★ (2026-08-25) PCI ID 만 보여주면 사용자가 무슨 GPU 인지 알 수 없다(펜닐 지적).
                //   모델명을 얻는 경로를 순서대로 시도한다 — 환경마다 있는 것이 달라서다.
                //     ① lspci  ② pci.ids 데이터베이스 조회  ③ 실패하면 벤더 + ID 만 표시(종전)
                //   어느 것도 없으면 최소한 벤더는 알 수 있으므로 진단 가치는 남는다.
                $lspciOut = '';
                if (trim((string)@shell_exec('command -v lspci 2>/dev/null')) !== '') {
                    $lspciOut = (string)@shell_exec('lspci -nn 2>/dev/null');
                }
                // pci.ids 는 배포판마다 위치가 다르다.
                $pciIdsFile = '';
                foreach (['/usr/share/hwdata/pci.ids', '/usr/share/misc/pci.ids', '/usr/share/pci.ids'] as $cand) {
                    if (@is_readable($cand)) { $pciIdsFile = $cand; break; }
                }

                foreach ((@glob('/sys/class/drm/card*/device/vendor') ?: []) as $vf) {
                    $vid = strtolower(trim((string)@file_get_contents($vf)));
                    $df  = dirname($vf) . '/device';
                    $did = strtolower(trim((string)@file_get_contents($df)));
                    $vendor = ($vid === '0x8086') ? 'Intel' : (($vid === '0x10de') ? 'NVIDIA' : (($vid === '0x1002') ? 'AMD' : $vid));
                    $vidShort = ltrim(str_replace('0x', '', $vid), '0') !== '' ? substr($vid, 2) : '';
                    $didShort = strlen($did) > 2 ? substr($did, 2) : '';
                    $model = '';

                    // ① lspci 출력에서 [vendor:device] 로 찾기 — 가장 정확하다.
                    if ($lspciOut !== '' && $vidShort !== '' && $didShort !== '') {
                        foreach (explode("\n", $lspciOut) as $ln) {
                            if (stripos($ln, '[' . $vidShort . ':' . $didShort . ']') !== false) {
                                // "00:02.0 VGA compatible controller: Intel Corporation HD Graphics [8086:0412] (rev 06)"
                                $pos = strpos($ln, ': ');
                                if ($pos !== false) {
                                    $model = trim(substr($ln, $pos + 2));
                                    $model = trim(preg_replace('/\s*\[[0-9a-f]{4}:[0-9a-f]{4}\].*$/i', '', $model));
                                }
                                break;
                            }
                        }
                    }
                    // ② pci.ids 조회 — 벤더 블록(들여쓰기 없음) 안의 디바이스 줄(탭 1개)을 찾는다.
                    if ($model === '' && $pciIdsFile !== '' && $vidShort !== '' && $didShort !== '') {
                        $fh = @fopen($pciIdsFile, 'r');
                        if ($fh) {
                            $inVendor = false;
                            while (($ln = fgets($fh)) !== false) {
                                if ($ln === '' || $ln[0] === '#') continue;
                                if ($ln[0] !== "\t") {
                                    if ($inVendor) break;                       // 다음 벤더로 넘어감
                                    $inVendor = (stripos($ln, $vidShort . ' ') === 0);
                                    continue;
                                }
                                if ($inVendor && $ln[0] === "\t" && (!isset($ln[1]) || $ln[1] !== "\t")) {
                                    $t = ltrim($ln, "\t");
                                    if (stripos($t, $didShort . ' ') === 0) {
                                        $model = trim(substr($t, strlen($didShort)));
                                        break;
                                    }
                                }
                            }
                            @fclose($fh);
                        }
                    }

                    // ③ 표시 — 모델명을 찾았으면 "벤더 모델명 (ID)", 아니면 종전처럼 "벤더 (ID)"
                    $idPart = ($vidShort !== '' && $didShort !== '') ? ' [' . $vidShort . ':' . $didShort . ']' : '';
                    $gpuList[] = $model !== '' ? ($model . $idPart) : ($vendor . $idPart);
                }
            } else {
                $o = []; $r = 1;
                @exec('wmic path win32_VideoController get name /value 2>NUL', $o, $r);
                foreach ($o as $l) {
                    if (stripos($l, 'Name=') === 0) {
                        $nm = trim(substr($l, 5));
                        if ($nm !== '') $gpuList[] = $nm;
                    }
                }
            }
            $gpuList = array_values(array_unique($gpuList));

            // 시놀로지 판정 — 아래 후보 루프의 패키지 안내에서 쓰므로 여기서 먼저 구한다.
            $isSynoEnv = @is_file('/etc/synoinfo.conf') || @is_dir('/var/packages');

            // 후보별로 ①빌드 포함 여부 ②실제 1프레임 인코딩을 확인한다.
            $candidates = [
                'h264_nvenc' => '-c:v h264_nvenc -preset p1 -tune ll -qp 23 -profile:v high -level 4.1 -pix_fmt yuv420p',
                'h264_qsv'   => '-c:v h264_qsv -preset veryfast -global_quality 23 -profile:v high -pix_fmt yuv420p',
                'h264_amf'   => '-c:v h264_amf -quality speed -qp_i 23 -qp_p 23 -profile:v high -pix_fmt yuv420p',
            ];
            if (PHP_OS_FAMILY !== 'Windows') {
                $candidates['h264_vaapi'] = '-c:v h264_vaapi -qp 23 -profile:v high -level 41';
            }

            $items = [];
            foreach ($candidates as $enc => $args) {
                $row = ['encoder' => $enc, 'in_build' => false, 'ok' => false, 'reason' => '', 'detail' => ''];
                if (strpos($encoderList, $enc) === false) {
                    $row['reason'] = __('api_hw_not_in_build', 'ffmpeg 빌드에 이 인코더가 없음');
                    // ★ (2026-08-25) 빌드에 없으면 ffmpeg 교체가 답이다 — 환경별로 방법이 다르다.
                    $row['pkg_hint'] = $isSynoEnv
                        ? 'pkg_syno_ffmpeg'
                        : (PHP_OS_FAMILY === 'Windows' ? 'pkg_win_ffmpeg' : 'pkg_linux_ffmpeg');
                    $items[] = $row; continue;
                }
                $row['in_build'] = true;

                if ($enc === 'h264_vaapi') {
                    if ($renderUsable === '') {
                        $row['reason'] = empty($renderNodes)
                            ? __('api_hw_no_render_node', '/dev/dri 렌더 노드가 없음 (내장 그래픽 비활성 가능)')
                            : __('api_hw_render_no_perm', '렌더 노드에 웹서버 계정 권한이 없음');
                        $items[] = $row; continue;
                    }
                    $cmd = escapeshellarg($ffmpegBin)
                        . ' -hide_banner -nostdin -vaapi_device ' . escapeshellarg($renderUsable)
                        . ' -f lavfi -i nullsrc=s=64x64:d=0.1'
                        . ' -vf format=nv12,hwupload ' . $args
                        . ' -frames:v 1 -f null - 2>&1';
                } else {
                    $cmd = escapeshellarg($ffmpegBin)
                        . ' -hide_banner -nostdin -f lavfi -i nullsrc=s=64x64:d=0.1 ' . $args
                        . ' -frames:v 1 -f null - 2>&1';
                }

                $o = []; $r = 1;
                @exec($cmd, $o, $r);
                if ($r === 0) {
                    $row['ok'] = true;
                } else {
                    $tail = shellOutToUtf8(trim(implode(' | ', array_slice($o, -6))));
                    if (strlen($tail) > 400) $tail = '...' . substr($tail, -400);
                    $row['reason'] = __('api_hw_encode_failed', '인코딩 테스트 실패');
                    $row['detail'] = $tail;
                    // ★ (2026-08-24) 리눅스의 QSV/NVENC 도 내부적으로 **/dev/dri 렌더 노드**를 통해
                    //   GPU 에 접근한다. 그래서 권한이 없으면 VA-API 뿐 아니라 이들도 실패하는데,
                    //   ffmpeg 메시지가 'Invalid argument' 처럼 모호해 권한 문제인지 알기 어렵다.
                    //   렌더 노드가 있는데 접근이 안 되는 상황이면 그 가능성을 함께 알린다.
                    //   ※ 단정하지 않고 '가능성'으로 표시한다 — 세대 미달·런타임 미설치 등
                    //     다른 원인일 수도 있어 오진단을 피하기 위함이다.
                    if (PHP_OS_FAMILY !== 'Windows' && $renderUsable === '' && !empty($renderNodes)) {
                        $row['perm_hint'] = true;
                    }
                    // ★ (2026-08-25) 빌드에는 있는데 실행이 실패하면 **런타임·드라이버**가 없을 가능성이 크다.
                    //   인코더별·환경별로 필요한 것이 달라 구분해 안내한다.
                    //   (배포 사용자 시놀로지 사례: 패키지센터에서 FFmpeg · SynoCli Video Drivers ·
                    //    SynoCli Video Driver Tools 를 설치해 해결)
                    if (PHP_OS_FAMILY !== 'Windows') {
                        if ($enc === 'h264_qsv') {
                            $row['pkg_hint'] = $isSynoEnv ? 'pkg_syno_qsv' : 'pkg_linux_qsv';
                        } elseif ($enc === 'h264_vaapi') {
                            $row['pkg_hint'] = $isSynoEnv ? 'pkg_syno_vaapi' : 'pkg_linux_vaapi';
                        }
                    }
                }
                $items[] = $row;
            }

            $result = [
                'success' => true,
                'os' => PHP_OS_FAMILY,
                'cpu' => $cpuModel,
                'gpus' => $gpuList,
                'ffmpeg' => $ffmpegBin,
                'render_nodes' => $renderNodes,
                'items' => $items,
                'mode' => trim($siteSettings['hw_accel_mode'] ?? ''),
                // 조치 안내용 — 값을 못 구하면 빈 문자열이며, 화면은 일반 안내로 대체한다.
                'web_user' => $webUser,
                'node_group' => $nodeGroup,
                'fix_cmd' => $fixCmd,
                'alt_cmd' => $altCmd,                  // --memberadd 미지원 시 대안
                'get_cmd' => $getCmd,                  // 멤버를 못 읽었을 때 먼저 실행할 조회 명령
                'group_members' => $groupMembers,      // 참고 표시용
                'already_member' => $alreadyMember,    // 이미 속해 있으면 재시작만 하면 된다
                'is_synology' => $isSyno,
            ];
            break;

        case 'test_pdftool':
            $auth->requireRealAdmin();
            $tool = trim($input['tool'] ?? '');
            $testPath = trim($input['path'] ?? '');
            
            if (!$tool && !$testPath) {
                $result = ['success' => false, 'error' => __('api_err_tool_or_path_required', '도구를 선택하거나 경로를 입력해주세요.')];
                break;
            }
            
            $execPath = $testPath ?: $tool;
            $out = [];

            // ★ (2026-08-24) Imagick 은 **CLI 명령이 아니라 PHP 확장**이므로 exec 로 테스트할 수 없다.
            //   [증상] 드롭다운에서 Imagick 을 고르고 [테스트]를 누르면
            //     실행 실패: "'imagick'은(는) 내부 또는 외부 명령…" (윈도우 셸 메시지)
            //   이 오류는 도구가 없는 것이 아니라 **애초에 실행할 수 없는 대상**을 exec 한 결과다.
            //   → 확장 로드 여부와 PDF 지원(디코더 목록)을 직접 확인해 결과를 돌려준다.
            //   경로를 함께 입력했다면 사용자가 CLI 도구를 의도한 것으로 보고 아래 일반 분기로 넘긴다.
            if ($tool === 'imagick' && $testPath === '') {
                if (!extension_loaded('imagick')) {
                    $result = ['success' => false, 'error' => __('api_err_imagick_missing', 'Imagick PHP 확장이 설치되지 않았습니다.')];
                    break;
                }
                $fmts = [];
                try {
                    $fmts = @\Imagick::queryFormats('PDF');
                } catch (\Throwable $e) {
                    $fmts = [];
                }
                if (empty($fmts)) {
                    // 확장은 있으나 PDF 델리게이트(Ghostscript)가 없는 상태
                    $result = ['success' => false, 'error' => __('api_err_imagick_no_pdf', 'Imagick 은 설치돼 있으나 PDF 를 지원하지 않습니다. Ghostscript 설치가 필요합니다.')];
                    break;
                }
                $ver = '';
                try {
                    $v = @\Imagick::getVersion();
                    $ver = is_array($v) ? (string)($v['versionString'] ?? '') : '';
                } catch (\Throwable $e) {
                    $ver = '';
                }
                $result = ['success' => true, 'version' => $ver !== '' ? $ver : 'Imagick', 'output' => 'PDF: ' . implode(', ', $fmts)];
                break;
            }

            // 도구별로 버전 확인 명령이 다름
            if (strpos($execPath, 'pdftoppm') !== false) {
                @exec(escapeshellarg($execPath) . ' -v 2>&1', $out, $ret);
            } elseif (strpos($execPath, 'mutool') !== false) {
                @exec(escapeshellarg($execPath) . ' --version 2>&1', $out, $ret);
            } else {
                // gs, gswin64c 등
                @exec(escapeshellarg($execPath) . ' --version 2>&1', $out, $ret);
            }
            
            if ($ret === 0) {
                $firstLine = trim($out[0] ?? '');
                $result = ['success' => true, 'version' => $firstLine, 'output' => implode("\n", array_slice($out, 0, 3))];
            } else {
                $result = ['success' => false, 'error' => __('api_err_exec_failed', '실행 실패: ') . shellOutToUtf8(trim((string)($out[0] ?? __('api_err_file_not_found', '파일을 찾을 수 없습니다.'))))];
            }
            break;
        
        case 'site_image_upload':
            $auth->requireRealAdmin();
            
            $type = $input['type'] ?? $_POST['type'] ?? '';  // 'logo' or 'bg'
            if (!in_array($type, ['logo', 'bg'])) {
                $result = ['success' => false, 'error' => __('api_err_invalid_image_type', '잘못된 이미지 타입')];
                break;
            }
            
            if (!isset($_FILES['image']) || $_FILES['image']['error'] !== UPLOAD_ERR_OK) {
                $result = ['success' => false, 'error' => __('api_err_file_upload_failed', '파일 업로드 실패')];
                break;
            }
            
            $file = $_FILES['image'];
            $allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
            
            if (!in_array($file['type'], $allowedTypes)) {
                $result = ['success' => false, 'error' => __('api_err_unsupported_image', '지원하지 않는 이미지 형식')];
                break;
            }
            
            // 이미지 저장 폴더
            $uploadDir = __DIR__ . '/data/site_images/';
            if (!is_dir($uploadDir)) {
                mkdir($uploadDir, 0755, true);
            }
            
            // 기존 이미지 삭제
            $siteSettings = loadSiteSettings();
            
            $oldImageKey = $type === 'logo' ? 'logo_image' : 'bg_image';
            // ★ (2026-11-01 11:36, 39차 점검) 원래 그림을 새 그림 저장 전에 지워, 옮기기·설정 저장이 실패하면 그림이 깨졌음 → 둘 다 성공한 뒤에 지움(아래)
            $oldPath = !empty($siteSettings[$oldImageKey]) ? __DIR__ . '/' . $siteSettings[$oldImageKey] : '';
            
            // 새 파일명 생성
            // ★ (2026-10-29 18:30, 22차 점검) 확장자는 허용한 형식에서 정함(소문자) — 종전엔 올린 파일 이름의 확장자를 그대로 써서, 'IMG.JPG' 는 data/.htaccess 의
            //   소문자 허용 규칙에 걸려 그림이 안 나왔고(Apache), 형식과 다른 확장자(.svg·.php 등)로도 저장될 수 있었음
            $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/gif' => 'gif', 'image/webp' => 'webp'][$file['type']] ?? 'png';
            $newFilename = $type . '_' . time() . '.' . $ext;
            $newPath = $uploadDir . $newFilename;
            
            if (!move_uploaded_file($file['tmp_name'], $newPath)) {
                $result = ['success' => false, 'error' => __('api_err_file_save_failed_2', '파일 저장 실패')];
                break;
            }
            
            // 설정 업데이트
            $relativePath = 'data/site_images/' . $newFilename;
            $siteSettings[$oldImageKey] = $relativePath;
            if (!saveSiteSettings($siteSettings)) {   // ★ (2026-11-01 11:36, 39차 점검) 설정 저장 실패면 새 파일을 지우고 원래 그림 유지
                @unlink($newPath);
                $result = ['success' => false, 'error' => __('api_err_file_save_failed_2', '파일 저장 실패')];
                break;
            }
            // ★ (2026-11-16 15:57, 252차 점검) 옛 그림은 data/site_images 안의 파일일 때만 지움 — site_settings.json 의 경로는 설정 복원으로 아무 값이나 들어갈 수 있어,
            //   'victim.txt'·'data/../config.php' 같은 값이면 새 그림 올리기·그림 지우기가 프로그램 폴더의 다른 파일을 지웠음(재현). 올리기로 정한 경로는 늘 이 폴더 안이라 정상 동작은 그대로
            $__siDir = realpath(__DIR__ . '/data/site_images');
            $__siIn = function ($p) use ($__siDir) { $r = ($p !== '' && $__siDir) ? realpath($p) : false; return $r !== false && is_file($r) && \isSubPath($r, $__siDir); };
            if ($oldPath !== '' && $oldPath !== $newPath && file_exists($oldPath) && $__siIn($oldPath)) {   // ★ (2026-11-01 11:36, 39차 점검) 성공한 뒤에 원래 그림 삭제(같은 초 같은 이름이면 지우지 않음)
                @unlink($oldPath);
            }
            
            $result = ['success' => true, 'path' => $relativePath];
            break;
        
        case 'site_image_delete':
            $auth->requireRealAdmin();
            
            $type = $input['type'] ?? '';  // 'logo' or 'bg'
            if (!in_array($type, ['logo', 'bg'])) {
                $result = ['success' => false, 'error' => __('api_err_invalid_image_type', '잘못된 이미지 타입')];
                break;
            }
            
            $siteSettings = loadSiteSettings();
            
            $imageKey = $type === 'logo' ? 'logo_image' : 'bg_image';
            if (!empty($siteSettings[$imageKey])) {
                $imagePath = __DIR__ . '/' . $siteSettings[$imageKey];
                $__siDir = realpath(__DIR__ . '/data/site_images');   // ★ (2026-11-16 15:57, 252차 점검) 위 site_image_upload 와 같음 — data/site_images 안의 파일만 지움(설정 칸은 종전대로 비움)
                $__siReal = is_string($siteSettings[$imageKey]) && $__siDir ? realpath($imagePath) : false;
                if ($__siReal !== false && is_file($__siReal) && \isSubPath($__siReal, $__siDir)) {
                    @unlink($imagePath);
                }
                unset($siteSettings[$imageKey]);
                saveSiteSettings($siteSettings);
            }
            
            $result = ['success' => true];
            break;
        
        // ===== 스토리지 경로 설정 =====
        case 'storage_paths_get':
            $auth->requireRealAdmin();
            $pathsFile = __DIR__ . '/data/storage_paths.json';
            $paths = file_exists($pathsFile) ? json_decode(preg_replace('/^\xEF\xBB\xBF/', '', (string)file_get_contents($pathsFile)), true) : [];   // ★ (2026-11-11 12:24, 73차) BOM 을 뗌 — config.php 가 BOM 파일 경로를 쓰게 되어(MIG_73 #2) 화면도 같은 값을 보여야 저장 때 경로가 지워지지 않음
            
            // 현재 적용된 경로 (상수값)
            $result = [
                'success' => true,
                'paths' => [
                    'user_files_root' => $paths['user_files_root'] ?? '',
                    'shared_files_root' => $paths['shared_files_root'] ?? '',
                    'trash_path' => $paths['trash_path'] ?? ''
                ],
                'current' => [
                    'user_files_root' => USER_FILES_ROOT,
                    'shared_files_root' => SHARED_FILES_ROOT,
                    'trash_path' => TRASH_PATH
                ],
                'defaults' => [
                    'user_files_root' => __DIR__ . '/users',
                    'shared_files_root' => __DIR__ . '/shared',
                    'trash_path' => __DIR__ . '/data/trash_files'
                ]
            ];
            break;
        
        case 'storage_paths_update':
            $auth->requireRealAdmin();
            
            $userPath = trim($input['user_files_root'] ?? '');
            $sharedPath = trim($input['shared_files_root'] ?? '');
            $trashPath = trim($input['trash_path'] ?? '');
            
            // 경로 유효성 검사 (비어있으면 기본값 사용)
            $errors = [];
            
            if (!empty($userPath)) {
                // 경로 정규화
                $userPath = str_replace(['/', '\\'], DIRECTORY_SEPARATOR, $userPath);
                $userPath = rtrim($userPath, DIRECTORY_SEPARATOR);
                
                // 폴더 존재 확인 또는 생성 시도
                if (!is_dir($userPath)) {
                    if (!@mkdir($userPath, 0755, true)) {
                        $errors[] = __('personal_folder_create_fail') . $userPath;
                    }
                }
                if (is_dir($userPath) && !is_writable($userPath)) {
                    $errors[] = __('personal_folder_no_write') . $userPath;
                }
            }
            
            if (!empty($sharedPath)) {
                // 경로 정규화
                $sharedPath = str_replace(['/', '\\'], DIRECTORY_SEPARATOR, $sharedPath);
                $sharedPath = rtrim($sharedPath, DIRECTORY_SEPARATOR);
                
                // 폴더 존재 확인 또는 생성 시도
                if (!is_dir($sharedPath)) {
                    if (!@mkdir($sharedPath, 0755, true)) {
                        $errors[] = __('shared_folder_create_fail') . $sharedPath;
                    }
                }
                if (is_dir($sharedPath) && !is_writable($sharedPath)) {
                    $errors[] = __('shared_folder_no_write') . $sharedPath;
                }
            }
            
            if (!empty($trashPath)) {
                // 경로 정규화
                $trashPath = str_replace(['/', '\\'], DIRECTORY_SEPARATOR, $trashPath);
                $trashPath = rtrim($trashPath, DIRECTORY_SEPARATOR);
                
                // 폴더 존재 확인 또는 생성 시도
                if (!is_dir($trashPath)) {
                    if (!@mkdir($trashPath, 0755, true)) {
                        $errors[] = __('trash_folder_create_fail') . $trashPath;
                    }
                }
                if (is_dir($trashPath) && !is_writable($trashPath)) {
                    $errors[] = __('trash_folder_no_write') . $trashPath;
                }
            }
            
            if (!empty($errors)) {
                $result = ['success' => false, 'error' => implode("\n", $errors)];
                break;
            }
            
            // 설정 저장
            $pathsFile = __DIR__ . '/data/storage_paths.json';
            $oldPaths = file_exists($pathsFile) ? json_decode(preg_replace('/^\xEF\xBB\xBF/', '', (string)file_get_contents($pathsFile)), true) : [];   // ★ (2026-11-11 12:24, 73차) 위 storage_paths_get 과 같게 BOM 을 뗌('바뀜' 안내 판단만)
            $paths = [
                'user_files_root' => $userPath,
                'shared_files_root' => $sharedPath,
                'trash_path' => $trashPath,
                'updated_at' => date('Y-m-d H:i:s')
            ];
            // ★ (2026-11-11 21:15, 84차 STG-3) 파일이 깨진 동안(FS_STORAGE_PATHS_BROKEN — 화면은 빈 칸을 받음) 세 칸이 모두 비어 온 저장은 파일을 덮지 않음(바꿀 값이 없음, 지금도 기본 경로로 동작) —
            //   종전엔 다른 설정만 저장해도 빈 값으로 덮여 깨진 원문이 백업 없이 사라지고 73차 '공유 정리 멈춤'이 풀려 홈 공유가 지워졌음(재현). 값을 넣어 저장하면 덮기 전에 원문을 .corrupt-… 로 보관(73차 fsKeepCorruptCopy)
            if (defined('FS_STORAGE_PATHS_BROKEN') && FS_STORAGE_PATHS_BROKEN && is_file($pathsFile)) {
                if ($userPath === '' && $sharedPath === '' && $trashPath === '') { $result = ['success' => true]; break; }
                if (function_exists('fsKeepCorruptCopy')) fsKeepCorruptCopy($pathsFile);
            }
            
            if (!fsWriteFileAtomic($pathsFile, json_encode($paths, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE))) {   // ★ (2026-11-04) 56차 C1-5 — 임시 파일+rename(종전 덮어쓰기 실패는 경고→예외로 오류 응답이었음 → 같은 '실패' 응답)
                $result = ['success' => false, 'error' => __('settings_file_save_fail', '설정 파일 저장에 실패했습니다.')];
                break;
            }

            // 경로가 실제로 변경되었는지 확인
            $changed = false;
            if (($oldPaths['user_files_root'] ?? '') !== $userPath) $changed = true;
            if (($oldPaths['shared_files_root'] ?? '') !== $sharedPath) $changed = true;
            if (($oldPaths['trash_path'] ?? '') !== $trashPath) $changed = true;
            
            $result = ['success' => true];
            if ($changed) {
                $result['message'] = __('path_settings_saved');
            }
            break;
        
        // ===== 회원가입 설정 확인 (공개) =====
        case 'signup_status':
            $settings = $db->load('settings');
            $users = $db->load('users') ?: [];
            
            // 사용자가 없으면 첫 관리자 가입을 위해 자동 허용
            // ★ (2026-10-31 13:19, 34차 후속 개선) users.json 이 손상돼 빈 표로 읽힌 경우는 '첫 사용자' 가 아님(아무나 관리자로 가입되던 것)
            $isFirstUser = empty($users) && !$db->isCorrupt('users') && !$db->hasInstallTraces();   // ★ (2026-11-11 12:24, 73차) 설치 흔적(JsonDB::hasInstallTraces)이 있으면 users.json 이 비어도 첫 사용자 아님(MIG_73 #4)
            $signupEnabled = $isFirstUser || ($settings['signup_enabled'] ?? false);
            
            $result = [
                'success' => true, 
                'signup_enabled' => $signupEnabled,
                'is_first_user' => $isFirstUser,
                'password_reset_enabled' => $settings['password_reset_enabled'] ?? false
            ];
            break;
        
        // ===== 비밀번호 찾기 (이메일) =====
        case 'find_username':
            // ★ (2026-10-29 21:16, 24차 점검) '비밀번호 찾기' 기능이 켜진 때만(같은 화면 묶음 — 22차 password_reset_request 와 같은 기준) — 종전엔 꺼져 있어도 API 로 아이디 안내 메일을 계속 보내게 할 수 있었음
            if (empty(($db->load('settings') ?: [])['password_reset_enabled'])) {
                $result = ['success' => false, 'error' => __('api_err_feature_disabled', '사용할 수 없는 기능입니다.')];
                break;
            }
            $email = trim($input['email'] ?? '');
            
            if (empty($email)) {
                $result = ['success' => false, 'error' => __('api_err_enter_email', '이메일을 입력해주세요.')];
                break;
            }
            
            $result = $auth->findUsername($email);
            break;
        
        case 'password_reset_request':
            // ★ (2026-10-29 18:30, 22차 점검) 관리자가 '비밀번호 찾기'를 켜 둔 때만(기본 꺼짐) — 종전엔 화면에서만 숨기고 API 는 늘 받아, 아이디·메일을 아는 사람이
            //   기능이 꺼져 있어도 남의 비밀번호를 임시 비밀번호로 바꾸고 로그인 유지를 끊을 수 있었음
            if (empty(($db->load('settings') ?: [])['password_reset_enabled'])) {
                $result = ['success' => false, 'error' => __('api_err_feature_disabled', '사용할 수 없는 기능입니다.')];
                break;
            }
            $username = trim($input['username'] ?? '');
            $email = trim($input['email'] ?? '');
            
            if (empty($username) || empty($email)) {
                $result = ['success' => false, 'error' => __('api_err_enter_id_email', '아이디와 이메일을 입력해주세요.')];
                break;
            }
            
            $result = $auth->requestPasswordReset($username, $email);
            break;
        
        // ===== 회원가입 =====
        case 'signup':
            $settings = $db->load('settings');
            $users = $db->load('users') ?: [];
            
            // 사용자가 없으면 첫 관리자 가입 허용
            $isFirstUser = empty($users) && !$db->isCorrupt('users') && !$db->hasInstallTraces();   // ★ (2026-10-31 13:19, 34차 후속 개선) 손상된 users.json 은 첫 사용자로 보지 않음   // ★ (2026-11-11 12:24, 73차) 설치 흔적이 있어도 아님(위 signup_status 와 같음)
            
            // 회원가입 허용 여부 확인 (첫 사용자는 항상 허용)
            if (!$isFirstUser && !($settings['signup_enabled'] ?? false)) {
                $result = ['success' => false, 'error' => __('api_signup_disabled', '회원가입이 비활성화되어 있습니다.')];
                break;
            }
            
            $username = trim($input['username'] ?? '');
            $password = $input['password'] ?? '';
            $displayName = trim(fsStripBidi((string)($input['display_name'] ?? '')));   // ★ (2026-11-17 09:41, 307차 재검토 — 303차 누락) 회원가입도 표시 이름의 방향 뒤집기 문자를 뺌 — 가입은 Auth::createUser 를 거치지 않고 따로 저장해 303차 수정이 닿지 않았음(재현: '\u202e가입'·방향 문자만인 이름이 그대로 저장). 빼서 비면 종전처럼 아이디가 이름
            $email = trim($input['email'] ?? '');
            $termsAgreed = $input['terms_agreed'] ?? false;
            
            // 약관이 활성화되어 있고 내용이 있으면 동의 필수 (첫 사용자는 예외)
            $terms = $db->load('terms');
            if (!$isFirstUser && !empty($terms['enabled']) && !empty($terms['content']) && !$termsAgreed) {
                $result = ['success' => false, 'error' => __('api_err_agree_terms', '이용약관에 동의해주세요.')];
                break;
            }
            
            // 유효성 검사
            if (empty($username) || empty($password)) {
                $result = ['success' => false, 'error' => __('api_err_required_id_pw', '아이디와 비밀번호는 필수입니다.')];
                break;
            }
            if (strlen($username) < 3 || strlen($username) > 20) {
                $result = ['success' => false, 'error' => __('api_err_username_length', '아이디는 3~20자여야 합니다.')];
                break;
            }
            if (strlen($password) < 8 || strlen($password) > 72) {
                $result = ['success' => false, 'error' => __('api_err_password_length', '비밀번호는 8자 이상, 72바이트 이하여야 합니다(한글은 1자가 3바이트).')];   // ★ (2026-11-12 10:56, 97차 개선 B2) 문구만 실제 기준(바이트, bcrypt 72바이트)으로 — 종전 '8~72자' 는 한글 30자(90바이트) 거부 때 안내와 맞지 않았음(재현). 받는 기준은 그대로
                break;
            }
            if (!preg_match('/^[a-zA-Z0-9_]+$/', $username)) {
                $result = ['success' => false, 'error' => __('api_err_username_chars', '아이디는 영문, 숫자, 밑줄만 사용 가능합니다.')];
                break;
            }
            if ($displayName !== '' && mb_strlen($displayName) > 30) {
                $result = ['success' => false, 'error' => __('err_display_name_too_long', '표시 이름은 30자 이내로 입력하세요.')];
                break;
            }
            // ★ (2026-11-04) 55차 A1 — 메일은 길이·형식 검사가 없어 비로그인 가입 한 번으로 users.json 이 수 MB 커졌음 → change_email 과 같은 형식 검사 + 254바이트 상한(빈 값은 지금처럼 허용)
            // ★ (2026-11-04) 56차 C7-2 — 형식 검사가 전에 가입되던 '한글@example.com'·'c7@한글도메인.kr' 을 막았음 → 가입은 형식 검사 빼고 254바이트 상한만(55차 전과 같이 형식 통과, change_email 은 그대로)
            if ($email !== '' && strlen($email) > 254) {
                $result = ['success' => false, 'error' => __('err_invalid_email', '올바른 이메일을 입력하세요.')];
                break;
            }

            // 중복 체크
            // ★ (2026-10-29 17:46, 22차 점검) 대소문자 무시 + 예약어('_deleted' 등) — 종전엔 정확히 같은 글자만 막아 'Tester' 가 'tester' 와 같은 홈 폴더(Windows)를 쓰게 됐음
            $unProblem = Auth::usernameProblem($db, $username);
            if ($unProblem === 'exists') {
                $result = ['success' => false, 'error' => __('username_exists')];
                break;
            }
            if ($unProblem === 'reserved') {
                $result = ['success' => false, 'error' => __('api_err_username_chars', '아이디는 영문, 숫자, 밑줄만 사용 가능합니다.')];
                break;
            }
            // ★ (2026-11-02 16:17, 가입 금지 아이디 — 펜닐 요청 "특정일부 아이디는 가입 예외 처리") 첫 사용자(관리자 만들기)는 목록과 상관없이 허용
            if (!$isFirstUser && Auth::signupBlocked($db, $username)) {
                $result = ['success' => false, 'error' => __('api_err_username_blocked', '사용할 수 없는 아이디입니다. 다른 아이디를 입력하세요.')];
                break;
            }
            // ★ (2026-11-03 10:23, 금지 아이디·닉네임 관리 — 펜닐 요청) 금지 닉네임 — 실제로 저장될 이름으로 검사
            //   ★ (2026-11-03 10:57, 재확인) 표시 이름을 비우면 아이디가 이름이 됨 — 종전엔 이 경우를 건너뛰어 금지 닉네임 staff* 가 있어도 아이디 staffer·이름 비움으로 가입하면 이름이 'staffer' 가 됐음(재현)
            if (!$isFirstUser && Auth::nicknameBlocked($db, $displayName !== '' ? $displayName : $username)) {
                $result = ['success' => false, 'error' => __('api_err_nickname_blocked', '사용할 수 없는 이름입니다. 다른 이름을 입력하세요.')];
                break;
            }
            
            // 탈퇴/삭제된 사용자 중복 체크
            $deletedUsers = $db->load('deleted_users') ?: [];
            foreach ($deletedUsers as $du) {
                if (strtolower(trim($du['username'] ?? '')) === strtolower(trim($username))) {
                    $result = ['success' => false, 'error' => __('username_was_withdrawn', '탈퇴 또는 삭제된 아이디입니다. 다른 아이디를 사용해주세요.')];
                    break 2;
                }
            }
            if (Auth::emailInUse($db, $email)) {   // ★ (2026-10-30 01:42, 26차 — 24차 결정 필요 '메일 중복' 자동 선택: 거부)
                $result = ['success' => false, 'error' => __('err_email_in_use', '다른 계정이 이미 쓰는 메일입니다.')];
                break;
            }
            
            // 첫 번째 사용자는 관리자로, 이후는 설정에 따라
            if ($isFirstUser) {
                $role = 'admin';
                $status = 'active';
            } else {
                $role = 'user';
                $autoApprove = $settings['auto_approve'] ?? false;
                $status = $autoApprove ? 'active' : 'pending';
            }
            
            // 기본 용량 설정
            $defaultQuota = (int)($settings['default_quota'] ?? 0);
            
            // 사용자 생성
            // ★ (2026-11-01 17:25, 40차 점검) '첫 사용자=관리자'·아이디 중복 확인이 잠금 밖이라, 동시에 들어온 가입 둘이 모두 admin 이 되거나 같은 아이디(대소문자만 다른 것)
            //   두 계정이 같은 홈 폴더를 쓸 수 있었음 → 추가를 잠금(atomicUpdate) 안에서 하며 표가 비었는지·같은 아이디가 있는지 다시 확인(아이디는 영문·숫자·밑줄만이라 소문자 비교로 충분)
            $suRecord = [
                'username' => $username,
                'password' => password_hash($password, PASSWORD_DEFAULT),
                'display_name' => $displayName ?: $username,
                'email' => $email,
                'role' => $role,
                'status' => $status,
                'quota' => $isFirstUser ? 0 : $defaultQuota,
                'is_active' => 1,
                'created_at' => date('Y-m-d H:i:s'),
                'terms_agreed_at' => $termsAgreed ? date('Y-m-d H:i:s') : null,
                'last_login' => null
            ];
            $id = 0; $suConflict = '';
            $suSaved = $db->atomicUpdate('users', function ($data) use ($db, $suRecord, $isFirstUser, &$id, &$suConflict) {
                $data = is_array($data) ? $data : [];
                if ($isFirstUser && !empty($data)) { $suConflict = 'first'; return $data; }
                foreach ($data as $row) {
                    if (strtolower(trim((string)($row['username'] ?? ''))) === strtolower($suRecord['username'])) { $suConflict = 'exists'; return $data; }
                }
                // ★ (2026-11-03 09:18, 49차 점검) 번호는 JsonDB::reserveId 로(insert 와 같은 규칙·같은 잠금 순서 users→_seq) — 종전엔 '지금 최대+1' 이라 42차 '지운 번호 다시 안 씀'이 회원가입에는 안 걸려,
                //   가장 최근 사용자를 지운 뒤 가입한 사람이 같은 번호(=옛 사용자의 검색 이름·버전·동기화·홈 스토리지 기록)를 받았음(시험 서버 재현: 3 삭제 → 가입 3)
                $id = $db->reserveId('users', empty($data) ? 0 : max(array_map('intval', array_column($data, 'id'))));
                $suRecord['id'] = $id;
                $data[] = $suRecord;
                return $data;
            });
            if ($suConflict !== '' || !$suSaved || !$id) {
                $result = ['success' => false, 'error' => $suConflict === 'exists' ? __('username_exists') : __('api_err_try_again', '잠시 후 다시 시도해 주세요.')];
                break;
            }
            
            // 스토리지별 기본 권한 적용 (첫 사용자 제외)
            if (!$isFirstUser && $id) {
                $storages = $db->load('storages') ?: [];
                foreach ($storages as $s) {
                    $sid = $s['id'] ?? 0;
                    if (!$sid) continue;
                    $defPerms = $s['default_permissions'] ?? [];
                    if (empty($defPerms)) continue;
                    $db->insert('permissions', [
                        'storage_id' => $sid,
                        'user_id' => $id,
                        'can_visible' => (int)($defPerms['can_visible'] ?? 0),
                        'can_visible_webdav' => (int)($defPerms['can_visible_webdav'] ?? 0),
                        'can_read' => (int)($defPerms['can_read'] ?? 0),
                        'can_download' => (int)($defPerms['can_download'] ?? 0),
                        'can_write' => (int)($defPerms['can_write'] ?? 0),
                        'can_delete' => (int)($defPerms['can_delete'] ?? 0),
                        'can_share' => (int)($defPerms['can_share'] ?? 0),
                    ]);
                }
            }
            
            if ($isFirstUser) {
                $result = ['success' => true, 'message' => __('admin_created')];
            } elseif ($status === 'active') {
                $result = ['success' => true, 'message' => __('signup_complete_login')];
            } else {
                $result = ['success' => true, 'message' => __('signup_pending_approval')];
            }
            break;
        
        // ===== 용량 =====
        case 'storage_quota':
            $auth->requireLogin();
            session_write_close(); // 세션 락 해제
            $storageId = (int)($_GET['storage_id'] ?? 0);
            // ★ (2026-10-29 10:45, 20차 점검) 읽을 수 있는 스토리지만(홈은 주인만) — 종전엔 누구나 남의 홈까지 사용량을 보고 폴더 전체를 훑게 할 수 있었음(재현)
            if (!$storage->checkPermission($storageId, 'can_read')) {
                $result = ['success' => false, 'error' => __('no_permission_dot', '권한이 없습니다.')]; break;
            }
            
            // 스토리지 정보 먼저 가져오기
            $storageInfo = $storage->getStorageById($storageId);
            $storageType = $storageInfo['storage_type'] ?? 'local';
            $remoteTypes = ['ftp', 'sftp', 'webdav', 's3', 'smb'];
            
            // 원격/SMB 스토리지: 실제 연결하지 않고 DB 캐시 사용 (블로킹 방지)
            if (in_array($storageType, $remoteTypes)) {
                $used = (int)($storageInfo['used_size'] ?? 0);
                $quota = (int)($storageInfo['quota'] ?? 0);
                
                if ($quota > 0) {
                    $total = $quota;
                    $free = max(0, $quota - $used);
                } elseif ($quota === -1) {
                    // 디스크 용량 표시: 인덱스 기반 사용량
                    $total = 0;
                    $free = 0;
                    // used_size가 없으면 인덱스에서 계산
                    if ($used === 0) {
                        $fileIndex = FileIndex::getInstance();
                        if ($fileIndex->isAvailable()) {
                            $used = $fileIndex->getStorageTotalSize($storageId);
                        }
                    }
                } else {
                    $total = 0;
                    $free = 0;
                }
                
                $lastCalc = (int)($storageInfo['used_size_updated_at'] ?? 0);
                $result = [
                    'success' => true,
                    'used' => $used,
                    'total' => $total,
                    'free' => $free,
                    'quota_set' => $quota > 0,
                    'used_formatted' => $fileManager->formatSize($used),
                    'total_formatted' => $total > 0 ? $fileManager->formatSize($total) : __('unlimited'),
                    'percent' => $total > 0 ? round(($used / $total) * 100, 1) : 0,
                    'needs_recalc' => false
                ];
                break;
            }
            
            $basePath = $storage->getRealPath($storageId);
            
            if ($basePath) {
                
                // home 타입이면 사용자 quota 사용
                $quota = 0;
                if ($storageType === 'home') {
                    // 폴더 사용량 계산 (home은 작으므로 직접 계산)
                    // ★ (2026-11-02 09:06, 41차 점검) 한도 판정(FileManager::checkQuota 홈)이 41차에 숨김(점) 파일 포함으로 바뀌어, 표시만 숨김 제외면
                    //   '남은 용량'이 판정보다 커 보이고 올리면 거부되는 어긋남이 생김 → 표시도 숨김 포함(WebDAV 홈 한도와 같은 기준)
                    $used = $fileManager->getDirectorySize($basePath);
                    
                    // 캐시 우회하여 DB에서 직접 quota 조회
                    $userId = $auth->getUserId();
                    $freshUser = $db->find('users', ['id' => $userId]);
                    $userQuota = (int)($freshUser['quota'] ?? 0);
                    
                    if ($userQuota > 0) {
                        $quota = $userQuota;
                        $total = $userQuota;
                        $free = max(0, $total - $used);
                    } else {
                        // 무제한인 경우
                        $total = 0;
                        $free = 0;
                    }
                } else {
                    // shared/local 타입: DB 캐싱된 used_size 사용 (빠름!)
                    $used = (int)($storageInfo['used_size'] ?? 0);
                    $quota = (int)($storageInfo['quota'] ?? 0);
                    
                    if ($quota > 0) {
                        // 용량 직접 설정
                        $total = $quota;
                        $free = max(0, $quota - $used);
                    } else if ($quota === -1) {
                        // 디스크 용량 표시 모드
                        $diskTotal = @disk_total_space($basePath);
                        $diskFree = @disk_free_space($basePath);
                        if ($diskTotal !== false && $diskTotal > 0) {
                            $total = $diskTotal;
                            $free = $diskFree ?: 0;
                            $used = $diskTotal - ($diskFree ?: 0);
                        } else {
                            $total = 0;
                            $free = 0;
                        }
                    } else {
                        // 무제한 (quota=0)
                        $total = 0;
                        $free = 0;
                    }
                }
                
                $result = [
                    'success' => true,
                    'used' => $used,
                    'total' => $total,
                    'free' => $free,
                    'quota_set' => ($quota ?? 0) > 0,
                    'used_formatted' => $fileManager->formatSize($used),
                    'total_formatted' => $total > 0 ? $fileManager->formatSize($total) : __('unlimited'),
                    'percent' => $total > 0 ? round(($used / $total) * 100, 1) : 0
                ];
                
                // 백그라운드 사용량 재계산이 필요한지 플래그 전달
                if ($storageType !== 'home') {
                    $lastCalc = (int)($storageInfo['used_size_updated_at'] ?? 0);
                    $result['needs_recalc'] = ($lastCalc === 0 || (time() - $lastCalc) >= 60);
                }
            } else {
                $result = ['success' => false, 'error' => __('no_storage')];
            }
            break;
        
        // 스토리지 사용량 백그라운드 재계산 (JS에서 비동기 호출)
        case 'storage_recalc':
            $auth->requireLogin();
            session_write_close();
            @set_time_limit(30);
            $storageId = (int)($_GET['storage_id'] ?? 0);
            // ★ (2026-10-29 10:45, 20차 점검) 읽을 수 있는 스토리지만 다시 계산(남의 스토리지 전체 훑기 막음). 화면이 조용히 넘어가게 종전 '안 함' 응답과 같은 모양
            if (!$storage->checkPermission($storageId, 'can_read')) {
                $result = ['success' => true, 'recalculated' => false]; break;
            }
            
            try {
                $recalcStorageInfo = $storage->getStorageById($storageId);
                if (!$recalcStorageInfo) {
                    $result = ['success' => true, 'recalculated' => false];
                    break;
                }
                $recalcType = $recalcStorageInfo['storage_type'] ?? '';
                // home, shared, local만 용량 계산 (나머지 전부 건너뛰기)
                if (!in_array($recalcType, ['home', 'shared', 'local'])) {
                    $result = ['success' => true, 'recalculated' => false];
                    break;
                }
                
                ignore_user_abort(true);
                // 재계산 주기: 시스템설정에서 지정 (분 단위, 기본 60분)
                // 업로드/삭제 시 updateUsedSize()가 즉시 반영하므로 주기 재계산은 보정 역할
                $recalcSettings = $db->load('settings') ?: [];
                $recalcIntervalMin = (int)($recalcSettings['storage_recalc_interval_minutes'] ?? 60);
                if ($recalcIntervalMin < 1) $recalcIntervalMin = 60;
                
                $recalcStart = microtime(true);
                $recalcUsedBefore = (int)($recalcStorageInfo['used_size'] ?? 0);
                $recalcResult = $storage->backgroundRecalcIfNeeded($storageId, $recalcIntervalMin * 60);
                $recalcElapsed = microtime(true) - $recalcStart;
                
                // 성능 로그: data/scan_perf.log 파일 있을 때만 기록
                // 실제 계산이 돈 경우(recalcResult=true)만 기록
                if ($recalcResult) {
                    $perfLog = DATA_PATH . '/scan_perf.log';
                    if (is_file($perfLog)) {
                        // 5MB 초과 시 뒤쪽 50%만 유지 (로그 파일 비대화 방지)
                        if (filesize($perfLog) > 5 * 1024 * 1024) {
                            $c = @file_get_contents($perfLog);
                            if ($c !== false) @file_put_contents($perfLog, substr($c, strlen($c) / 2));
                        }
                        $updatedStorage = $storage->getStorageById($storageId);
                        $usedAfter = (int)($updatedStorage['used_size'] ?? 0);
                        $diff = $usedAfter - $recalcUsedBefore;
                        $sizeGb = round($usedAfter / 1024 / 1024 / 1024, 2);
                        $diffMb = round($diff / 1024 / 1024, 2);
                        @file_put_contents($perfLog,
                            sprintf("[%s] storage_recalc done storage_id=%d name=%s elapsed=%.1fs size=%sGB delta=%sMB\n",
                                date('Y-m-d H:i:s'), $storageId,
                                substr($recalcStorageInfo['name'] ?? '?', 0, 30),
                                $recalcElapsed, $sizeGb, $diffMb),
                            FILE_APPEND | LOCK_EX);
                    }
                }
                $result = ['success' => true, 'recalculated' => $recalcResult];
            } catch (\Throwable $e) {
                $result = ['success' => true, 'recalculated' => false];
            }
            break;
        
        // ===== 휴지통 =====
        case 'trash_list':
            $auth->requireLogin();
            $user = $auth->getUser();
            session_write_close(); // 세션 락 해제
            $all = isset($_GET['all']) && $_GET['all'] === 'true' && ($user['role'] ?? '') === 'admin';
            
            $userId = $all ? null : $user['id'];
            $result = $fileManager->getTrashList($userId);
            // ★ (2026-11-14 22:28, 141차) 전체 휴지통(관리자)에서 남의 '내 파일' 항목은 복원이 늘 '쓰기 권한이 없습니다'로 실패함(복원은 원래 스토리지 쓰기 권한을 봄)
            //   → 복원 단추를 감출 수 있게 항목마다 지금 사용자가 원래 스토리지에 쓸 수 있는지(참/거짓)만 붙임. 복원 검사·권한은 그대로
            if ($all && !empty($result['items']) && is_array($result['items'])) {
                foreach ($result['items'] as &$tlCrItem) {
                    $tlCrItem['can_restore'] = $storage->checkPermission((int)($tlCrItem['storage_id'] ?? 0), 'can_write');
                }
                unset($tlCrItem);
            }
            break;

        case 'trash_restore':
            $auth->requireLogin();
            session_write_close(); // 세션 락 해제
            $user = $auth->getUser();
            $id = $input['id'] ?? '';
            
            // 권한 확인
            $trash = $db->load('trash');
            $item = null;
            foreach ($trash as $t) {
                if ($t['id'] === $id) {
                    $item = $t;
                    break;
                }
            }
            
            if (!$item) {
                $result = ['success' => false, 'error' => __('item_not_found')];
                break;
            }
            
            // 관리자이거나 본인이 삭제한 것만 복원 가능
            if (($user['role'] ?? '') !== 'admin' && ($item['deleted_by'] ?? 0) !== $user['id']) {
                $result = ['success' => false, 'error' => __('no_permission')];
                break;
            }
            
            $result = $fileManager->restoreFromTrash($id);
            
            // 복원 로그
            if ($result['success'] ?? false) {
                $activityLog->log(ActivityLog::TYPE_RESTORE, [
                    'storage_id' => $item['storage_id'] ?? 0,
                    'storage_name' => $item['storage_name'] ?? (($storage->getStorageById((int)($item['storage_id'] ?? 0)) ?: [])['name'] ?? ''),   // ★ (2026-11-04) 56차 휴지통 기록엔 이름 칸이 없어 늘 빈 값이었음 → 스토리지에서 조회(작업 큐 복원과 같음)
                    'path' => $item['original_path'] ?? '',
                    'filename' => $item['name'] ?? ''
                ]);
                
                // 인덱스 갱신
                // ★ (2026-11-01 11:36, 39차 점검) 로컬 복원은 restoreFromTrash 가 실제 놓인 경로로 reindexPath 를 이미 함. 여기서 original_path 로
                //   한 번 더 넣어 수정 시각을 '지금'으로 덮고, 이름이 겹쳐 'X (1)' 로 복원되면 원래 있던 'X' 의 기록을 건드렸음
                //   → 원격일 때만(작업 큐 복원 JobManager 와 같은 기준)
                $fileIndex = FileIndex::getInstance();
                if (!empty($result['remote']) && $fileIndex->isAvailable()) {
                        $restoredStorageId = (int)($item['storage_id'] ?? 0);
                        $restoredPath = $item['original_path'] ?? '';
                        // ★ (2026-10-29 23:42, 24차 점검) 원격 복원은 같은 이름이 있으면 'X (1)' 로 올라가므로 실제 이름으로 경로를 다시 만듦(종전엔 원래 항목을 크기 0으로 덮음)
                        if (!empty($result['remote']) && !empty($result['restored_path'])) {
                            $_rsDir = dirname(str_replace('\\', '/', $restoredPath));
                            $restoredPath = (($_rsDir === '.' || $_rsDir === '/' || $_rsDir === '') ? '' : $_rsDir . '/') . $result['restored_path'];
                        }
                        $basePath = $storage->getRealPath($restoredStorageId);
                        $fullPath = $basePath . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $restoredPath);
                        // ★ (2026-10-28) 원격 스토리지로 복원하면 로컬 경로가 빈 문자열이라 서버 루트 경로(예 /mnt)를 보게 됨 → 로컬 경로가 있을 때만 폴더 인덱싱·크기 읽기(아니면 종전 기본값)
                        if ($basePath && is_dir($fullPath)) {
                            $fileIndex->indexFolder($restoredStorageId, $basePath, $restoredPath);
                        } else {
                            $fileIndex->addFile($restoredStorageId, $restoredPath, [
                                'name' => !empty($result['remote']) ? basename($restoredPath) : ($item['name'] ?? basename($restoredPath)),
                                'size' => ($basePath && is_file($fullPath)) ? filesize($fullPath) : ((!$basePath && empty($item['is_dir'])) ? max(0, (int)($item['size'] ?? 0)) : 0),   // ★ (2026-10-30 01:50, 26차 점검) 원격 파일은 휴지통 기록 크기(작업 큐 복원과 같게 — 종전 0)
                                'modified' => time(),
                                'is_dir' => (!$basePath && !empty($item['is_dir'])) ? 1 : 0   // ★ (2026-10-29 23:42, 24차 점검) 원격 복원은 휴지통 기록의 폴더 여부로
                            ]);
                            if (!$basePath) {   // ★ (2026-11-04, 55차 점검) 원격: 다시 만들어진 조상 폴더 행(D5)·폴더 복원의 하위 색인(X-1) — 작업 큐 복원(JobManager)과 같음
                                JobManager::indexRemoteAncestors($restoredStorageId, $restoredPath);
                                if (!empty($item['is_dir'])) JobManager::indexRemoteTree($fileManager, $restoredStorageId, $restoredPath);
                            }
                        }
                }
            }
            break;
            
        case 'trash_delete':
            $auth->requireLogin();
            $user = $auth->getUser();
            $id = $input['id'] ?? '';
            
            // 권한 확인
            $trash = $db->load('trash');
            $item = null;
            foreach ($trash as $t) {
                if ($t['id'] === $id) {
                    $item = $t;
                    break;
                }
            }
            
            if (!$item) {
                $result = ['success' => false, 'error' => __('item_not_found')];
                break;
            }
            
            // 권한 확인
            if (($user['role'] ?? '') !== 'admin' && ($item['deleted_by'] ?? 0) !== $user['id']) {
                $result = ['success' => false, 'error' => __('no_permission')];
                break;
            }
            
            session_write_close();
            @set_time_limit(0);
            
            // 폴더인 경우 진행률 파일 생성
            $progressFile = '';
            if (!empty($item['is_dir'])) {
                $dataDir = defined('DATA_PATH') ? DATA_PATH : (__DIR__ . '/data');
                $progressFile = $dataDir . '/delete_progress_' . md5($id) . '.tmp';
            }
            
            $result = $fileManager->deleteFromTrash($id, $progressFile);
            break;
            
        case 'trash_empty':
            $auth->requireLogin();
            $user = $auth->getUser();
            $all = isset($input['all']) && $input['all'] === true && ($user['role'] ?? '') === 'admin';
            
            $userId = $all ? null : $user['id'];
            $result = $fileManager->emptyTrash($userId);
            break;
        
        // ===== 조건부 일괄 삭제 =====
        case 'bulk_search':
            $auth->requireAdminPerm('storages');
            $patterns = $input['patterns'] ?? [];
            if (is_string($patterns)) {
                $patterns = array_values(array_filter(array_map('trim', explode("\n", $patterns)), 'strlen'));   // ★ (2026-11-01 17:27, 40차 점검) 콜백 없는 array_filter 가 패턴 '0' 을 버렸음 → 빈 줄만 뺌
            }
            $patterns = is_array($patterns) ? array_values(array_filter($patterns, 'is_string')) : [];   // ★ (2026-11-04) 56차 C6#2 — 숫자·bool·중첩 배열이면 TypeError 500 → 글자 항목만(화면은 글자만 보냄)
            $result = $fileManager->bulkSearch(
                (int)($input['storage_id'] ?? 0),
                $input['path'] ?? '',
                $patterns,
                $input['scope'] ?? 'recursive',
                $input['type'] ?? 'all'
            );
            // ★ (2026-11-02 10:31, 42차 점검) 검색은 1000건에서 끊기는데(FileManager::bulkSearch) 잘렸다는 표시가 없어 '전부 지움'이 앞 1000개만 지웠음(E8#12) → 1000건이면 truncated(더 있을 수 있음)
            if (is_array($result) && !empty($result['success']) && !isset($result['truncated'])) $result['truncated'] = count($result['items'] ?? []) >= 1000;
            break;
            
        case 'bulk_delete':
            $auth->requireAdminPerm('storages');
            $result = $fileManager->bulkDelete(
                (int)($input['storage_id'] ?? 0),
                is_array($input['paths'] ?? null) ? array_values(array_filter($input['paths'], 'is_string')) : []   // ★ (2026-11-04) 56차 C6#2 — 문자열·중첩 배열이면 TypeError 500 → 글자 항목만(화면은 경로 글자 배열)
            );
            break;
            
        // ===== 백신 설정 (관리자) =====
        case 'antivirus_settings':
            $auth->requireRealAdmin();
            $settings = $db->load('antivirus_settings');
            if (empty($settings)) {
                $settings = [
                    'engine' => 'disabled',
                    'max_size' => 100,
                    'clamav_path' => '',
                    'defender_path' => '',
                    'block_on_error' => false
                ];
            }
            
            $result = [
                'success' => true,
                'settings' => $settings
            ];
            break;
            
        case 'antivirus_settings_save':
            $auth->requireRealAdmin();
            
            $settings = [
                'engine' => in_array($input['engine'] ?? 'disabled', ['disabled', 'clamav', 'defender'], true)   // ★ (2026-11-01 17:22, 40차 점검) 엄격 비교 — 느슨하면 JSON true 가 저장됐음
                    ? ($input['engine'] ?? 'disabled') : 'disabled',
                'max_size' => max(0, (int)($input['max_size'] ?? 100)),
                'clamav_path' => trim($input['clamav_path'] ?? ''),
                'defender_path' => trim($input['defender_path'] ?? ''),
                'block_on_error' => (bool)($input['block_on_error'] ?? false)
            ];
            
            $db->save('antivirus_settings', $settings);
            
            // config용 JSON 파일도 저장 (FileManager에서 로드)
            fsWriteFileAtomic(DATA_PATH . '/antivirus_config.json', json_encode($settings, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));   // ★ (2026-11-04) 56차 C1-5 — 임시 파일+rename(종전처럼 결과는 안 봄)
            
            $result = ['success' => true];
            break;
            
        case 'antivirus_test':
            $auth->requireRealAdmin();
            $fm = new FileManager();
            $result = $fm->testAntivirus();
            break;
            
        case 'antivirus_logs':
            $auth->requireRealAdmin();
            
            $page = max(1, (int)($input['page'] ?? 1));
            $perPage = min(100, max(10, (int)($input['per_page'] ?? 50)));
            $dateFrom = $input['date_from'] ?? '';
            $dateTo = $input['date_to'] ?? '';
            
            $logFile = DATA_PATH . '/antivirus_scan_logs.json';
            $allLogs = [];
            if (file_exists($logFile)) {
                $allLogs = json_decode(file_get_contents($logFile), true) ?: [];
            }
            
            // 날짜 필터링
            $filteredLogs = [];
            $cleanCount = 0;
            $threatCount = 0;
            
            foreach ($allLogs as $log) {
                $logDate = substr($log['time'] ?? '', 0, 10);
                
                if ($dateFrom && $logDate < $dateFrom) continue;
                if ($dateTo && $logDate > $dateTo) continue;
                
                $filteredLogs[] = $log;
                if ($log['clean'] ?? true) {
                    $cleanCount++;
                } elseif (empty($log['scan_error_blocked'])) {   // ★ (2026-11-12 08:57, 96차 AV-2) '검사 오류로 차단'은 위협에 세지 않음 — 종전엔 검사기 없음 + '오류 시 차단'으로 막힌 2건이 바이러스 0건인데 '위협 2건'(재현). 이 표시가 없는 옛 기록은 종전처럼 셈
                    $threatCount++;
                }
            }
            
            // 역순 정렬 (최신순)
            $filteredLogs = array_reverse($filteredLogs);
            
            $total = count($filteredLogs);
            $offset = ($page - 1) * $perPage;
            $offset = ($offset >= PHP_INT_MAX) ? PHP_INT_MAX : (int)$offset;   // ★ (2026-11-02 10:58, 42차 재검토) '>=' — 정확히 2^63(float)이면 '>' 가 거짓이라 (int) 가 음수로 넘쳐 첫 쪽이 나왔음   // ★ (2026-11-02 10:31, 42차 점검) 아주 큰 page 면 float 로 넘쳐 array_slice TypeError(500)였음(E8#6) → 정수 범위로 자름(빈 쪽)
            $logs = array_slice($filteredLogs, $offset, $perPage);
            
            $result = [
                'success' => true,
                'logs' => $logs,
                'total' => $total,
                'page' => $page,
                'per_page' => $perPage,
                'clean_count' => $cleanCount,
                'threat_count' => $threatCount
            ];
            break;
            
        case 'antivirus_logs_delete':
            $auth->requireRealAdmin();
            
            $dateFrom = $input['date_from'] ?? '';
            $dateTo = $input['date_to'] ?? '';
            
            if (empty($dateFrom) && empty($dateTo)) {
                $result = ['success' => false, 'error' => __('api_err_specify_delete_date', '삭제할 날짜 범위를 지정하세요.')];
                break;
            }
            
            $logFile = DATA_PATH . '/antivirus_scan_logs.json';
            $deletedCount = 0;
            // ★ (2026-11-01 17:31, 40차 점검) 잠금 안에서 읽고 거르고 씀(fsJsonLogRewrite 주석) — 종전엔 잠금 없이 써서 그사이 기록이 사라졌고 깨진 파일이면 전체가 지워졌음
            $avOk = fsJsonLogRewrite($logFile, function ($allLogs) use ($dateFrom, $dateTo, &$deletedCount) {
                $remainingLogs = [];
                foreach ($allLogs as $log) {
                    $logDate = substr((string)($log['time'] ?? ''), 0, 10);
                    $shouldDelete = true;
                    
                    if ($dateFrom && $logDate < $dateFrom) $shouldDelete = false;
                    if ($dateTo && $logDate > $dateTo) $shouldDelete = false;
                    
                    if ($shouldDelete) {
                        $deletedCount++;
                    } else {
                        $remainingLogs[] = $log;
                    }
                }
                return $remainingLogs;
            });
            
