                $result = ['success' => false, 'error' => __('sec_list_invalid', 'IP·국가 목록에 형식이 맞지 않는 항목이 있어 저장하지 않았습니다') . ': ' . implode(', ', array_slice(array_map(function ($d) { return mb_substr((string)$d, 0, 60); }, array_unique($secDropped)), 0, 10))];
