                    }
                    
                    if (count($realtimeResults) >= 200) $_saTrunc = true;   // ★ (2026-11-02 14:39, 44차 점검) 실시간 순회는 200건에서 멈춤 — 다 찼으면 잘렸을 수 있음(truncated)
                    foreach ($realtimeResults as $item) {
                        $item['storage_id'] = $storageId;
                        $item['storage_name'] = $sName;
                        $searchResults[] = $item;
                    }
                }
            } else {
                // 전체 스토리지 검색 (사용자 접근 가능한 스토리지만, 무제한)
                $userStorages = $storage->getStorages();
                
                // 스토리지 ID -> 이름 매핑 생성
                $storageNames = [];
                $allowedStorageIds = [];
                foreach ($userStorages as $category => $storageList) {
                    // getStorages()는 카테고리별로 반환 (home, public, shared)
                    if (is_array($storageList)) {
                        foreach ($storageList as $st) {
                            $sid = (int)($st['id'] ?? 0);
                            // ★ (2026-10-28) 보이기만 하고 읽기 권한이 없는(can_read=0) 스토리지는 빼기 — search_all 과 같은 기준
                            if ($sid > 0 && !empty($st['can_read'])) {
                                $storageNames[$sid] = $st['name'] ?? '';
                                $allowedStorageIds[] = $sid;
                            }
                        }
                    }
                }
                
                // 허용된 스토리지에서만 검색 (FileIndex가 storage_id 반환)
                if (!empty($allowedStorageIds)) {
                    $results = $fileIndex->search($query, $allowedStorageIds, $_saLimit + 1);   // ★ (2026-11-02 14:39, 44차 점검) 위 특정 스토리지와 같은 상한·잘림 표시(G1#8)
                    if (count($results) > $_saLimit) { $_saTrunc = true; $results = array_slice($results, 0, $_saLimit); }
                    foreach ($results as $item) {
                        // FileIndex가 반환한 storage_id 사용
                        $sid = (int)($item['storage_id'] ?? 0);
                        $item['storage_name'] = $storageNames[$sid] ?? '';
                        $searchResults[] = $item;
                    }
                }
            }
            
            // ★ (2026-10-28, 펜닐 승인) 결과 경로 — 인덱스 검색(FileIndex::search)은 'path', 실시간 검색은 'filepath'(+'path') 로 줌.
            //   아래 필터·정렬이 'filepath' 만 읽어서 인덱스 결과에선 빈 문자열이 됐음
            //   → 유형·경로 필터 결과 0개, 폴더 권한 필터가 아무것도 못 거름(읽기 금지 폴더 안 파일이 검색에 보임), 이름·유형 정렬 안 됨
            $_srPath = function ($item) { return (string)($item['filepath'] ?? ($item['path'] ?? '')); };
            
            // 필터 적용
            if (!empty($fileType) && $fileType !== 'all') {
                $typeExtensions = [
                    'image' => ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'svg', 'ico'],
                    'video' => ['mp4', 'webm', 'avi', 'mkv', 'mov', 'wmv', 'flv'],
                    'audio' => ['mp3', 'wav', 'ogg', 'flac', 'aac', 'm4a', 'wma'],
                    'document' => ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'txt', 'rtf', 'odt', 'hwp', 'hwpx'],   // ★ (2026-11-11 18:30, 79차 IDX-5) 한글 문서(hwp·hwpx)도 — 종전엔 유형 '문서'에 빠져 검색어 보고서의 hwp 1,226건이 모두 걸러졌음(재현)
                    'archive' => ['zip', 'rar', '7z', 'tar', 'gz', 'bz2']
                ];
                
                if (isset($typeExtensions[$fileType])) {
                    $allowedExts = $typeExtensions[$fileType];
                    $searchResults = array_filter($searchResults, function($item) use ($allowedExts, $_srPath) {
                        $ext = strtolower(pathinfo($_srPath($item), PATHINFO_EXTENSION));
                        return in_array($ext, $allowedExts);
                    });
                }
            }
            
            // 날짜 필터
            if (!empty($dateFrom)) {
                $fromTime = strtotime($dateFrom);
                $searchResults = array_filter($searchResults, function($item) use ($fromTime) {
                    return strtotime($item['modified'] ?? 0) >= $fromTime;
                });
            }
            if (!empty($dateTo)) {
                $toTime = strtotime($dateTo . ' 23:59:59');
                $searchResults = array_filter($searchResults, function($item) use ($toTime) {
                    return strtotime($item['modified'] ?? 0) <= $toTime;
                });
            }
            
            // 크기 필터
            if ($sizeMin > 0) {
                $searchResults = array_filter($searchResults, function($item) use ($sizeMin) {
                    return ($item['size'] ?? 0) >= $sizeMin;
                });
            }
            if ($sizeMax > 0) {
                $searchResults = array_filter($searchResults, function($item) use ($sizeMax) {
                    return ($item['size'] ?? 0) <= $sizeMax;
                });
            }
            
            // 경로 필터
            if (!empty($searchPath)) {
                $searchResults = array_filter($searchResults, function($item) use ($searchPath, $_srPath) {
                    return strpos($_srPath($item), $searchPath) === 0;
                });
            }
            
            // 폴더별 권한 필터링 (검색 결과에서 접근 불가 폴더 제외 - 관리자 포함)
            $searchResults = array_filter($searchResults, function($item) use ($storage, $_srPath) {
                $sid = (int)($item['storage_id'] ?? 0);
                $filepath = $_srPath($item);
                $dirPath = dirname($filepath);
                if ($dirPath !== '.' && $dirPath !== '' && !$storage->checkFolderPermission($sid, $dirPath)) return false;
                // ★ (2026-11-01 01:50, 36차 전체 점검) 폴더 항목은 그 폴더 자신의 '보기' 규칙도(옛 검색 _fsFilterSearchResults 35차와 같게) — 화면이 실제로 쓰는 이 검색에는 빠져 있어
                //   목록에서 숨긴 폴더 이름이 검색 결과에 그대로 나왔음(루트 바로 아래 폴더 포함)
                if (!empty($item['is_dir'])) {
                    $fpDir = ($dirPath === '.' || $dirPath === '/') ? '' : $dirPath;
                    if (!$storage->filterByFolderPermission($sid, $fpDir, [['name' => basename(str_replace('\\', '/', $filepath)), 'is_dir' => true]])) return false;
                }
                return true;
            });
            // ★ (2026-10-28, 펜닐) 숨김 항목 — 자기 자신이나 상위 폴더가 숨김(시스템 이름·~$·속성 숨김)이면 빼고,
            //   '숨김 항목 보기'(show_hidden)면 hidden 표시를 달아 남김 — 페이지 나누기 전에 걸러 개수도 맞음
            $_hidShow = !empty($input['show_hidden']); $_hidMaps = [];
            $_hidOut = [];
            foreach ($searchResults as $item) {
                $sid = (int)($item['storage_id'] ?? 0);
                if (!isset($_hidMaps[$sid])) $_hidMaps[$sid] = HiddenItems::mapFor($sid);
                if (HiddenItems::isHiddenPath($sid, $_srPath($item), $_hidMaps[$sid])) {
                    if (!$_hidShow) continue;
                    $item['hidden'] = true;
                }
                $_hidOut[] = $item;
            }
            $searchResults = $_hidOut;
            $searchResults = array_values($searchResults);
            
            // 정렬 적용
            $sortBy = $input['sort_by'] ?? 'name';
            $sortOrder = $input['sort_order'] ?? 'asc';
            
            usort($searchResults, function($a, $b) use ($sortBy, $sortOrder, $_srPath) {
                // 폴더 우선
                $aIsDir = $a['is_dir'] ?? 0;
                $bIsDir = $b['is_dir'] ?? 0;
                if ($aIsDir != $bIsDir) {
                    return $bIsDir - $aIsDir; // 폴더가 먼저
                }
                
                // 정렬 기준에 따라
                switch ($sortBy) {
                    case 'size':
                        $cmp = ($a['size'] ?? 0) - ($b['size'] ?? 0);
                        break;
                    case 'date':
                        $cmp = strtotime($a['modified'] ?? '0') - strtotime($b['modified'] ?? '0');
                        break;
                    case 'type':
                        $extA = strtolower(pathinfo($_srPath($a), PATHINFO_EXTENSION));
                        $extB = strtolower(pathinfo($_srPath($b), PATHINFO_EXTENSION));
                        $cmp = strcmp($extA, $extB);
                        break;
                    case 'name':
                    default:
                        $nameA = basename($_srPath($a));
                        $nameB = basename($_srPath($b));
                        $cmp = strnatcmp(strtolower($nameA), strtolower($nameB));   // ★ (2026-11-16 11:54, 227차) 검색 결과 이름순도 파일 목록(FileManager::sortFiles)과 같은 자연 정렬
                        break;
                }
                
                return $sortOrder === 'desc' ? -$cmp : $cmp;
            });
            
            // 페이지네이션 적용
            $searchResults = array_values($searchResults);
            $total = count($searchResults);
            $totalPages = ceil($total / $perPage);
            $offset = ($page - 1) * $perPage;
            $offset = ($offset >= PHP_INT_MAX) ? PHP_INT_MAX : (int)$offset;   // ★ (2026-11-02 10:58, 42차 재검토) '>=' — 정확히 2^63(float)이면 '>' 가 거짓이라 (int) 가 음수로 넘쳐 첫 쪽이 나왔음   // ★ (2026-11-02 10:31, 42차 점검) 아주 큰 page 면 float 로 넘쳐 array_slice TypeError(500)였음(E8#6) → 정수 범위로 자름(빈 쪽)
            $pagedResults = array_slice($searchResults, $offset, $perPage);
            
            $result = [
                'success' => true, 
                'results' => $pagedResults,
                'total' => $total,
                'page' => $page,
                'per_page' => $perPage,
                'total_pages' => $totalPages
            ];
            
            // 실시간 검색 여부 표시
            if ($isRealtimeSearch) {
                $result['realtime'] = true;
            }
            if ($_saTrunc) { $result['truncated'] = true; $result['limit'] = $isRealtimeSearch ? 200 : $_saLimit; }   // ★ (2026-11-02 16:38, 45차 재확인) 화면 안내에 쓸 상한도 함께(화면은 이 값이 없으면 자체 기본값)
              // ★ (2026-11-02 14:39, 44차 점검) 상한에서 잘림 — 표시는 화면 몫(bulk_search 의 truncated 와 같은 이름)
            
            // 전체 검색일 때: 인덱스 재구축을 한 번도 안 한 경우에만 unindexed 안내
            if ($storageId === 0 && !$fileIndex->getMeta('last_rebuild')) {
                $unindexed = [];
                if (!empty($allowedStorageIds)) {
                    if (!isset($indexedIds)) {
                        $indexedIds = $fileIndex->getIndexedStorageIds();
                    }
                    foreach ($allowedStorageIds as $sid) {
                        if (!in_array($sid, $indexedIds)) {
                            $unindexed[] = [
                                'id' => $sid,
                                'name' => $storageNames[$sid] ?? ''
                            ];
                        }
                    }
                }
                if (!empty($unindexed)) {
                    $result['unindexed_storages'] = $unindexed;
                }
            }
            break;
        
        // ========== 네트워크 공유 (SMB) ==========
        case 'search_realtime':
            // 인덱스 없는 스토리지에서 실시간 폴더 순회 검색
            $auth->requireLogin();
            session_write_close();
            @set_time_limit(120);
            @ini_set('memory_limit', '512M');
            try {
                $storageId = (int)($input['storage_id'] ?? 0);
                $query = trim($input['query'] ?? '');
                
                if (!$storageId || $query === '') {   // ★ (2026-11-01 17:27, 40차 점검) 이름·경로·검색어 '0' 이 빈 값으로 취급되던 판정을 === '' 로
                    $result = ['success' => false, 'error' => __('api_err_invalid_param', '잘못된 요청입니다.')];
                    break;
                }
                
                if (!$storage->checkPermission($storageId, 'can_read')) {
                    $result = ['success' => false, 'error' => __('api_err_no_read_perm', '읽기 권한이 없습니다.')];
                    break;
                }
                
                $storageInfo = $storage->getStorageById($storageId);
                $sType = $storageInfo['storage_type'] ?? 'local';
                $remoteAdapterTypes = ['ftp', 'sftp', 'webdav', 's3', 'smb'];
                $results = [];
                $searchLimit = 200;
                
                if (in_array($sType, $remoteAdapterTypes)) {
                    $adapter = StorageAdapterFactory::create($storageInfo);
                    if (!$adapter->connect()) {
                        $result = ['success' => false, 'error' => $adapter->getLastError() ?: __('api_err_connect_failed', '연결 실패')];
                        break;
                    }
                    $fileManager->_searchStartTime = time();
                    $fileManager->searchRemoteRecursive($adapter, '', $query, $results, $searchLimit);
                    $adapter->disconnect();
                } else {
                    // 로컬/SMB: 폴더 순회
                    $storagePath = $storage->getRealPath($storageId);
                    if ($storagePath && is_dir($storagePath)) {
                        $fileManager->searchRecursivePublic($storagePath, $query, $storagePath, $results, $searchLimit);
                    }
                }
                
                foreach ($results as &$r) {
                    $r['storage_id'] = $storageId;
                    $r['storage_name'] = $storageInfo['name'] ?? '';
                }
                unset($r);
                // ★ (2026-10-29 02:36, 16차) 폴더 규칙·숨김을 다른 검색(search·search_all)과 같이 걸러냄 — 종전엔 스토리지 읽기만 봐서
                //   읽기 금지 폴더 안 파일 이름까지 보였음
                $results = _fsFilterSearchResults($storage, $results, $storageId, !empty($_GET['show_hidden']));
                
                $result = ['success' => true, 'results' => $results, 'total' => count($results), 'realtime' => true];
            } catch (Throwable $e) {
                // ★ (2026-10-29 02:36, 16차) 오류 문구에 서버 절대 경로가 섞이지 않게
                $result = ['success' => false, 'error' => str_ireplace([__DIR__, str_replace('\\', '/', __DIR__)], '', $e->getMessage())];
            }
            break;
        
        case 'smb_detect':
        case 'network_share_detect':
            $auth->requireAdminPerm('storages');
            
            session_write_close(); // 세션 락 해제
            $os = PHP_OS_FAMILY;
            $serverIp = $_SERVER['SERVER_ADDR'] ?? $_SERVER['SERVER_NAME'] ?? 'localhost';
            
            $env = [
                'os' => $os,
                'is_docker' => false,
                'hostname' => @gethostname() ?: 'unknown',
                'ip' => $serverIp,
                'exec_enabled' => false,
                'smb_available' => ($os === 'Windows'),
                'existing_shares' => [],
                'storages' => [],
                'share_settings' => [],
            ];
            
            // exec check
            $disabledStr = @ini_get('disable_functions') ?: '';
            $disabledArr = array_map('trim', explode(',', $disabledStr));
            $canExec = function_exists('exec') && !in_array('exec', $disabledArr);
            $env['exec_enabled'] = $canExec;
            
            // Windows: net share (에러 핸들러 비활성)
            if ($canExec && $os === 'Windows') {
                $shareOutput = [];
                $rc = -1;
                set_error_handler(function() {}, E_ALL);
                exec('chcp 65001 >nul 2>&1 & net share 2>&1', $shareOutput, $rc);
                restore_error_handler();
                $shares = [];
                foreach ($shareOutput as $line) {
                    // CP949 → UTF-8 변환
                    if (!mb_check_encoding($line, 'UTF-8')) {
                        $line = @mb_convert_encoding($line, 'UTF-8', 'CP949');
                    }
                    $trimmed = trim($line);
                    if (preg_match('/^([A-Za-z0-9_\-]+)\s+([A-Z]:\\\\.*)$/i', $trimmed, $m)) {
                        $name = $m[1];
                        if (!preg_match('/^(IPC|ADMIN|[A-Z]|print)\$$/i', $name)) {
                            $shares[] = ['name' => $name, 'path' => trim($m[2])];
                        }
                    }
                }
                $env['existing_shares'] = $shares;
            }
            
            // ★ (2026-10-29 11:27, 20차 점검) 화면이 쓰는 Docker 여부·패키지 관리자 채움(다른 환경 감지와 같은 방식) — 종전엔 늘 false·빈 값이라
            //   Docker 안내가 안 나오고 설치 명령도 늘 'Install samba package' 로만 보였음
            if ($os === 'Linux') {
                $env['is_docker'] = file_exists('/.dockerenv') || (is_readable('/proc/1/cgroup') && strpos((string)@file_get_contents('/proc/1/cgroup'), 'docker') !== false);
                if ($canExec) {
                    foreach (['apt' => 'apt-get', 'yum' => 'yum', 'apk' => 'apk'] as $pmKey => $pmBin) {
                        $pmOut = []; $pmRc = 1;
                        set_error_handler(function() {}, E_ALL);
                        exec('which ' . $pmBin . ' 2>/dev/null', $pmOut, $pmRc);
                        restore_error_handler();
                        if ($pmRc === 0) { $env['pkg_manager'] = $pmKey; break; }
                    }
                }
            }
            
            // Linux: Samba
            if ($canExec && $os === 'Linux') {
                $smbdOut = [];
                set_error_handler(function() {}, E_ALL);
                exec('which smbd 2>/dev/null', $smbdOut, $smbdRc);
                restore_error_handler();
                $env['smb_available'] = ($smbdRc === 0);
                if ($smbdRc === 0) {
                    $svcOut = [];
                    set_error_handler(function() {}, E_ALL);
                    exec('systemctl is-active smbd 2>/dev/null', $svcOut, $svcRc);
                    restore_error_handler();
                    $env['smb_running'] = ($svcRc === 0);
                    if (@is_readable('/etc/samba/smb.conf')) {
                        $conf = @file_get_contents('/etc/samba/smb.conf') ?: '';
                        $shares = [];
                        preg_match_all('/\[([^\]]+)\]\s*\n(?:[^\[]*?path\s*=\s*(.+))/m', $conf, $matches, PREG_SET_ORDER);
                        foreach ($matches as $m) {
                            $name = trim($m[1]);
                            if (!in_array(strtolower($name), ['global', 'homes', 'printers'])) {
                                $shares[] = ['name' => $name, 'path' => trim($m[2])];
                            }
                        }
                        $env['existing_shares'] = $shares;
                    }
                } else {
                    $env['smb_running'] = false;
                }
            }
            
            // 스토리지
            $storages = $db->load('storages');
            $storageList = [];
            if (is_array($storages)) {
                foreach ($storages as $sid => $s) {
                    $path = $s['path'] ?? '';
                    $name = $s['name'] ?? "Storage $sid";
                    // UTF-8 보장
                    if (!mb_check_encoding($path, 'UTF-8')) {
                        $path = @mb_convert_encoding($path, 'UTF-8', 'CP949');
                    }
                    if (!mb_check_encoding($name, 'UTF-8')) {
                        $name = @mb_convert_encoding($name, 'UTF-8', 'CP949');
                    }
                    $storageList[] = [
                        'id' => (string)($s['id'] ?? $sid),   // ★ (2026-10-29 10:11, 20차 점검) 실제 스토리지 번호 — 종전엔 배열 순번이라 공유 만들기(network_share_create)가 엉뚱한 스토리지를 찾았음(재현)
                        'name' => $name,
                        'path' => $path,
                        'exists' => !empty($path) && @is_dir($path),
                    ];
                }
            }
            $env['storages'] = $storageList;
            
            // 공유 설정
            $shareSettingsFile = DATA_PATH . '/network_share_settings.json';
            if (@file_exists($shareSettingsFile)) {
                $raw = @file_get_contents($shareSettingsFile);
                if ($raw) {
                    $decoded = @json_decode($raw, true);
                    if (is_array($decoded)) $env['share_settings'] = $decoded;
                }
            }
            
            $result = ['success' => true, 'env' => $env];
            break;
            
        case 'network_share_create':
            $auth->requireRealAdmin();   // ★ (2026-11-01 17:19, 40차 점검) 서버 OS 설정(net share·smb.conf·Samba 계정)을 바꾸는 기능이라 실제 관리자만 — 종전엔 '스토리지' 권한 부관리자가 권한 없는 로컬 스토리지 경로를 OS 공유로 열 수 있었음(37차 '로컬 경로는 관리자만' 결정보다 넓음)
            
            session_write_close(); // 세션 락 해제
            $storageId = $input['storage_id'] ?? '';
            $shareName = preg_replace('/[^a-zA-Z0-9_\-]/', '', $input['share_name'] ?? '');
            $readOnly = !empty($input['read_only']);
            $guestAccess = !empty($input['guest_access']);
            
            if (!$storageId || !$shareName) {
                $result = ['success' => false, 'error' => 'Storage ID and share name required'];
                break;
            }
            
            $storages = $db->load('storages');
            $storageData = null;
            foreach ($storages as $s) {
                if (($s['id'] ?? 0) == $storageId) { $storageData = $s; break; }
            }
            if (!$storageData || empty($storageData['path']) || !is_dir($storageData['path'])) {
                $result = ['success' => false, 'error' => 'Invalid storage or path not found'];
                break;
            }
            
            $storagePath = realpath($storageData['path']);
            // SMB 설정 파일 인젝션 방지 (줄바꿈/제어문자 제거)
            $storagePath = preg_replace('/[\r\n\x00-\x1f]/', '', $storagePath);
            $os = PHP_OS_FAMILY;
            $output = [];
            $success = false;
            
            if ($os === 'Windows') {
                $perm = '';
                if ($guestAccess) $perm = $readOnly ? ' /GRANT:Everyone,READ' : ' /GRANT:Everyone,FULL';
                $cmd = 'net share ' . escapeshellarg($shareName . '=' . $storagePath) . $perm;
                
                // 설정 저장 (exec 성공 여부와 무관)
                $shareSettingsFile = DATA_PATH . '/network_share_settings.json';
                $shareSettings = @file_exists($shareSettingsFile) ? (@json_decode(@file_get_contents($shareSettingsFile), true) ?: []) : [];
                $shareSettings[$shareName] = [
                    'storage_id' => $storageId,
                    'share_name' => $shareName,
                    'path' => $storagePath,
                    'read_only' => $readOnly,
                    'guest_access' => $guestAccess,
                    'created' => date('Y-m-d H:i:s'),
                ];
                @file_put_contents($shareSettingsFile, json_encode($shareSettings, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
                
                // exec 시도
                $output = [];
                $rc = -1;
                set_error_handler(function() {}, E_ALL);
                @exec('chcp 65001 >nul 2>&1 & ' . $cmd . ' 2>&1', $output, $rc);
                restore_error_handler();
                
                if ($rc === 0) {
                    $result = ['success' => true];
                } else {
                    $result = ['success' => true, 'warning' => true, 'cmd' => $cmd,
                        'message' => __('smb_share_auto_create_failed', '자동 생성 실패. 관리자 CMD에서 실행하세요: ') . $cmd];   // ★ (2026-11-02 10:31, 42차 점검) 번역 없이 한국어 고정이었음(E3 목록 B)
                }
                break;
                
            } elseif ($os === 'Linux') {
                $confPath = '/etc/samba/smb.conf';
                if (!file_exists($confPath) || !is_writable($confPath)) {
                    $result = ['success' => false, 'error' => 'Cannot write to /etc/samba/smb.conf. Check permissions or install Samba.'];
                    break;
                }
                
                $conf = file_get_contents($confPath);
                if (preg_match('/\[' . preg_quote($shareName, '/') . '\]/i', $conf)) {
                    $result = ['success' => false, 'error' => "Share [{$shareName}] already exists"];
                    break;
                }
                
                $writable = $readOnly ? 'no' : 'yes';
                $guestOk = $guestAccess ? 'yes' : 'no';
                $browseable = 'yes';
                
                // valid users 설정 (게스트가 아닌 경우 FileStation 사용자만 허용)
                $validUsersLine = '';
                if (!$guestAccess) {
                    // 활성 사용자 목록 (smb.conf 안전 문자만 허용)
                    // ★ (2026-11-02 09:08, 41차 점검) status 키가 없는 옛 계정(다른 곳은 모두 'active' 로 봄 — Auth 로그인·WebDAV 37차)을 findAll 조건이 빼 valid users 에서 빠졌음(D1#4) → 없으면 active 로
                    $users = array_filter($db->load('users') ?: [], function ($u) { return is_array($u) && ($u['status'] ?? 'active') === 'active'; });
                    $usernames = [];
                    foreach ($users as $u) {
                        if (preg_match('/^[a-zA-Z0-9_\-]+$/', $u['username'])) {
                            $usernames[] = $u['username'];
                        }
                    }
                    if (!empty($usernames)) {
                        $validUsersLine = "\n   valid users = " . implode(' ', $usernames);
                    }
                }
                
                $newSection = "\n\n# FileStation auto-generated share\n[{$shareName}]\n   path = \"" . $storagePath . "\"\n   browseable = {$browseable}\n   read only = " . ($readOnly ? 'yes' : 'no') . "\n   writable = {$writable}\n   guest ok = {$guestOk}{$validUsersLine}\n   create mask = 0664\n   directory mask = 0775\n   force group = www-data\n";
                
                if (!file_put_contents($confPath, $conf . $newSection)) {
                    $result = ['success' => false, 'error' => 'Failed to write smb.conf'];
                    break;
                }
                
                set_error_handler(function() {}, E_ALL);
                @exec('systemctl restart smbd 2>&1 || service smbd restart 2>&1', $output, $rc);
                restore_error_handler();
                $success = true;
            }
            
            if ($success) {
                $shareSettingsFile = DATA_PATH . '/network_share_settings.json';
                $shareSettings = @file_exists($shareSettingsFile) ? (@json_decode(@file_get_contents($shareSettingsFile), true) ?: []) : [];
                $shareSettings[$shareName] = [
                    'storage_id' => $storageId,
                    'share_name' => $shareName,
                    'path' => $storagePath,
                    'read_only' => $readOnly,
                    'guest_access' => $guestAccess,
                    'created' => date('Y-m-d H:i:s'),
                ];
                @file_put_contents($shareSettingsFile, json_encode($shareSettings, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
            }
            
            $result = ['success' => $success, 'output' => $output];
            break;
            
        case 'network_share_remove':
            $auth->requireRealAdmin();   // ★ (2026-11-01 17:19, 40차 점검) 서버 OS 설정(net share·smb.conf·Samba 계정)을 바꾸는 기능이라 실제 관리자만 — 종전엔 '스토리지' 권한 부관리자가 권한 없는 로컬 스토리지 경로를 OS 공유로 열 수 있었음(37차 '로컬 경로는 관리자만' 결정보다 넓음)
            
            session_write_close(); // 세션 락 해제
            $shareName = preg_replace('/[^a-zA-Z0-9_\-]/', '', $input['share_name'] ?? '');
            if (!$shareName) {
                $result = ['success' => false, 'error' => 'Share name required'];
                break;
            }
            // ★ (2026-11-01 01:51, 36차 전체 점검) Samba 특수 섹션은 지우지 않음 — 표시 주석이 없는 섹션도 이름으로 지우는 대체 때문에 API 로 'global' 을 보내면 [global] 이 통째 지워져 Samba 설정이 깨졌음(화면 목록은 이 셋을 빼고 보여 줌)
            if (in_array(strtolower($shareName), ['global', 'homes', 'printers'], true)) {
                $result = ['success' => false, 'error' => 'Reserved share name'];
                break;
            }
            
            $os = PHP_OS_FAMILY;
            $success = false;
            $output = [];
            
            if ($os === 'Windows') {
                // 설정 제거
                $shareSettingsFile = DATA_PATH . '/network_share_settings.json';
                if (@file_exists($shareSettingsFile)) {
                    $shareSettings = @json_decode(@file_get_contents($shareSettingsFile), true) ?: [];
                    unset($shareSettings[$shareName]);
                    @file_put_contents($shareSettingsFile, json_encode($shareSettings, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
                }
                
                // exec 시도
                $cmd = 'net share ' . escapeshellarg($shareName) . ' /DELETE /Y';
                $output = [];
                $rc = -1;
                set_error_handler(function() {}, E_ALL);
                @exec('chcp 65001 >nul 2>&1 & ' . $cmd . ' 2>&1', $output, $rc);
                restore_error_handler();
                
                if ($rc === 0) {
                    $result = ['success' => true];
                } else {
                    $result = ['success' => true, 'warning' => true,
                        'message' => __('smb_share_auto_delete_failed', '자동 삭제 실패. 관리자 CMD에서 실행하세요: ') . $cmd];   // ★ (2026-11-02 10:31, 42차 점검) 번역 없이 한국어 고정이었음(E3 목록 B)
                }
                break;
                
            } elseif ($os === 'Linux') {
                $confPath = '/etc/samba/smb.conf';
                if (!is_writable($confPath)) {
                    $result = ['success' => false, 'error' => 'Cannot write to /etc/samba/smb.conf'];
                    break;
                }
                
                $conf = file_get_contents($confPath);
                $pattern = '/\n*# FileStation auto-generated share\n\[' . preg_quote($shareName, '/') . '\][^\[]*/i';
                $newConf = preg_replace($pattern, '', $conf);
                if ($newConf === $conf) {
                    $pattern = '/\n*\[' . preg_quote($shareName, '/') . '\][^\[]*/i';
                    $newConf = preg_replace($pattern, '', $conf);
                }
                
                file_put_contents($confPath, $newConf);
                set_error_handler(function() {}, E_ALL);
                @exec('systemctl restart smbd 2>&1 || service smbd restart 2>&1', $output, $rc);
                restore_error_handler();
                $success = true;
            }
            
            if ($success) {
                $shareSettingsFile = DATA_PATH . '/network_share_settings.json';
                if (@file_exists($shareSettingsFile)) {
                    $shareSettings = @json_decode(@file_get_contents($shareSettingsFile), true) ?: [];
                    unset($shareSettings[$shareName]);
                    @file_put_contents($shareSettingsFile, json_encode($shareSettings, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
                }
            }
            
            $result = ['success' => $success, 'output' => $output];
            break;
            
        case 'smb_sync_users':
            $auth->requireRealAdmin();   // ★ (2026-11-01 17:19, 40차 점검) 서버 OS 설정(net share·smb.conf·Samba 계정)을 바꾸는 기능이라 실제 관리자만 — 종전엔 '스토리지' 권한 부관리자가 권한 없는 로컬 스토리지 경로를 OS 공유로 열 수 있었음(37차 '로컬 경로는 관리자만' 결정보다 넓음)
            
            session_write_close(); // 세션 락 해제
            if (PHP_OS_FAMILY !== 'Linux') {
                $result = ['success' => false, 'error' => 'Samba user sync is only supported on Linux'];
                break;
            }
            
            $disabledStr = @ini_get('disable_functions') ?: '';
            $disabledArr = array_map('trim', explode(',', $disabledStr));
            $canExec = function_exists('exec') && !in_array('exec', $disabledArr);
            if (!$canExec) {
                $result = ['success' => false, 'error' => 'exec() is disabled'];
                break;
            }
            
            // smbpasswd 확인
            $smbOut = [];
            set_error_handler(function() {}, E_ALL);
            @exec('which smbpasswd 2>/dev/null', $smbOut, $smbRc);
            restore_error_handler();
            if ($smbRc !== 0) {
                $result = ['success' => false, 'error' => 'smbpasswd not found. Install Samba first.'];
                break;
            }
            
            // 특정 사용자만 동기화 (선택)
            $targetUserId = $input['user_id'] ?? null;
            $targetPassword = $input['password'] ?? null;
            // ★ (2026-11-01 17:19, 40차 점검) 비밀번호 '0' 이 '안 줌'으로 처리돼(기존 계정 건너뜀·새 계정은 아이디1234) 사용자가 준 값이 무시됐고, 배열이면 escapeshellarg 에서 500 → 비지 않은 문자열만 비밀번호로 봄
            $targetPassword = (is_string($targetPassword) && $targetPassword !== '') ? $targetPassword : null;
            
            $users = $db->load('users');
            $synced = [];
            $errors = [];
            $kept = [];   // ★ (2026-10-29 20:04, 23차 점검, 펜닐 결정 '새 사용자만 기본값') 이미 Samba 계정이 있어 비밀번호를 그대로 둔 사용자
            // ★ (2026-10-29 20:04, 23차 점검, 펜닐 결정 '새 사용자만 기본값') 비밀번호를 따로 주지 않으면 이미 Samba 계정이 있는 사용자의 비밀번호는 바꾸지 않음(없는 사용자만 '아이디1234' 로 만듦) —
            //   종전엔 동기화할 때마다 전원 비밀번호를 '아이디1234' 로 덮어써, 사용자가 smbpasswd 로 바꾼 비밀번호가 돌아갔음.
            //   있는지 확인은 pdbedit(smbpasswd 와 같은 Samba 패키지). 없으면 기존 비밀번호 보호를 위해 기본값 설정을 건너뜀
            $pdbOut = [];
            set_error_handler(function() {}, E_ALL);
            @exec('which pdbedit 2>/dev/null', $pdbOut, $pdbRc);
            restore_error_handler();
            $hasPdbedit = ($pdbRc === 0);
            
            foreach ($users as $user) {
                if (($user['status'] ?? 'active') !== 'active') continue;   // ★ (2026-11-02 09:08, 41차 점검) status 없는 옛 계정은 active 로(다른 곳과 같게 — D1#4)
                if ($targetUserId && (int)$user['id'] !== (int)$targetUserId) continue;
                
                $username = $user['username'];
                // 안전한 사용자명만 허용
                // ★ (2026-11-01 17:19, 40차 점검) 맨 앞 '-' 를 허용해 SSO 로 만들어진 '-a' 같은 아이디가 smbpasswd 옵션으로 읽혀 root 의 Samba 계정이 추가·활성화됐음(재현) → 첫 글자 '-' 금지,
                //   아래 id·useradd·smbpasswd 명령에 '--' 구분자 추가(pdbedit -u 는 값 인자라 '--' 를 넣지 않음 — 첫 글자 검사로 막힘)
                if (!is_string($username) || !preg_match('/^[a-zA-Z0-9_][a-zA-Z0-9_\-]*$/', $username)) {
                    $errors[] = "{$username}: invalid characters in username";
                    continue;
                }
                
                // 리눅스 사용자 존재 확인 → 없으면 생성
                $idOut = [];
                set_error_handler(function() {}, E_ALL);
                @exec('id -- ' . escapeshellarg($username) . ' 2>/dev/null', $idOut, $idRc);
                restore_error_handler();
                
                if ($idRc !== 0) {
                    // 시스템 사용자 생성 (홈 디렉토리 없이, 로그인 불가)
                    $addOut = [];
                    set_error_handler(function() {}, E_ALL);
                    @exec('useradd -M -s /usr/sbin/nologin -g www-data -- ' . escapeshellarg($username) . ' 2>&1', $addOut, $addRc);
                    restore_error_handler();
                    if ($addRc !== 0) {
                        $errors[] = "{$username}: failed to create system user";
                        continue;
                    }
                }
                
                // ★ (2026-10-29 20:04, 23차 점검, 펜닐 결정 '새 사용자만 기본값') 비밀번호를 주지 않았으면 이미 있는 Samba 계정은 건너뜀(활성화만)
                if ($targetPassword === null) {   // ★ (2026-11-01 17:19, 40차 점검) '0' 도 비밀번호로(위 정리 참고)
                    if (!$hasPdbedit) {
                        $errors[] = "{$username}: pdbedit not found — skipped to keep existing password";
                        continue;
                    }
                    $pdbChk = [];
                    set_error_handler(function() {}, E_ALL);
                    @exec('pdbedit -L -u ' . escapeshellarg($username) . ' 2>/dev/null', $pdbChk, $pdbChkRc);
                    restore_error_handler();
                    if ($pdbChkRc === 0) {
                        set_error_handler(function() {}, E_ALL);
                        @exec('smbpasswd -e -- ' . escapeshellarg($username) . ' 2>&1', $enOut0, $enRc0);
                        restore_error_handler();
                        $kept[] = $username;
                        continue;
                    }
                }
                
                // ★ (2026-11-17 09:59, 308차 펜닐 결정 'FileStation 이 만든 계정만') 이미 있던 리눅스 계정(root·daemon·서버 관리자 계정 등)에는 새 Samba 계정을 만들지 않음 —
                //   종전엔 FileStation 아이디가 그 이름과 같으면(가입으로 'root' 등) 그 계정에 Samba 비밀번호(기본 '아이디1234')가 붙어, 가입한 사람이 공유 폴더에 root 등으로 접속할 수 있었음(재현: pdbedit 'root:0:root').
                //   FileStation 이 만든 계정 = 위 useradd 로 지금 만든 것, 또는 번호 1000 이상·기본 그룹 www-data(같은 useradd 로 전에 만든 것). 이미 Samba 계정이 있으면(위 '그대로 둠'·비밀번호 지정 갱신) 종전과 같음
                if ($idRc === 0) {
                    $ownOk = false;
                    $uidO = []; $gidO = []; $wgO = [];
                    set_error_handler(function() {}, E_ALL);
                    @exec('id -u -- ' . escapeshellarg($username) . ' 2>/dev/null', $uidO, $uidRc);
                    @exec('id -g -- ' . escapeshellarg($username) . ' 2>/dev/null', $gidO, $gidRc);
                    @exec('id -g www-data 2>/dev/null', $wgO, $wgRc);
                    restore_error_handler();
                    if ($uidRc === 0 && $gidRc === 0 && $wgRc === 0 && isset($uidO[0], $gidO[0], $wgO[0])
                        && ctype_digit(trim($uidO[0])) && (int)trim($uidO[0]) >= 1000 && trim($gidO[0]) === trim($wgO[0])) $ownOk = true;
                    if (!$ownOk) {
                        $smbHas = false;
                        if ($targetPassword !== null && $hasPdbedit) {   // 비밀번호 지정이면 이미 있는 Samba 계정의 비밀번호 바꾸기는 종전대로(비밀번호 없이는 위에서 이미 '그대로 둠'으로 넘어감)
                            $pdbChk2 = [];
                            set_error_handler(function() {}, E_ALL);
                            @exec('pdbedit -L -u ' . escapeshellarg($username) . ' 2>/dev/null', $pdbChk2, $pdbChk2Rc);
                            restore_error_handler();
                            $smbHas = ($pdbChk2Rc === 0);
                        }
                        if (!$smbHas) {
                            $errors[] = "{$username}: existing Linux account not created by FileStation (system or other user) — skipped";
                            continue;
                        }
                    }
                }

                // Samba 비밀번호 설정
                $pass = $targetPassword ?? ($user['username'] . '1234'); // 기본 비밀번호(새 Samba 계정만)
                $smbCmd = 'printf ' . escapeshellarg('%s\n%s\n') . ' ' . escapeshellarg($pass) . ' ' . escapeshellarg($pass) . ' | smbpasswd -a -s -- ' . escapeshellarg($username) . ' 2>&1';
                $smbSetOut = [];
                set_error_handler(function() {}, E_ALL);
                @exec($smbCmd, $smbSetOut, $smbSetRc);
                restore_error_handler();
                
                if ($smbSetRc === 0) {
                    // Samba 사용자 활성화
                    set_error_handler(function() {}, E_ALL);
                    @exec('smbpasswd -e -- ' . escapeshellarg($username) . ' 2>&1', $enableOut, $enableRc);
                    restore_error_handler();
                    $synced[] = $username;
                } else {
                    $errors[] = "{$username}: smbpasswd failed";
                }
            }
            
            $result = [
                'success' => true,
                'synced' => $synced,
                'kept' => $kept,
                'errors' => $errors,
                'message' => count($synced) . ' users synced' . (count($kept) ? ', ' . count($kept) . ' kept' : '') . (count($errors) ? ', ' . count($errors) . ' errors' : '')
            ];
            break;
            
        // ===== 작업 큐 시스템 =====
        
        case 'job_create':
            $auth->requireLogin();
            $user = $auth->getUser();
            $jobType = $input['type'] ?? '';
            $jobParams = $input['params'] ?? [];
            
            if (!in_array($jobType, ['copy', 'move', 'delete', 'restore', 'trash_empty', 'trash_delete'])) {
                $result = ['success' => false, 'error' => 'Invalid job type'];
                break;
            }
            // ★ (2026-11-01 11:39, 39차 점검) 앞단 '..' 검사는 최상위 키만 봐서 params 안의 경로(dest_path·items[].path·paths 등)는 검사되지 않았고,
            //   Linux 에서 'zz/../../<남의 홈>/x' 처럼 없는 폴더를 끼우면 isPathSafe 를 지나 스토리지 밖에 복사됐음(M5 재현)
            //   → 키 이름에 'path' 가 든 값(배열 안 포함)에 '..' 조각(Windows 는 점·공백만인 조각)이 있으면 거부(fsSyncCleanPath 와 같은 기준)
            $jqBadPath = false;
            $jqWalk = function ($v, $k) use (&$jqWalk, &$jqBadPath) {
                if ($jqBadPath) return;
                if (is_array($v)) { foreach ($v as $kk => $vv) $jqWalk($vv, is_string($kk) ? $kk : $k); return; }
                if (is_string($k) && stripos($k, 'path') !== false && is_scalar($v) && fsSyncCleanPath($v) === null) $jqBadPath = true;
            };
            $jqWalk($jobParams, '');
            if ($jqBadPath) {
                $result = ['success' => false, 'error' => __('api_err_invalid_path', '잘못된 경로입니다.')];
                break;
            }
            
            // ★ (2026-10-28 17:23, 소스 점검 2단계) 작업 큐 권한 검사 — 종전엔 하나도 없어, 폴더별 권한으로 막힌 폴더나
            //   다른 사용자의 휴지통 항목을 작업 큐(copy/move/delete/restore/trash_*)로 우회할 수 있었음. 직접 액션(move·delete·trash_delete)과 같은 기준으로 검사.
            {
                $jqItems = is_array($jobParams['items'] ?? null) ? $jobParams['items'] : [];
                $jqSrc = (int)($jobParams['source_storage_id'] ?? 0);
                $jqDstId = (int)($jobParams['dest_storage_id'] ?? $jqSrc);
                $jqDstPath = $jobParams['dest_path'] ?? '';
                $jqDeny = null;
                $jqDir = function($path) { $d = dirname(str_replace('\\', '/', (string)$path)); return $d === '.' ? '' : $d; };
                // 폴더 권한 + 스토리지 권한 둘 다(checkFolderPermission 은 폴더 규칙이 없으면 통과하므로, 스토리지 접근 권한은 checkPermission 으로 — FileManager 가 실행 때 보는 것과 같은 기준)
                if (in_array($jobType, ['copy', 'move'])) {
                    if (!$storage->checkPermission($jqDstId, 'can_write') || !$storage->checkFolderPermission($jqDstId, $jqDstPath, 'can_write')) $jqDeny = __('no_permission_dot', '권한이 없습니다.');
                    if (!$jqDeny && !$storage->checkPermission($jqSrc, 'can_read')) $jqDeny = __('no_permission_dot', '권한이 없습니다.');
                    // ★ (2026-10-28 19:55, 6차 점검) 이동은 직접 이동(api move → FileManager::moveInner)과 같은 기준 — 원본 스토리지 can_write·폴더 can_read.
                    //   종전(2단계 추가분)엔 can_delete 를 요구해 쓰기만 있는 사용자의 큐 이동이 직접 이동과 달리 막혔음(회귀)
                    if (!$jqDeny && $jobType === 'move' && !$storage->checkPermission($jqSrc, 'can_write')) $jqDeny = __('no_permission_dot', '권한이 없습니다.');
                    $jqMvNorm = function ($p) { $p = trim(str_replace('\\', '/', (string)$p), '/'); if ($p === '.') $p = ''; return DIRECTORY_SEPARATOR === '\\' ? mb_strtolower($p) : $p; };
                    foreach ($jqItems as $it) {
                        if ($jqDeny) break;
                        $ip = $it['path'] ?? '';
                        // ★ (2026-11-10 13:22, 63차 1) 다른 폴더·다른 스토리지로 옮기는 항목은 원본 스토리지 삭제 권한도(FileManager::moveInner 와 같은 기준) — 같은 폴더 안은 종전대로 쓰기만
                        if ($jobType === 'move' && !($jqSrc === $jqDstId && $jqMvNorm($jqDir(trim(str_replace('\\', '/', (string)$ip), '/'))) === $jqMvNorm($jqDstPath)) && !$storage->checkPermission($jqSrc, 'can_delete')) $jqDeny = __('api_err_no_delete_perm', '삭제 권한이 없습니다.');
                        if (!$storage->checkFolderPermission($jqSrc, fsDirOr($jqDir($ip), $ip), 'can_read')) $jqDeny = __('no_permission_dot', '권한이 없습니다.');   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                        // ★ (2026-10-28 20:42, 7차 점검, 펜닐 결정) 이동은 원본 폴더 쓰기도 필요(직접 이동과 같은 기준)
                        if (!$jqDeny && $jobType === 'move' && !$storage->checkFolderPermission($jqSrc, fsDirOr($jqDir($ip), $ip), 'can_write')) $jqDeny = __('no_permission_dot', '권한이 없습니다.');   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                        if (!$jqDeny && $jobType === 'move' && !$storage->checkFolderPermission($jqSrc, fsDirOr($jqDir($ip), $ip), 'can_delete')) $jqDeny = __('no_permission_dot', '권한이 없습니다.');   // ★ (2026-10-28 21:19, 8차 점검, 펜닐 결정)   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                        // ★ (2026-10-28 21:53, 9차 점검, 펜닐 결정 '작업 자체를 거부') 항목 자신 + 그 아래 보호 폴더까지(checkFolderTreePermission) — 종전엔 상위 폴더만 봐서 보호 폴더 자체·그걸 품은 폴더를 지우고·옮기고·복사·공유할 수 있었음(재현)
                        if (!$jqDeny && (!$storage->checkFolderTreePermission($jqSrc, $ip, 'can_read') || ($jobType === 'move' && (!$storage->checkFolderTreePermission($jqSrc, $ip, 'can_write') || !$storage->checkFolderTreePermission($jqSrc, $ip, 'can_delete'))))) $jqDeny = __('no_permission_dot', '권한이 없습니다.');
                    }
                } elseif ($jobType === 'delete') {
                    foreach ($jqItems as $it) {
                        if ($jqDeny) break;
                        $ip = $it['path'] ?? '';
                        $isid = (int)($it['storage_id'] ?? $jobParams['storage_id'] ?? $jqSrc);
                        if (!$storage->checkPermission($isid, 'can_delete') || !$storage->checkFolderPermission($isid, fsDirOr($jqDir($ip), $ip), 'can_delete')   // ★ (2026-11-01 17:26, 40차 점검) 부모 경로 판정을 fsDirOr 로('0' 폴더 — 아래 함수 주석)
                            || !$storage->checkFolderTreePermission($isid, $ip, 'can_delete')) $jqDeny = __('no_permission_dot', '권한이 없습니다.');   // ★ (2026-10-28 21:53, 9차 점검) 안의 보호 폴더까지
                    }
                } elseif (in_array($jobType, ['restore', 'trash_delete', 'trash_empty'])) {
                    // 휴지통 항목은 본인 것 또는 관리자만(직접 trash_delete 와 같은 기준) — trash_empty 는 전체이므로 본인 것만 처리됨을 보장하기 위해 관리자 아니면 각 항목 소유자 검사
                    $jqAdmin = ($user['role'] ?? '') === 'admin';
                    if (!$jqAdmin) {
                        $jqTrash = $db->load('trash') ?: [];
                        $jqOwn = [];
                        foreach ($jqTrash as $t) { if (($t['deleted_by'] ?? 0) === ($user['id'] ?? -1)) $jqOwn[(string)($t['id'] ?? '')] = true; }
                        // restore·trash_delete·trash_empty 모두 items[].id 단위로 처리되므로, 각 항목이 본인 휴지통 것인지 확인
                        foreach ($jqItems as $it) {
                            if (empty($jqOwn[(string)($it['id'] ?? '')])) { $jqDeny = __('no_permission_dot', '권한이 없습니다.'); break; }
                        }
                    }
                }
                if ($jqDeny) { $result = ['success' => false, 'error' => $jqDeny]; break; }
            }
            
            $jobManager = JobManager::getInstance();
            $jobManager->setAuth($auth);
            $createResult = $jobManager->create($jobType, $jobParams, $user['id']);
            
            if (!$createResult['success']) {
                $result = $createResult;
                break;
            }
            
            $jobId = $createResult['job_id'];
            
            // 작업 등록만 하고 즉시 반환 (실행은 클라이언트가 job_execute 호출)
            session_write_close();
            
            $result = ['success' => true, 'job_id' => $createResult['job_id']];
            break;
        
        case 'job_execute':
            $auth->requireLogin();
            $user = $auth->getUser();
            $jobId = $input['id'] ?? '';
            
            $jobManager = JobManager::getInstance();
            $jobManager->setAuth($auth);
            
            // 본인 작업만 실행 가능
            $jobCheck = $jobManager->getStatus($jobId);
            if (!$jobCheck || ($jobCheck['user_id'] ?? 0) !== $user['id']) {
                $result = ['success' => false, 'error' => 'Job not found'];
                break;
            }
            
            // 동시 실행 중인 작업 수 체크 (running 상태)
            $activeJobs = $jobManager->listJobs($user['id'], true);
            $runningCount = 0;
            foreach ($activeJobs as $aj) {
                if (($aj['status'] ?? '') === 'running' && $aj['id'] !== $jobId) {
                    $runningCount++;
                }
            }
            $appSettings = $db->load('settings');
            // ★ (2026-10-29 20:07, 23차 점검, 펜닐 결정 '설정값을 실행 제한에도 적용') 동시 실행 수 = 설정 화면의 '사용자당 최대 동시 작업 수'(0 = 제한 없음) —
            //   종전엔 화면에 없는 max_running_jobs(기본 2)로 따로 묶여, 설정을 5로 해도 2개만 돌고 나머지는 대기했음
            $maxRunning = (int)($appSettings['max_concurrent_jobs'] ?? 5);
            if ($maxRunning > 0 && $runningCount >= $maxRunning) {
                // 대기 상태로 두고 응답 (폴링에서 재시도)
                $jobManager->touchQueued($jobId);   // ★ (2026-11-12 17:34, 101차 TRA-2) 마지막으로 실행을 물은 시각 남김(cleanup 이 버려진 작업으로 지우지 않게)
                $result = ['success' => true, 'queued' => true];
                break;
            }
            
            // 응답을 먼저 보내고 작업 실행
            session_write_close();
            ignore_user_abort(true);
            @set_time_limit(0);
            
            $response = json_encode(['success' => true], JSON_UNESCAPED_UNICODE);
            if (function_exists('fastcgi_finish_request')) {
                echo $response;
                fastcgi_finish_request();
            } else {
                while (ob_get_level() > 0) ob_end_clean();
                header('Content-Type: application/json; charset=utf-8');
                header('Connection: close');
                header('Content-Length: ' . strlen($response));
                echo $response;
                flush();
            }
            
            $jobManager->execute($jobId);
