            header('Content-Length: ' . $size);
            header("Content-Disposition: attachment; filename*=UTF-8''" . rawurlencode($filename));
            header('Cache-Control: no-cache');
            readfile($fullPath);
            exit;
        
        case 'vault_convert_delete_original':
