            }
            // ★ (2026-11-02 09:03, 41차 점검) uuid 형식만 보고 .enc 가 실제로 있는지·크기는 안 봐서, 보관함 폴더에 한도 확인 없이 아무 크기 파일이나 만들 수 있었음(D5#3)
            //   → 원본 암호 파일(.enc 또는 .chunks)이 있어야 받고, 받은 크기가 그 암호문 크기 + 1MB 를 넘으면 거부(AES-GCM 평문은 암호문보다 작음 — 압축 없음)
            $vdsSrcSize = fsVaultEncSourceSize($vaultDir, $uuid);
            if ($vdsSrcSize === null) {
                $result = ['success' => false, 'error' => __('vault_err_source_missing', '원본 암호화 파일이 없습니다.')];
                break;
            }
            if ((int)($_FILES['decrypted_file']['size'] ?? 0) > $vdsSrcSize + 1048576) {
                $result = ['success' => false, 'error' => __('vault_err_size_exceeds', '복호화한 파일이 원본 암호화 파일보다 큽니다.')];
                break;
            }
            
            // ★ (2026-11-17 13:43, 326차) 일반 올리기와 같은 검사(막히면 원본 .enc 그대로 둠)
            if (($vgErr = fsVaultSaveGuard((string)$originalName, (string)$_FILES['decrypted_file']['tmp_name'])) !== null) {
                $result = ['success' => false, 'error' => $vgErr];
                break;
            }
            $destPath = $vaultDir . DIRECTORY_SEPARATOR . $originalName;
            // 동일 이름 존재 시 번호 추가
            if (file_exists($destPath)) {
                $info = pathinfo($originalName);
                $base = $info['filename'];
                $ext = isset($info['extension']) ? '.' . $info['extension'] : '';
                $i = 1;
                while (file_exists($vaultDir . DIRECTORY_SEPARATOR . $base . " ($i)" . $ext)) $i++;
                $destPath = $vaultDir . DIRECTORY_SEPARATOR . $base . " ($i)" . $ext;
            }
            
            if (!move_uploaded_file($_FILES['decrypted_file']['tmp_name'], $destPath)) {
                $result = ['success' => false, 'error' => __('vault_err_upload_failed')];
                break;
            }
            
            // .enc 및 .meta.enc 삭제
            $encFile = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.enc';
            $metaFile = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.meta.enc';
            $freedSize = 0;
            if (file_exists($encFile)) { $vdsSz = (int)filesize($encFile); if (@unlink($encFile)) $freedSize += $vdsSz; }   // ★ (2026-11-02 09:03, 41차 점검) 실제로 지운 것만 셈
            if (file_exists($metaFile)) { $vdsSz = (int)filesize($metaFile); if (@unlink($metaFile)) $freedSize += $vdsSz; }
            for ($vdsLi = 0; file_exists($vaultDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vdsLi); $vdsLi++) { $vdsLp = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vdsLi; $vdsSz = (int)filesize($vdsLp); if (@unlink($vdsLp)) $freedSize += $vdsSz; }   // ★ (2026-11-09 12:01, 57차 Z09-1) 옛 청크 형식 조각도 지움(위 fsVaultEncSourceSize 가 이제 옛 형식을 받으므로 — 안 지우면 메타 없는 조각이 남음)
            // ★ (2026-11-02 09:03, 41차 점검) 새 파일 크기를 더하지도 지운 .enc·.meta.enc 를 빼지도 않았음(40차 C8 은 '화면이 안 쓰는 판'이라 뺐던 것) → 차이를 반영
            $storage->updateUsedSize($storageId, (int)@filesize($destPath) - $freedSize);
            
            $result = ['success' => true, 'saved_as' => basename($destPath)];
            break;
        
        case 'vault_decrypt_save_chunk':
            // 청크 방식 복호화 파일 저장 (대용량 파일 413 에러 방지)
            $auth->requireLogin();
            session_write_close();
            $storageId = (int)($_POST['storage_id'] ?? 0);
            $path = $_POST['path'] ?? '';
            $uuid = $_POST['uuid'] ?? '';
            $originalName = $_POST['original_name'] ?? '';
            $chunkIndex = (int)($_POST['chunk_index'] ?? 0);
            $totalChunks = (int)($_POST['total_chunks'] ?? 1);
            
            // 스토리지 쓰기 권한 체크
            // ★ (2026-10-29 02:36, 16차) 폴더 규칙도 확인(같은 일을 하는 vault_decrypt_save 와 같음) — 종전엔 스토리지 쓰기만 봤음
            if (!$storage->checkPermission($storageId, 'can_write') || !$storage->checkFolderPermission($storageId, $path, 'can_write')) {
                $result = ['success' => false, 'error' => __('no_write_permission', '쓰기 권한이 없습니다.')];
                break;
            }
            // ★ (2026-10-29 22:39, 24차 점검) 원본 암호 파일(.enc·.meta.enc·조각)을 휴지통 없이 지우므로 삭제 권한도(vault_delete 16차·vault_convert_delete_original 11차와 같은 기준) —
            //   종전엔 쓰기 권한만 있는 사용자가 아무 내용으로 보내 남의 보관함 파일을 복원할 수 없게 지울 수 있었음(2회차 재검토)
            if (!$storage->checkPermission($storageId, 'can_delete') || !$storage->checkFolderPermission($storageId, $path, 'can_delete')) {
                $result = ['success' => false, 'error' => __('no_permission_dot', '권한이 없습니다.')];
                break;
            }
            
            if (empty($uuid) || (!is_scalar($originalName) || (string)$originalName === '')) {   // ★ (2026-11-01 11:37, 39차 점검) empty() 가 이름·경로 '0' 을 빈 값으로 봐 '0' 폴더·파일이 거부됐음 → 빈 글자일 때만
                $result = ['success' => false, 'error' => __('vault_err_missing_params')];
                break;
            }
            if (!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/', $uuid)) {
                $result = ['success' => false, 'error' => 'Invalid UUID'];
                break;
            }
            if (preg_match('/[\\/\\\\:*?"<>|]/', $originalName) || trim($originalName, '. ') === '') {   // ★ (2026-11-01 07:24, 37차 기능 점검) 구분자는 이미 막으므로 이름 전체가 점뿐일 때만 거부 — 종전엔 '회의록...docx' 같은 정상 이름의 해제·미리보기가 막혔음
                $result = ['success' => false, 'error' => __('vault_err_invalid_name')];
                break;
            }
            if ($__execReason = fsServerExecReason($originalName)) {   // ★ (2026-10-29 02:36, 16차) 실행될 수 있는 이름 거부(vault_decrypt_save 와 같음)
                $result = ['success' => false, 'error' => $__execReason];
                break;
            }
            
            $_vp = resolveVaultPath($storage, $storageId, $path);
            if (!$_vp) {
                $result = ['success' => false, 'error' => __('api_err_storage_not_found')];
                break;
            }
            $basePath = $_vp['basePath'];
            $vaultDir = $_vp['vaultDir'];
            
            if (!file_exists($vaultDir . DIRECTORY_SEPARATOR . '.vault.json')) {
                $result = ['success' => false, 'error' => __('vault_err_not_vault')];
                break;
            }
            
            if (empty($_FILES['chunk']) || $_FILES['chunk']['error'] !== UPLOAD_ERR_OK) {
                $result = ['success' => false, 'error' => fsVaultNoFileError('chunk')];   // ★ (2026-11-14 23:23, 146차) 한도 초과면 이유를
                break;
            }
            
            // 임시 파일에 청크 추가
            $tmpFile = $vaultDir . DIRECTORY_SEPARATOR . '.decrypt_tmp_' . $uuid;
            // ★ (2026-11-11 17:01, 76차 VLT-1) 화면이 보낸 해제 한 번의 표식(dec_job, hex 8~32자)이 있으면 임시 파일 이름에 붙임 — 종전엔 uuid 만이라 두 탭이 같은 파일을 조금 어긋나게 풀면 늦은 탭 첫 조각이 앞 탭 임시 파일을 자르고 앞 탭 마지막 조각이 이어 붙어, 섞인 파일이 원래 이름으로 저장되고 원본 .enc 가 지워졌음(재현). 표식이 없으면(옛 화면) 종전 이름 그대로. 하루 지난 정리·목록 숨김은 같은 접두어라 그대로
            $vdJob = $_POST['dec_job'] ?? '';
            if (is_string($vdJob) && preg_match('/^[0-9a-f]{8,32}$/', $vdJob)) $tmpFile .= '_' . $vdJob;
            // ★ (2026-11-02 09:03, 41차 점검) 화면이 쓰는 조각판도 .enc 존재·누적 크기를 안 봐서, 첫 조각만 보내고 뒤 조각을 끝없이 이어 붙여 한도 확인 없이 임의 크기 파일을 만들 수 있었음(D5#3)
            //   → 첫 조각에서 원본 암호 파일(.enc 또는 .chunks) 크기를 재어 옆 파일(.decrypt_tmp_<uuid>.lim — 아래 하루 지난 정리 대상과 같은 접두어)에 적고,
            //   조각마다 '지금까지 받은 크기 + 이번 조각' 이 그 크기 + 1MB 를 넘으면 거부(평문은 암호문보다 작음). 원본이 없으면 처음부터 거부
            $vdLimFile = $tmpFile . '.lim';
            $vdSrcSize = null;
            if ($chunkIndex !== 0 && is_file($vdLimFile)) {
                $vdLimRaw = @file_get_contents($vdLimFile);
                if (is_string($vdLimRaw) && ctype_digit(trim($vdLimRaw))) $vdSrcSize = (int)trim($vdLimRaw);
            }
            if ($vdSrcSize === null) $vdSrcSize = fsVaultEncSourceSize($vaultDir, $uuid);
            if ($vdSrcSize === null) {
                $result = ['success' => false, 'error' => __('vault_err_source_missing', '원본 암호화 파일이 없습니다.')];
                break;
            }
            $vdHave = ($chunkIndex === 0 || !is_file($tmpFile)) ? 0 : (int)@filesize($tmpFile);
            if ($vdHave + (int)($_FILES['chunk']['size'] ?? 0) > $vdSrcSize + 1048576) {
                @unlink($tmpFile); @unlink($vdLimFile);
                $result = ['success' => false, 'error' => __('vault_err_size_exceeds', '복호화한 파일이 원본 암호화 파일보다 큽니다.')];
                break;
            }
            // ★ (2026-11-17 13:43, 326차) 첫 조각에서 이름만 먼저 검사(막을 형식이면 끝까지 받지 않음) — 크기·내용·백신은 마지막 조각에서
            if ($chunkIndex === 0 && ($vgErr = fsVaultSaveGuard((string)$originalName)) !== null) {
                $result = ['success' => false, 'error' => $vgErr];
                break;
            }
            if ($chunkIndex === 0) @file_put_contents($vdLimFile, (string)$vdSrcSize, LOCK_EX);
            // ★ (2026-11-01 11:38, 39차 점검) 해제 중 끊기면 '.decrypt_tmp_*'(평문 조각)가 지우는 곳 없이 남았음 → 새 해제(첫 조각) 때 이 보관함의
            //   하루 지난 것을 지움. 또 첫 조각이 아닌데 임시 파일이 없으면(앞 조각 유실) 'ab' 로 새로 만들어 뒷부분만 저장하고 원본을 지울 수 있어 실패로 답함
            if ($chunkIndex === 0) {
                foreach ((glob($vaultDir . DIRECTORY_SEPARATOR . '.decrypt_tmp_*') ?: []) as $__dtOld) {
                    if (is_file($__dtOld) && time() - (int)@filemtime($__dtOld) > 86400) @unlink($__dtOld);
                }
            } elseif (!is_file($tmpFile)) {
                $result = ['success' => false, 'error' => __('local_write_failed', '로컬 파일 저장 실패')];
                break;
            }
            $mode = ($chunkIndex === 0) ? 'wb' : 'ab';
            $fp = fopen($tmpFile, $mode);
            if (!$fp) {
                $result = ['success' => false, 'error' => 'Failed to open temp file'];
                break;
            }
            $chunkData = file_get_contents($_FILES['chunk']['tmp_name']);
            // ★ (2026-10-29 09:14, 20차) 쓰기 결과 확인 — 종전엔 확인하지 않아 디스크가 차서 잘려도 마지막에 원본(.enc)을 지우고 성공으로 답했음
            $vdWritten = ($chunkData === false) ? false : fwrite($fp, $chunkData);
            fclose($fp);
            if ($chunkData === false || $vdWritten !== strlen($chunkData)) {
                @unlink($tmpFile); @unlink($vdLimFile);   // ★ (2026-11-02 09:48, 41차 재검토) 크기 기록(.lim)도 같이 지움(검토 발견 — 남아도 하루 뒤 정리되지만 다음 해제 첫 조각 전까지 남았음)
                $result = ['success' => false, 'error' => __('local_write_failed', '로컬 파일 저장 실패')];
                break;
            }
            
            // 마지막 청크: 임시 파일을 최종 파일명으로 이동 + 원본 .enc 삭제
            if ($chunkIndex >= $totalChunks - 1) {
                // ★ (2026-11-17 13:43, 326차) 다 모은 파일에 일반 올리기와 같은 검사(막히면 임시 파일만 지우고 원본 .enc 그대로 둠)
                if (($vgErr = fsVaultSaveGuard((string)$originalName, $tmpFile)) !== null) {
                    @unlink($tmpFile); @unlink($vdLimFile);
                    $result = ['success' => false, 'error' => $vgErr];
                    break;
                }
                $destPath = $vaultDir . DIRECTORY_SEPARATOR . $originalName;
                if (file_exists($destPath)) {
                    $info = pathinfo($originalName);
                    $base = $info['filename'];
                    $ext = isset($info['extension']) ? '.' . $info['extension'] : '';
                    $i = 1;
                    while (file_exists($vaultDir . DIRECTORY_SEPARATOR . $base . " ($i)" . $ext)) $i++;
                    $destPath = $vaultDir . DIRECTORY_SEPARATOR . $base . " ($i)" . $ext;
                }
                // ★ (2026-10-29 09:14, 20차) 이름 바꾸기에 실패하면 원본(.enc)을 지우지 않고 실패로(종전엔 결과를 안 보고 원본을 지웠음)
                @unlink($vdLimFile);
                if (!@rename($tmpFile, $destPath)) {
                    @unlink($tmpFile);
                    $result = ['success' => false, 'error' => __('local_write_failed', '로컬 파일 저장 실패')];
                    break;
                }
                
                // .enc 및 .meta.enc + .chunks 삭제
                $encFile = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.enc';
                $metaFile = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.meta.enc';
                $chunksDir = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.chunks';
                // ★ (2026-11-02 09:03, 41차 점검) 사용량을 전혀 고치지 않았음(지운 암호 파일을 빼지도, 새 파일을 더하지도 않음) → 실제로 지운 크기와 새 파일 크기의 차이를 반영
                $vdFreed = 0;
                if (file_exists($encFile)) { $vdSz = (int)filesize($encFile); if (@unlink($encFile)) $vdFreed += $vdSz; }
                if (file_exists($metaFile)) { $vdSz = (int)filesize($metaFile); if (@unlink($metaFile)) $vdFreed += $vdSz; }
                if (is_dir($chunksDir)) {
                    $chunkFiles = glob($chunksDir . DIRECTORY_SEPARATOR . '*') ?: [];
                    foreach ($chunkFiles as $cf) { $vdSz = is_file($cf) ? (int)filesize($cf) : 0; if (@unlink($cf)) $vdFreed += $vdSz; }
                    @rmdir($chunksDir);
                }
                for ($vdLi = 0; file_exists($vaultDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vdLi); $vdLi++) { $vdLp = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vdLi; $vdSz = (int)filesize($vdLp); if (@unlink($vdLp)) $vdFreed += $vdSz; }   // ★ (2026-11-09 12:01, 57차 Z09-1) 옛 청크 형식 조각도 지움(vault_delete 와 같은 반복 — 안 지우면 메타 없는 조각이 남음)
                $storage->updateUsedSize($storageId, (int)@filesize($destPath) - $vdFreed);
                
                $result = ['success' => true, 'saved_as' => basename($destPath), 'completed' => true];
            } else {
                $result = ['success' => true, 'chunk_index' => $chunkIndex, 'completed' => false];
            }
            break;
        
        case 'vault_remove':
            // vault 폴더의 .vault.json 삭제 → 일반 폴더로 전환
            // (파일 복호화는 클라이언트가 vault_decrypt_save로 개별 처리한 후 호출)
            $auth->requireLogin();
            session_write_close(); // 세션 락 해제
            $storageId = (int)($input['storage_id'] ?? 0);
            $path = $input['path'] ?? '';
            // 스토리지 쓰기 권한 체크
            // ★ (2026-10-28 19:55, 6차 점검) 스토리지 권한도 확인 — 종전엔 폴더 권한(규칙이 없으면 통과)만 봐서 남의 홈 스토리지에 쓰거나 내려받을 수 있었음(재현)
            if (!$storage->checkPermission($storageId, 'can_write') || !$storage->checkFolderPermission($storageId, $path, 'can_write')) {
                $result = ['success' => false, 'error' => __('no_write_permission', '쓰기 권한이 없습니다.')];
                break;
            }
            $storageId = (int)($input['storage_id'] ?? 0);
            $path = $input['path'] ?? '';
            
            $_vp = resolveVaultPath($storage, $storageId, $path);
            if (!$_vp) {
                $result = ['success' => false, 'error' => __('api_err_storage_not_found')];
                break;
            }
            $basePath = $_vp['basePath'];
            $vaultDir = $_vp['vaultDir'];
            $vaultJsonPath = $vaultDir . DIRECTORY_SEPARATOR . '.vault.json';
            
            if (!file_exists($vaultJsonPath)) {
                $result = ['success' => false, 'error' => __('vault_err_not_vault')];
                break;
            }
            
            // 아직 .enc 파일이 남아있는지 확인
            $remainingEnc = 0;
            $iter = new DirectoryIterator($vaultDir);
            foreach ($iter as $f) {
                // ★ (2026-11-01 07:24, 37차 기능 점검) 보관함이 만드는 이름(uuid.enc·uuid.meta.enc)만 셈 — 종전엔 원래 이름이 'backup.enc' 인 일반 파일을 해제해 두면 해제가 계속 거부됐음
                if (!$f->isDot() && preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(\.meta)?\.enc$/i', $f->getFilename())) {
                    $remainingEnc++;
                }
            }
            // ★ (2026-10-29 10:31, 20차 점검) 하위까지 지우는 경우(recursive)는 하위 폴더의 남은 암호화 파일도 확인 — 종전엔 맨 위만 봐서, 하위 보관함에서
            //   해제에 실패한 파일이 남아도 그 보관함 정보(.vault.json: 파일 이름·조각 정보)를 지워 남은 파일을 풀 수 없게 됐음(재현). 조각 폴더(*.chunks) 안은 맨 위와 같이 세지 않음
            if ($remainingEnc === 0 && !empty($input['recursive'])) {
                $rcIt = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($vaultDir, RecursiveDirectoryIterator::SKIP_DOTS), RecursiveIteratorIterator::SELF_FIRST);
                foreach ($rcIt as $rcF) {
                    // ★ (2026-10-29 15:35, 21차 재점검) 보관함 정보(.vault.json)가 있는 하위 보관함 바로 안의 것만 셈 — 20차엔 보관함 안의 일반 폴더에 든
                    //   '.enc' 이름의 보통 파일도 세어(화면이 풀 수 없는 파일) 전체 해제가 계속 거부됐음(재현)
                    if ($rcF->isFile() && preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(\.meta)?\.enc$/i', $rcF->getFilename()) && !preg_match('/\.chunks$/', basename($rcF->getPath()))   // ★ (2026-11-01 07:24, 37차 기능 점검) uuid 이름만
                        && is_file($rcF->getPath() . DIRECTORY_SEPARATOR . '.vault.json')) $remainingEnc++;
                }
            }
            
            if ($remainingEnc > 0) {
                $result = ['success' => false, 'error' => __('vault_remove_has_enc', '아직 암호화된 파일이 남아있습니다. 모든 파일을 복호화한 후 해제하세요.'), 'remaining' => $remainingEnc];
                break;
            }
            
            if (@unlink($vaultJsonPath)) {
                // recursive 옵션: 하위 sub-vault의 .vault.json도 삭제
                if (!empty($input['recursive'])) {
                    $rii = new RecursiveIteratorIterator(
                        new RecursiveDirectoryIterator($vaultDir, RecursiveDirectoryIterator::SKIP_DOTS),
                        RecursiveIteratorIterator::SELF_FIRST
                    );
                    foreach ($rii as $subItem) {
                        if ($subItem->isDir()) {
                            $subVaultJson = $subItem->getPathname() . DIRECTORY_SEPARATOR . '.vault.json';
                            if (file_exists($subVaultJson)) {
                                @unlink($subVaultJson);
                            }
                        }
                    }
                }
                $result = ['success' => true, 'message' => __('vault_removed', '암호화가 해제되었습니다.')];
            } else {
                $result = ['success' => false, 'error' => __('vault_err_remove_failed', '암호화 해제에 실패했습니다.')];
            }
            break;
        
        case 'vault_server_copy':
            // 같은 키의 vault 간 .enc 파일을 서버에서 직접 복사/이동 (복호화-재암호화 불필요)
            $auth->requireLogin();
            session_write_close();
            $storageId = (int)($input['storage_id'] ?? 0);
            $srcPath   = $input['src_path'] ?? '';
            $destPath  = $input['dest_path'] ?? '';
            $uuid      = $input['uuid'] ?? '';
            $copyMode  = $input['mode'] ?? 'copy'; // 'copy' or 'cut'
            
            if ((!is_scalar($srcPath) || (string)$srcPath === '') || (!is_scalar($destPath) || (string)$destPath === '') || empty($uuid)) {   // ★ (2026-11-01 11:37, 39차 점검) empty() 가 이름·경로 '0' 을 빈 값으로 봐 '0' 폴더·파일이 거부됐음 → 빈 글자일 때만
                $result = ['success' => false, 'error' => __('vault_err_missing_params')];
                break;
            }
            
            // 같은 경로 복사 차단
            if ($srcPath === $destPath) {
                $result = ['success' => false, 'error' => __('vault_err_same_location', '원본과 대상이 같은 위치입니다.')];   // ★ (2026-11-16 18:07, 260차 점검) 영어 고정 문구를 번역 문구로(판정 그대로)
                break;
            }
            
            // UUID 형식 검증
            if (!preg_match('/^[0-9a-f\-]{36}$/', $uuid)) {
                $result = ['success' => false, 'error' => 'Invalid UUID'];
                break;
            }
            
            // 권한 체크
            // ★ (2026-10-28 19:55, 6차 점검) 스토리지 권한도 확인 — 종전엔 폴더 권한(규칙이 없으면 통과)만 봐서 남의 홈 스토리지에 쓰거나 내려받을 수 있었음(재현)
            if (!$storage->checkPermission($storageId, 'can_read') || !$storage->checkFolderPermission($storageId, $srcPath, 'can_read') ||
                !$storage->checkPermission($storageId, 'can_write') || !$storage->checkFolderPermission($storageId, $destPath, 'can_write')) {
                $result = ['success' => false, 'error' => __('no_permission_dot')];
                break;
            }
            // ★ (2026-10-29 02:36, 16차) 잘라내기(cut)는 원본을 지우므로 원본 폴더의 쓰기·삭제 권한도(일반 이동 move 와 같은 기준) — 종전엔 읽기만 봤음
            if ($copyMode === 'cut' && (!$storage->checkPermission($storageId, 'can_delete') || !$storage->checkFolderPermission($storageId, $srcPath, 'can_write') || !$storage->checkFolderPermission($storageId, $srcPath, 'can_delete'))) {
                $result = ['success' => false, 'error' => __('no_permission_dot')];
                break;
            }
            
            // 경로 해석
            $_vpSrc  = resolveVaultPath($storage, $storageId, $srcPath);
            $_vpDest = resolveVaultPath($storage, $storageId, $destPath);
            if (!$_vpSrc || !$_vpDest) {
                $result = ['success' => false, 'error' => __('api_err_storage_not_found')];
                break;
            }
            $srcDir  = $_vpSrc['vaultDir'];
            $destDir = $_vpDest['vaultDir'];
            
            // vault 폴더인지 확인
            if (!file_exists($srcDir . DIRECTORY_SEPARATOR . '.vault.json') ||
                !file_exists($destDir . DIRECTORY_SEPARATOR . '.vault.json')) {
                $result = ['success' => false, 'error' => __('vault_err_not_vault')];
                break;
            }
            
            // ★ (2026-10-29 21:45, 24차 점검) 복사(copy)는 늘어나는 만큼 용량 확인(보관함 업로드 vault_upload·일반 복사와 같게) — 종전엔 사용량만 더하고 확인은 없어 한도를 넘겨 계속 복사됐음
            if ($copyMode !== 'cut') {
                $vqSz = function ($p) { if (is_file($p)) return (int)@filesize($p); $t = 0; if (is_dir($p)) foreach (new DirectoryIterator($p) as $f) { if (!$f->isDot() && $f->isFile()) $t += (int)$f->getSize(); } return $t; };
                $vqNeed = 0;
                foreach (['.enc', '.meta.enc', '.chunks'] as $vqSuf) {
                    $vqNeed += $vqSz($srcDir . DIRECTORY_SEPARATOR . $uuid . $vqSuf) - $vqSz($destDir . DIRECTORY_SEPARATOR . $uuid . $vqSuf);
                }
                for ($vqLi = 0; is_file($srcDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vqLi); $vqLi++) { $vqNeed += $vqSz($srcDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vqLi) - $vqSz($destDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vqLi); }   // ★ (2026-11-09 12:01, 57차 Z09-1) 아래에서 옛 청크 형식 조각도 복사하므로 용량 확인에도 셈
                if ($vqNeed > 0) {
                    $vqChk = $fileManager->checkQuotaPublic($storageId, $vqNeed);
                    if (empty($vqChk['allowed'])) { $result = ['success' => false, 'error' => $vqChk['error'] ?? __('quota_exceeded', '용량이 부족합니다.')]; break; }
                }
            }
            
            $copied = 0;
            $filesToDelete = []; // cut 모드: 복사 성공 후 원본 삭제
            // ★ (2026-10-29 09:14, 20차) 하나라도 복사에 실패하면 원본은 그대로 두고, 대상에 만든 일부 사본은 지우고 실패로 답함 — 종전엔 청크 하나가 실패해도
            //   .meta.enc 를 지워 원본 보관함 목록에서 파일이 사라지고 대상에는 깨진 항목이 남았음
            $vcFailed = false;
            $vcMade = [];   // 대상에 새로 만든 것(실패 시 되돌림)
            // ★ (2026-10-29 15:35, 21차 재점검) 대상에 같은 uuid 사본이 이미 있으면(같은 파일을 두 번 복사) 그 파일은 되돌리기에서 지우지 않고,
            //   사용량은 늘어난 만큼만 — 20차엔 덮어쓴 파일도 '새로 만든 것' 으로 보아 실패 때 기존 사본을 지웠고(재현: 조각 실패 → 기존 사본 깨짐),
            //   성공 때도 전체 크기를 또 더해 사용량이 부풀었음(재현: 두 번째 복사 +6200)
            $vcPre = [];    // 대상 경로 => 복사 전 크기(원래 있던 파일만)
            $vcNote = function (string $p) use (&$vcPre) { clearstatcache(true, $p); if (is_file($p)) $vcPre[$p] = (int)@filesize($p); };
            
            // 1) uuid.enc (단일 암호화 파일)
            $encFile = $srcDir . DIRECTORY_SEPARATOR . $uuid . '.enc';
            if (file_exists($encFile)) {
                $destFile = $destDir . DIRECTORY_SEPARATOR . $uuid . '.enc';
                $vcNote($destFile);
                if (@copy($encFile, $destFile)) {
                    $copied++; $vcMade[] = $destFile;
                    if ($copyMode === 'cut') $filesToDelete[] = $encFile;
                } else { $vcFailed = true; }
            }

            // ★ (2026-11-09 12:01, 57차 Z09-1) 1-2) 옛 청크 형식 uuid.enc.0, .enc.1 … 도 복사(잘라내기면 지울 목록에) — 종전엔 메타만 옮겨져 대상엔 안 보이고 원본엔 메타 없는 조각만 남아 파일이 사라진 것처럼 됐음(재현). 실패하면 아래 되돌리기
            if (!$vcFailed && is_file($srcDir . DIRECTORY_SEPARATOR . $uuid . '.enc.0')) {
                $vcLegacyOk = true;
                for ($vcLi = 0; is_file($srcDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vcLi); $vcLi++) {
                    $vcLsrc = $srcDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vcLi;
                    $vcLdst = $destDir . DIRECTORY_SEPARATOR . $uuid . '.enc.' . $vcLi;
                    $vcNote($vcLdst);
                    if (@copy($vcLsrc, $vcLdst)) {
                        $vcMade[] = $vcLdst;
                        if ($copyMode === 'cut') $filesToDelete[] = $vcLsrc;
                    } else { $vcLegacyOk = false; break; }
                }
                if ($vcLegacyOk) $copied++; else $vcFailed = true;
            }

            // 2) uuid.meta.enc (메타데이터)
            $metaFile = $srcDir . DIRECTORY_SEPARATOR . $uuid . '.meta.enc';
            if (!$vcFailed && file_exists($metaFile)) {
                $destMeta = $destDir . DIRECTORY_SEPARATOR . $uuid . '.meta.enc';
                $vcNote($destMeta);
                if (@copy($metaFile, $destMeta)) {
                    $copied++; $vcMade[] = $destMeta;
                    if ($copyMode === 'cut') $filesToDelete[] = $metaFile;
                } else { $vcFailed = true; }
            }
            
            // 3) uuid.chunks/ (청크 폴더)
            $chunksDir = $srcDir . DIRECTORY_SEPARATOR . $uuid . '.chunks';
            if (!$vcFailed && is_dir($chunksDir)) {
                $destChunks = $destDir . DIRECTORY_SEPARATOR . $uuid . '.chunks';
                $vcChunksNew = !is_dir($destChunks);
                if ($vcChunksNew) @mkdir($destChunks, 0755, true);
                $chunkCopied = true;
                $vcChunkFiles = [];
                $chunkIter = new DirectoryIterator($chunksDir);
                foreach ($chunkIter as $cf) {
                    if ($cf->isDot()) continue;
                    $vcTarget = $destChunks . DIRECTORY_SEPARATOR . $cf->getFilename();
                    $vcNote($vcTarget);
                    if (@copy($cf->getPathname(), $vcTarget)) { $vcChunkFiles[] = $vcTarget; }
                    else { $chunkCopied = false; }
                }
                if ($chunkCopied) {
                    $copied++;
                    if ($copyMode === 'cut') $filesToDelete[] = $chunksDir;
                } else {
                    $vcFailed = true;
                }
                foreach ($vcChunkFiles as $vcf) $vcMade[] = $vcf;
                if ($vcChunksNew) $vcMade[] = $destChunks;
            }
            
            if ($vcFailed) {
                // 대상에 만든 것만 되돌림(파일 먼저, 새로 만든 청크 폴더는 마지막에)
                foreach ($vcMade as $vm) { if (is_file($vm) && !isset($vcPre[$vm])) @unlink($vm); }   // 원래 있던 사본은 남김
                foreach ($vcMade as $vm) { if (is_dir($vm)) @rmdir($vm); }
                $result = ['success' => false, 'error' => __('api_err_copy_failed', '파일 복사에 실패했습니다.')];
                break;
            }
            
            // ★ (2026-10-29 11:08, 20차 점검) 복사(copy)는 같은 스토리지에 데이터가 늘어나므로 사용량에 더함 — 종전엔 반영하지 않았음. 잘라내기는 같은 스토리지 안 이동이라 변화 없음
            if ($copied > 0 && $copyMode !== 'cut') {
                $vcAdd = 0;
                foreach ($vcMade as $vm) { if (is_file($vm)) { clearstatcache(true, $vm); $vcAdd += (int)@filesize($vm) - (int)($vcPre[$vm] ?? 0); } }
                if ($vcAdd > 0) $storage->updateUsedSize($storageId, $vcAdd);
            }
            
            // cut 모드: 모든 복사 성공 후 원본 삭제
            if ($copied > 0 && $copyMode === 'cut') {
                foreach ($filesToDelete as $delPath) {
                    if (is_dir($delPath)) {
                        // 청크 폴더 삭제
                        $di = new DirectoryIterator($delPath);
                        foreach ($di as $df) { if (!$df->isDot()) @unlink($df->getPathname()); }
                        @rmdir($delPath);
                    } else {
                        @unlink($delPath);
                    }
                }
            }
            
            if ($copied > 0) {
                $result = ['success' => true, 'copied' => $copied];
            } else {
                $result = ['success' => false, 'error' => 'No files found for UUID: ' . $uuid];
            }
            break;
        
        case 'vault_migrate_legacy':
            // 레거시 concat .enc 파일을 새 .chunks/ 형식으로 분할
            $auth->requireLogin();
            session_write_close();
            $storageId = (int)($input['storage_id'] ?? 0);
            $path = $input['path'] ?? '';
            $uuid = $input['uuid'] ?? '';
            $chunkSize = (int)($input['chunk_size'] ?? 5242880); // 기본 5MB
            // ★ (2026-10-29 02:36, 16차) 권한 확인 — 종전엔 로그인만 봐서 읽기만 되는 사용자도 남의 암호화 파일을 쪼개고 원본을 지울 수 있었음.
            //   원본(.enc)을 지우고 새 형식으로 다시 쓰므로 스토리지·폴더 쓰기 권한. 조각 크기도 64KB~64MB 로 제한(1바이트면 파일 수천만 개)
            if (!$storage->checkPermission($storageId, 'can_write') || !$storage->checkFolderPermission($storageId, $path, 'can_write')) {
                $result = ['success' => false, 'error' => __('no_write_permission', '쓰기 권한이 없습니다.')];
                break;
            }
            if ($chunkSize < 65536 || $chunkSize > 67108864) {
                $result = ['success' => false, 'error' => __('api_err_invalid_request', '잘못된 요청입니다.')];
                break;
            }
            
            if (empty($uuid) || !preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/', $uuid)) {
                $result = ['success' => false, 'error' => 'Invalid UUID'];
                break;
            }
            
            $_vp = resolveVaultPath($storage, $storageId, $path);
            if (!$_vp) {
                $result = ['success' => false, 'error' => __('api_err_storage_not_found')];
                break;
            }
            $basePath = $_vp['basePath'];
            $vaultDir = $_vp['vaultDir'];
            $encFile = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.enc';
            
            if (!file_exists($encFile)) {
                $result = ['success' => false, 'error' => __('api_err_file_not_found', '파일을 찾을 수 없습니다.')];
                break;
            }
            
            $fileSize = filesize($encFile);
            // 암호화된 청크 크기 = IV(12) + 원본 청크(chunkSize) + GCM tag(16)
            $encChunkSize = 12 + $chunkSize + 16;
            
            // 단일 모드 파일은 마이그레이션 불필요 (encChunkSize 이하)
            if ($fileSize <= $encChunkSize) {
                $result = ['success' => true, 'message' => 'File is already single-mode, no migration needed', 'migrated' => false];
                break;
            }
            
            // .chunks 디렉토리 생성
            $chunkDir = $vaultDir . DIRECTORY_SEPARATOR . $uuid . '.chunks';
            if (is_dir($chunkDir)) {
                $result = ['success' => false, 'error' => 'Chunks directory already exists'];
                break;
            }
            
            if (!@mkdir($chunkDir, 0755, true)) {
                $result = ['success' => false, 'error' => 'Failed to create chunks directory'];
                break;
            }
            
            // concat 파일을 encChunkSize 단위로 분할
            $fp = fopen($encFile, 'rb');
            if (!$fp) {
                @rmdir($chunkDir);
                $result = ['success' => false, 'error' => 'Failed to open encrypted file'];
                break;
            }
            
            $chunkIdx = 0;
            $totalWritten = 0;
            $migrationOk = true;
            
            while (!feof($fp)) {
                $data = fread($fp, $encChunkSize);
                if ($data === false || strlen($data) === 0) break;
                
                // 최소 크기 검증 (IV + GCM tag + 1byte)
                if (strlen($data) < 29) {
                    // 끝에 남은 잔여 바이트 — 무시
                    break;
                }
                
                $chunkPath = $chunkDir . DIRECTORY_SEPARATOR . $chunkIdx;
                if (file_put_contents($chunkPath, $data) === false) {
                    $migrationOk = false;
                    break;
                }
                
                $totalWritten += strlen($data);
                $chunkIdx++;
            }
            fclose($fp);
            
            if (!$migrationOk || $chunkIdx === 0) {
                // 실패 시 정리
                $iter = new DirectoryIterator($chunkDir);
                foreach ($iter as $f) {
                    if (!$f->isDot()) @unlink($f->getPathname());
                }
                @rmdir($chunkDir);
                $result = ['success' => false, 'error' => 'Migration failed during chunk split'];
                break;
            }
            
            // 원본 concat .enc 삭제
            if (!@unlink($encFile)) {
                // .enc 삭제 실패해도 .chunks는 유지 (수동 정리 필요)
                $result = ['success' => true, 'warning' => 'Chunks created but failed to delete original .enc', 'chunks' => $chunkIdx, 'migrated' => true];
                break;
            }
            
            $result = ['success' => true, 'migrated' => true, 'chunks' => $chunkIdx, 'original_size' => $fileSize];
            break;
        
        case 'vault_preview_temp':
            // 복호화 파일을 vault 폴더 내 uuid.chunks/ 에 저장
            $auth->requireLogin();
            session_write_close();
            ignore_user_abort(false); // 클라이언트 연결 끊기면 PHP도 중단
            $storageId = (int)($_POST['storage_id'] ?? 0);
            $path = $_POST['path'] ?? '';
            
            // 폴더 읽기 권한 체크
            // ★ (2026-10-28 19:55, 6차 점검) 스토리지 권한도 확인 — 종전엔 폴더 권한(규칙이 없으면 통과)만 봐서 남의 홈 스토리지에 쓰거나 내려받을 수 있었음(재현)
            if (!$storage->checkPermission($storageId, 'can_read') || !$storage->checkFolderPermission($storageId, $path, 'can_read')) {
                $result = ['success' => false, 'error' => __('no_permission_dot', '권한이 없습니다.')];
                break;
            }
            
            $originalName = $_POST['original_name'] ?? '';
            $tempId = $_POST['temp_id'] ?? '';  // uuid (미리보기용 임시 ID)
            $chunkMode = $_POST['chunk_mode'] ?? '0';
            $chunkIndex = (int)($_POST['chunk_index'] ?? 0);
            $isLast = ($_POST['is_last'] ?? '0') === '1';
            
            if ((!is_scalar($originalName) || (string)$originalName === '') || empty($tempId)) {   // ★ (2026-11-01 11:37, 39차 점검) empty() 가 이름·경로 '0' 을 빈 값으로 봐 '0' 폴더·파일이 거부됐음 → 빈 글자일 때만
                $result = ['success' => false, 'error' => __('api_err_missing_params', '필수 매개변수가 누락되었습니다.')];
                break;
            }
            
            if (!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/', $tempId)) {
